import{m as e}from"./merge-BmcoofH2.js";const t={"unternehmensfuehrung-ueberblick":[{type:"text",level:1,de:{q:"Wie heißt die oberste Führungsebene eines Unternehmens (z. B. Geschäftsführung)? (englischer Begriff)",a:["Topmanagement","Top-Management","Top Management"],e:"Topmanagement (Geschäftsführung) → Middle Management (Abteilungsleitung) → Lower Management (Team-/Gruppenleitung)."},en:{q:"What is the highest management level of a company called (e.g. the managing directors)?",a:["top management"],e:"Top management (managing directors) → middle management (heads of department) → lower management (team leaders)."},hu:{q:"Hogy hívják egy vállalat legfelső vezetési szintjét (pl. ügyvezetés)?",a:["felső vezetés","topmenedzsment","top management"],e:"Felső vezetés (ügyvezetés) → középvezetés (osztályvezetés) → alsó vezetés (csapatvezetés)."}},{type:"text",level:2,de:{q:"Wofür steht die Abkürzung CEO?",a:["Chief Executive Officer","Geschäftsführer","Geschäftsführerin"],e:"CEO = Chief Executive Officer (Geschäftsführung). CSO = Vertriebsleitung, COO = laufender Geschäftsbetrieb."},en:{q:"What does the abbreviation CEO stand for?",a:["Chief Executive Officer"],e:"CEO = Chief Executive Officer. CSO = Chief Sales Officer, COO = Chief Operating Officer."},hu:{q:"Mit jelent a CEO rövidítés?",a:["Chief Executive Officer","vezérigazgató","ügyvezető"],e:"CEO = Chief Executive Officer (vezérigazgató). CSO = értékesítési vezető, COO = operatív vezető."}},{type:"mc",level:3,correctIndex:3,de:{q:"Welche Zuordnung von Managementebene und Aufgabe ist richtig?",o:["Normativ – tägliche Schichteinteilung der Mitarbeitenden","Operativ – Unternehmensvision festlegen","Strategisch – Werte, Normen und Leitbild des Unternehmens formulieren","Strategisch – langfristige Unternehmensstrategie planen"],e:"Normativ = Vision, Werte, Leitbild. Strategisch = langfristige Strategien. Operativ = konkrete Umsetzung im Alltag."},en:{q:"Which pairing of management level and task is correct?",o:["Normative – daily shift planning for the staff","Operational – setting the company vision","Strategic – writing the values, norms and mission statement","Strategic – planning the long-term company strategy"],e:"Normative = vision, values, mission statement. Strategic = long-term strategies. Operational = concrete implementation day to day."},hu:{q:"Melyik párosítás helyes a menedzsmentszint és a feladat között?",o:["Normatív – a munkavállalók napi műszakbeosztása","Operatív – a vállalati vízió meghatározása","Stratégiai – értékek, normák és küldetésnyilatkozat megfogalmazása","Stratégiai – a hosszú távú vállalati stratégia megtervezése"],e:"Normatív = vízió, értékek, küldetésnyilatkozat. Stratégiai = hosszú távú stratégiák. Operatív = konkrét megvalósítás a mindennapokban."}}],"normatives-management":[{type:"text",level:1,de:{q:"Wie nennt man die freiwillige Verantwortung eines Unternehmens für Gesellschaft und Umwelt? (Abkürzung)",a:["CSR","Corporate Social Responsibility"],e:"CSR = Corporate Social Responsibility – Werte müssen sich in konkreten Maßnahmen zeigen."},en:{q:"What do you call a company's voluntary responsibility for society and the environment? (Abbreviation)",a:["CSR","corporate social responsibility"],e:"CSR = corporate social responsibility – values must show in concrete actions."},hu:{q:"Hogyan nevezzük a vállalat önkéntes felelősségvállalását a társadalom és a környezet iránt? (Rövidítés)",a:["CSR","vállalati társadalmi felelősségvállalás"],e:"CSR = vállalati társadalmi felelősségvállalás – az értékeknek konkrét intézkedésekben kell megmutatkozniuk."}},{type:"text",level:2,de:{q:"Nach welcher Formel sollen Ziele formuliert werden – spezifisch, messbar, attraktiv, realistisch, terminiert?",a:["SMART","SMART-Formel"],e:"SMART-Ziele sind spezifisch, messbar, attraktiv, realistisch und terminiert."},en:{q:"Which formula should goals follow – specific, measurable, attractive, realistic, time-bound?",a:["SMART","SMART formula"],e:"SMART goals are specific, measurable, attractive, realistic and time-bound."},hu:{q:"Melyik képlet szerint kell a célokat megfogalmazni – specifikus, mérhető, vonzó, reális, határidős?",a:["SMART","SMART-képlet"],e:"A SMART célok specifikusak, mérhetők, vonzók, reálisak és határidősek."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Unternehmen will gleichzeitig die Personalkosten senken und alle Arbeitsplätze sichern. Welche Zielbeziehung liegt vor?",o:["Zielneutralität","Zielkomplementarität","Zielkonflikt","Zielharmonie durch Operationalisierung"],e:"Personalkosten senken erschwert es, alle Arbeitsplätze zu halten – die Ziele behindern einander: Zielkonflikt (Zielkonkurrenz)."},en:{q:"A company wants to cut staff costs and secure all jobs at the same time. What relationship between the goals is this?",o:["Goal neutrality","Goal complementarity","Goal conflict","Goal harmony through operationalisation"],e:"Cutting staff costs makes it harder to keep all jobs – the goals hinder each other: goal conflict."},hu:{q:"Egy vállalat egyszerre szeretné csökkenteni a személyi költségeket és megtartani az összes munkahelyet. Milyen célkapcsolatról van szó?",o:["Célsemlegesség","Célkomplementaritás","Célkonfliktus","Célharmónia operacionalizálás révén"],e:"A személyi költségek csökkentése megnehezíti az összes munkahely megtartását – a célok akadályozzák egymást: célkonfliktus."}}],"strategisches-operatives-management":[{type:"text",level:1,de:{q:"Wie heißt die Analyse, die Stärken, Schwächen, Chancen und Risiken zusammenführt?",a:["SWOT-Analyse","SWOT","SWOT Analyse"],e:"SWOT = Strengths, Weaknesses (intern), Opportunities, Threats (extern)."},en:{q:"What is the analysis called that brings together strengths, weaknesses, opportunities and threats?",a:["SWOT analysis","SWOT"],e:"SWOT = strengths, weaknesses (internal), opportunities, threats (external)."},hu:{q:"Hogy hívják azt az elemzést, amely összekapcsolja az erősségeket, gyengeségeket, lehetőségeket és veszélyeket?",a:["SWOT-elemzés","SWOT","SWOT elemzés"],e:"SWOT = erősségek, gyengeségek (belső), lehetőségek, veszélyek (külső)."}},{type:"text",level:2,de:{q:"Wie heißt der Kreislauf zur ständigen Verbesserung mit den Schritten Plan – Do – Check – Act?",a:["PDCA","PDCA-Zyklus","Deming-Kreis","Demingkreis"],e:"Der PDCA-Zyklus (Deming-Kreis): Plan (Ziele), Do (umsetzen), Check (kontrollieren), Act (anpassen)."},en:{q:"What is the cycle for continuous improvement with the steps plan – do – check – act called?",a:["PDCA","PDCA cycle","Deming cycle"],e:"The PDCA cycle (Deming cycle): plan (goals), do (implement), check (monitor), act (adjust)."},hu:{q:"Hogy hívják a folyamatos fejlesztés körforgását a Plan – Do – Check – Act lépésekkel?",a:["PDCA","PDCA-ciklus","Deming-kör","Deming kör"],e:"A PDCA-ciklus (Deming-kör): Plan (célok), Do (megvalósítás), Check (ellenőrzés), Act (kiigazítás)."}},{type:"number",level:3,value:2.5,tol:.01,de:{q:"Loopys Marktanteil bei Fruchtbonbons beträgt 15 %, der stärkste Konkurrent hält 6 %. Wie hoch ist der relative Marktanteil? (auf 1 Kommastelle)",e:"Relativer Marktanteil = eigener Marktanteil ÷ Marktanteil des stärksten Konkurrenten = 15 ÷ 6 = 2,5. Werte über 1 bedeuten Marktführerschaft."},en:{q:"Loopy's market share for fruit sweets is 15%, the strongest competitor holds 6%. What is the relative market share? (1 decimal place)",e:"Relative market share = own market share ÷ market share of the strongest competitor = 15 ÷ 6 = 2.5. Values above 1 mean market leadership."},hu:{q:"Loopy piaci részesedése a gyümölcsös cukorkáknál 15%, a legerősebb versenytársé 6%. Mekkora a relatív piaci részesedés? (1 tizedesjegyre)",e:"Relatív piaci részesedés = saját részesedés ÷ a legerősebb versenytárs részesedése = 15 ÷ 6 = 2,5. Az 1 feletti érték piacvezetést jelent."}}],"organisieren-und-fuehren":[{type:"text",level:1,de:{q:"Wie nennt man die grafische Darstellung der Aufbauorganisation eines Unternehmens?",a:["Organigramm","Organisationsplan"],e:"Das Organigramm zeigt Stellen, Abteilungen und Weisungswege eines Unternehmens."},en:{q:"What do you call the graphic picture of a company's organisational structure?",a:["organisation chart","organization chart","organigram","org chart"],e:"The organisation chart shows positions, departments and chains of command in a company."},hu:{q:"Hogyan nevezzük egy vállalat szervezeti felépítésének grafikus ábrázolását?",a:["szervezeti ábra","organigram","organigramm"],e:"A szervezeti ábra mutatja a munkaköröket, osztályokat és utasítási utakat."}},{type:"text",level:2,de:{q:"Wie nennt man eine Stelle, die die Leitung berät und unterstützt, aber keine Weisungsbefugnis hat (z. B. Assistenz, Controlling)?",a:["Stabsstelle","Stabstelle","Stab"],e:"Stabsstellen beraten und unterstützen – Weisungen erteilen dürfen sie nicht."},en:{q:"What do you call a position that advises and supports management but has no authority to give instructions (e.g. assistant, controlling)?",a:["staff position","staff function","staff unit"],e:"Staff positions advise and support – they may not give instructions."},hu:{q:"Hogyan nevezzük azt a munkakört, amely tanácsot ad és támogatja a vezetést, de nincs utasítási joga (pl. asszisztens, kontrolling)?",a:["törzskari munkakör","törzskar","stáb"],e:"A törzskari munkakörök tanácsot adnak és támogatnak – utasítást nem adhatnak."}},{type:"mc",level:3,correctIndex:1,de:{q:"Eine neue Mitarbeiterin ist motiviert, kann die Aufgabe aber noch nicht. Welcher Führungsstil passt laut Reifegradmodell (Hersey/Blanchard) am besten?",o:["Delegating – Aufgaben ohne Erklärung übergeben","Selling – Aufgaben erklären und überzeugen","Participating – an Entscheidungen beteiligen","Laissez-faire – gar nicht eingreifen"],e:"Geringe Fähigkeit, aber Motivation = geringe bis mittlere Reife → Selling: Aufgaben erklären, stark mitarbeiterbezogen führen."},en:{q:"A new employee is motivated but cannot do the task yet. According to the maturity model (Hersey/Blanchard), which leadership style fits best?",o:["Delegating – hand over tasks without explanation","Selling – explain tasks and convince","Participating – involve in decisions","Laissez-faire – don't step in at all"],e:"Low ability but motivated = low to medium maturity → selling: explain tasks, lead in a strongly people-focused way."},hu:{q:"Egy új munkatárs motivált, de még nem tudja elvégezni a feladatot. Az érettségi modell (Hersey/Blanchard) szerint melyik vezetési stílus illik hozzá legjobban?",o:["Delegating – feladatok átadása magyarázat nélkül","Selling – a feladatok elmagyarázása és meggyőzés","Participating – bevonás a döntésekbe","Laissez-faire – egyáltalán nem beavatkozni"],e:"Alacsony képesség, de motiváció = alacsony–közepes érettség → selling: a feladatok elmagyarázása, erősen emberközpontú vezetés."}}]},n={personalbedarfsplanung:[{type:"text",level:1,de:{q:"Bei welchem Sozialversicherungsträger muss ein neuer Mitarbeiter angemeldet werden? (Abkürzung)",a:["ÖGK","Österreichische Gesundheitskasse","OEGK"],e:"Neue Mitarbeiter werden vor Arbeitsbeginn bei der ÖGK (Österreichische Gesundheitskasse) angemeldet; zusätzlich gibt es einen Dienstzettel."},en:{q:"With which social insurance institution must a new employee be registered in Austria? (Abbreviation)",a:["ÖGK","OEGK","Austrian Health Insurance Fund"],e:"New employees are registered with the ÖGK (Austrian Health Insurance Fund) before they start; they also receive a Dienstzettel (written statement of terms)."},hu:{q:"Melyik társadalombiztosítási intézménynél kell Ausztriában bejelenteni egy új munkatársat? (Rövidítés)",a:["ÖGK","OEGK","Osztrák Egészségpénztár"],e:"Az új munkatársakat a munka megkezdése előtt be kell jelenteni az ÖGK-nál (Osztrák Egészségpénztár); emellett Dienstzettelt (írásos munkaszerződési kivonatot) kapnak."}},{type:"mc",level:2,correctIndex:2,de:{q:"Eine Mitarbeiterin lernt neue Software in einem Abendkurs außerhalb des Betriebs. Welche PE-Methode ist das?",o:["Into the Job","On the Job","Off the Job","Out of the Job"],e:"Off the Job = Weiterbildung außerhalb des Arbeitsplatzes (Kurse, Seminare). Into = Einarbeitung, On = am Arbeitsplatz, Out of = Ruhestandsvorbereitung."},en:{q:"An employee learns new software in an evening course outside the company. Which staff development method is this?",o:["Into the job","On the job","Off the job","Out of the job"],e:"Off the job = training away from the workplace (courses, seminars). Into = induction, on = at the workplace, out of = preparing for retirement."},hu:{q:"Egy munkatárs esti tanfolyamon, a vállalaton kívül tanul új szoftvert. Melyik személyzetfejlesztési módszer ez?",o:["Into the job","On the job","Off the job","Out of the job"],e:"Off the job = képzés a munkahelyen kívül (tanfolyamok, szemináriumok). Into = betanítás, on = munkahelyen, out of = nyugdíjra való felkészítés."}},{type:"number",level:3,value:750,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy zahlt einer Mitarbeiterin 3.500 € brutto, 14-mal im Jahr. Wie viel zahlt Loopy pro Jahr in die Mitarbeitervorsorgekasse (1,53 %)? (auf ganze € runden)",e:"Jahresbrutto = 3.500 × 14 = 49.000 €. Abfertigung neu: 49.000 × 1,53 % = 749,70 € ≈ 750 €."},en:{q:"Loopy pays an employee €3,500 gross, 14 times a year. How much does Loopy pay into the employee severance fund (1.53%) per year? (round to whole €)",e:"Annual gross = 3,500 × 14 = €49,000. Severance fund: 49,000 × 1.53% = €749.70 ≈ €750."},hu:{q:"Loopy egy munkatársnak bruttó 3500 €-t fizet, évente 14-szer. Mennyit fizet Loopy évente a munkavállalói végkielégítési pénztárba (1,53%)? (egész €-ra kerekítve)",e:"Éves bruttó = 3500 × 14 = 49 000 €. Végkielégítési pénztár: 49 000 × 1,53% = 749,70 € ≈ 750 €."}}],personaleinsatzgestaltung:[{type:"number",level:1,value:25,tol:0,unit:{de:"Arbeitstage",en:"working days",hu:"munkanap"},de:{q:"Wie viele Arbeitstage Urlaub stehen einem Arbeitnehmer in Österreich pro Jahr zu (Grundanspruch)?",e:"25 Arbeitstage (5 Wochen); nach 25 Dienstjahren 30 Arbeitstage (6 Wochen)."},en:{q:"How many working days of holiday is an employee in Austria entitled to per year (basic entitlement)?",e:"25 working days (5 weeks); after 25 years of service 30 working days (6 weeks)."},hu:{q:"Hány munkanap szabadság jár egy munkavállalónak Ausztriában évente (alapjogosultság)?",e:"25 munkanap (5 hét); 25 év szolgálat után 30 munkanap (6 hét)."}},{type:"text",level:2,de:{q:"Ein Mitarbeiter bekommt zusätzlich Planungs- und Kontrollaufgaben, also mehr Verantwortung. Wie heißt diese Maßnahme?",a:["Jobenrichment","Job Enrichment","Job-Enrichment","Arbeitsbereicherung"],e:"Jobenrichment = qualitative Erweiterung (mehr Verantwortung). Jobenlargement = mehr Aufgaben mit gleicher Anforderung. Jobrotation = Arbeitsplatzwechsel."},en:{q:"An employee is additionally given planning and control tasks, i.e. more responsibility. What is this measure called?",a:["job enrichment","jobenrichment"],e:"Job enrichment = qualitative expansion (more responsibility). Job enlargement = more tasks at the same level. Job rotation = changing workplaces."},hu:{q:"Egy munkatárs tervezési és ellenőrzési feladatokat is kap, vagyis több felelősséget. Hogy hívják ezt az intézkedést?",a:["munkagazdagítás","job enrichment","jobenrichment"],e:"Munkagazdagítás (job enrichment) = minőségi bővítés (több felelősség). Munkakörbővítés (job enlargement) = több azonos szintű feladat. Munkakör-rotáció = munkahelyváltás."}},{type:"number",level:3,value:165,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein Angestellter hat einen Stundenlohn von 22 € und macht 5 Überstunden mit 50 % Zuschlag. Wie viel € bekommt er für die Überstunden insgesamt?",e:"Überstundenlohn = 22 × 1,5 = 33 € pro Stunde. 5 × 33 = 165 €."},en:{q:"An employee earns €22 per hour and works 5 hours of overtime with a 50% surcharge. How much does he get for the overtime in total?",e:"Overtime rate = 22 × 1.5 = €33 per hour. 5 × 33 = €165."},hu:{q:"Egy alkalmazott órabére 22 €, és 5 túlórát dolgozik 50%-os pótlékkal. Összesen hány €-t kap a túlórákért?",e:"Túlóradíj = 22 × 1,5 = 33 € óránként. 5 × 33 = 165 €."}}],personalbeurteilung:[{type:"text",level:1,de:{q:"Wie heißt eine Beurteilung, bei der Vorgesetzte, Kollegen, Mitarbeiter und man selbst Feedback geben?",a:["360°-Feedback","360-Grad-Feedback","360 Grad Feedback","360°","360 Feedback"],e:"Beim 360°-Feedback beurteilen Personen aus allen Richtungen – oben, gleichrangig, unten und man selbst."},en:{q:"What is an appraisal called in which managers, colleagues, staff and you yourself give feedback?",a:["360° feedback","360 degree feedback","360-degree feedback","360 feedback","360°"],e:"In 360° feedback people from all directions give an assessment – above, same level, below and yourself."},hu:{q:"Hogy hívják azt az értékelést, amelyben a felettesek, kollégák, beosztottak és saját magunk is visszajelzést adunk?",a:["360°-os visszajelzés","360 fokos visszajelzés","360°","360 feedback","360°-feedback"],e:"A 360°-os visszajelzésnél minden irányból értékelnek – felülről, azonos szintről, alulról és saját magunk."}},{type:"text",level:2,de:{q:"Ein Chef bewertet eine Mitarbeiterin nur nach ihrer letzten, sehr guten Woche. Wie heißt dieser Beurteilungsfehler?",a:["Recency-Effekt","Recency Effekt","Recency-Effect","Nikolaus-Effekt","Nikolauseffekt"],e:"Recency-Effekt: Die jüngsten Ereignisse überlagern den ganzen Beurteilungszeitraum."},en:{q:"A manager rates an employee only on her last, very good week. What is this appraisal error called?",a:["recency effect","recency bias"],e:"Recency effect: the most recent events outweigh the whole appraisal period."},hu:{q:"Egy főnök egy munkatársat csak az utolsó, nagyon jó hete alapján értékel. Hogy hívják ezt az értékelési hibát?",a:["recency-hatás","recency hatás","frissességi hatás","recency effect"],e:"Recency-hatás: a legutóbbi események elnyomják a teljes értékelési időszakot."}},{type:"number",level:3,value:32,tol:.05,unit:{de:"%",en:"%",hu:"%"},de:{q:"Loopys Fabrik hat Personalkosten von 416.000 € bei einer Betriebsleistung von 1.300.000 €. Wie hoch ist die Personalintensität in %?",e:"Personalintensität = Personalkosten × 100 ÷ Betriebsleistung = 416.000 × 100 ÷ 1.300.000 = 32 %."},en:{q:"Loopy's factory has staff costs of €416,000 and an operating output of €1,300,000. What is the personnel intensity in %?",e:"Personnel intensity = staff costs × 100 ÷ operating output = 416,000 × 100 ÷ 1,300,000 = 32%."},hu:{q:"Loopy gyárának személyi költségei 416 000 €, üzemi teljesítménye 1 300 000 €. Mekkora a személyi intenzitás %-ban?",e:"Személyi intenzitás = személyi költségek × 100 ÷ üzemi teljesítmény = 416 000 × 100 ÷ 1 300 000 = 32%."}}],produktionsbetriebe:[{type:"text",level:1,de:{q:"Zu welchem Wirtschaftssektor gehören Produktionsbetriebe? (primär, sekundär oder tertiär)",a:["sekundär","sekundärer Sektor","sekundaer","Sekundärsektor"],e:"Produktionsbetriebe (Industrie, Gewerbe) gehören zum sekundären Sektor – rund 28 % des BIP und etwa 70 % der Exporte."},en:{q:"Which economic sector do production companies belong to? (primary, secondary or tertiary)",a:["secondary","secondary sector"],e:"Production companies (industry, trade) belong to the secondary sector – about 28% of GDP and around 70% of exports."},hu:{q:"Melyik gazdasági szektorhoz tartoznak a termelő vállalatok? (primer, szekunder vagy tercier)",a:["szekunder","szekunder szektor","másodlagos","ipar"],e:"A termelő vállalatok (ipar, kisipar) a szekunder szektorhoz tartoznak – a GDP kb. 28%-a és az export kb. 70%-a."}},{type:"mc",level:2,correctIndex:0,de:{q:"Welches Merkmal passt zur Industrie, nicht zum Gewerbe?",o:["Anlagenintensiv und stark automatisiert","Der Inhaber arbeitet selbst mit","Arbeitsintensive Einzelanfertigung","Wenige Mitarbeiter, kleine Stückzahlen"],e:"Industrie: anlagenintensiv, Management, groß, automatisiert, Massenfertigung. Gewerbe: arbeitsintensiv, Inhaber, klein."},en:{q:"Which feature belongs to industry rather than to a trade business?",o:["Capital-intensive and highly automated","The owner works alongside the staff","Labour-intensive one-off production","Few employees, small quantities"],e:"Industry: capital-intensive, managers, large, automated, mass production. Trade: labour-intensive, owner-run, small."},hu:{q:"Melyik jellemző illik az iparhoz, és nem a kisiparhoz?",o:["Eszközigényes és erősen automatizált","A tulajdonos maga is dolgozik","Munkaigényes egyedi gyártás","Kevés munkatárs, kis darabszám"],e:"Ipar: eszközigényes, menedzsment, nagy, automatizált, tömeggyártás. Kisipar: munkaigényes, tulajdonos vezeti, kicsi."}},{type:"number",level:3,value:.75,tol:.005,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopys Fabrik hat 60.000 € Fixkosten im Monat. Statt 40.000 werden jetzt 80.000 Packungen erzeugt. Um wie viel € sinken die Fixkosten pro Packung? (auf 2 Kommastellen)",e:"Fixkostendegression: vorher 60.000 ÷ 40.000 = 1,50 €, nachher 60.000 ÷ 80.000 = 0,75 €. Die Fixkosten pro Stück sinken um 0,75 €."},en:{q:"Loopy's factory has fixed costs of €60,000 a month. Instead of 40,000 it now produces 80,000 packs. By how many € do the fixed costs per pack fall? (2 decimal places)",e:"Fixed cost degression: before 60,000 ÷ 40,000 = €1.50, afterwards 60,000 ÷ 80,000 = €0.75. Fixed costs per unit fall by €0.75."},hu:{q:"Loopy gyárának havi fix költsége 60 000 €. 40 000 helyett most 80 000 csomagot gyártanak. Hány €-val csökken a csomagonkénti fix költség? (2 tizedesjegyre)",e:"Fixköltség-degresszió: előtte 60 000 ÷ 40 000 = 1,50 €, utána 60 000 ÷ 80 000 = 0,75 €. Az egy darabra jutó fix költség 0,75 €-val csökken."}}]},a={"leistungserstellungsprozess-produktion":[{type:"text",level:1,de:{q:"Wie heißt die Fertigungsart, bei der dasselbe Produkt in sehr großen Mengen ohne Unterbrechung hergestellt wird?",a:["Massenfertigung","Massenproduktion"],e:"Fertigungsarten: Einzelfertigung (ein Stück), Serienfertigung (begrenzte Mengen), Massenfertigung (sehr große Mengen)."},en:{q:"What is the type of production called in which the same product is made in very large quantities without interruption?",a:["mass production","mass manufacturing"],e:"Types of production: one-off production (one unit), batch production (limited quantities), mass production (very large quantities)."},hu:{q:"Hogy hívják azt a gyártási módot, amelynél ugyanazt a terméket nagyon nagy mennyiségben, megszakítás nélkül gyártják?",a:["tömeggyártás"],e:"Gyártási módok: egyedi gyártás (egy darab), sorozatgyártás (korlátozott mennyiség), tömeggyártás (nagyon nagy mennyiség)."}},{type:"number",level:2,value:12,tol:0,unit:{de:"Stunden",en:"hours",hu:"óra"},de:{q:"Ein Auftrag für Loopys Lutscher: 2 h Rüstzeit, 6 h Bearbeitungszeit, 3 h Liegezeit und 1 h Transportzeit. Wie lang ist die Durchlaufzeit?",e:"Durchlaufzeit = Rüst- + Bearbeitungs- + Liege- + Transportzeit = 2 + 6 + 3 + 1 = 12 Stunden."},en:{q:"An order for Loopy's lollipops: 2 h set-up time, 6 h processing time, 3 h waiting time and 1 h transport time. How long is the lead time?",e:"Lead time = set-up + processing + waiting + transport time = 2 + 6 + 3 + 1 = 12 hours."},hu:{q:"Egy megrendelés Loopy nyalókáira: 2 óra átállási idő, 6 óra megmunkálási idő, 3 óra várakozási idő és 1 óra szállítási idő. Mennyi az átfutási idő?",e:"Átfutási idő = átállási + megmunkálási + várakozási + szállítási idő = 2 + 6 + 3 + 1 = 12 óra."}},{type:"number",level:3,value:2800,tol:0,unit:{de:"Lutscher",en:"lollipops",hu:"nyalóka"},de:{q:"Eine Geschenkbox enthält 2 Tüten, jede Tüte enthält 5 Lutscher. Bestellt sind 400 Geschenkboxen, im Lager liegen 1.200 Lutscher. Wie hoch ist der Nettobedarf an Lutschern?",e:"Bruttobedarf = 400 × 2 × 5 = 4.000 Lutscher (Erzeugnisstruktur: Box → Tüte → Lutscher). Nettobedarf = 4.000 − 1.200 Lagerbestand = 2.800 Lutscher."},en:{q:"A gift box contains 2 bags, each bag contains 5 lollipops. 400 gift boxes have been ordered and there are 1,200 lollipops in stock. What is the net requirement of lollipops?",e:"Gross requirement = 400 × 2 × 5 = 4,000 lollipops (product structure: box → bag → lollipop). Net requirement = 4,000 − 1,200 in stock = 2,800 lollipops."},hu:{q:"Egy ajándékdobozban 2 zacskó van, minden zacskóban 5 nyalóka. 400 ajándékdobozt rendeltek, a raktárban 1200 nyalóka van. Mekkora a nettó nyalókaszükséglet?",e:"Bruttó szükséglet = 400 × 2 × 5 = 4000 nyalóka (termékszerkezet: doboz → zacskó → nyalóka). Nettó szükséglet = 4000 − 1200 raktárkészlet = 2800 nyalóka."}}],"investition-finanzierung-ueberblick":[{type:"text",level:1,de:{q:"Wie nennt man die Fähigkeit eines Unternehmens, seine Rechnungen jederzeit pünktlich zu bezahlen?",a:["Liquidität","Zahlungsfähigkeit","Liquiditaet"],e:"Liquidität = Zahlungsfähigkeit. Fehlt sie, droht die Insolvenz – auch wenn das Unternehmen Gewinn macht."},en:{q:"What do you call a company's ability to pay its bills on time at all times?",a:["liquidity","solvency"],e:"Liquidity = ability to pay. Without it a company faces insolvency – even if it makes a profit."},hu:{q:"Hogyan nevezzük egy vállalat azon képességét, hogy számláit mindig időben ki tudja fizetni?",a:["likviditás","fizetőképesség"],e:"Likviditás = fizetőképesség. Ha hiányzik, csőd fenyeget – még akkor is, ha a vállalat nyereséges."}},{type:"mc",level:2,correctIndex:1,de:{q:"Was zeigt die Aktivseite (Aktiva) der Bilanz?",o:["Die Mittelherkunft, also die Finanzierung des Unternehmens","Die Mittelverwendung, also die Investition","Nur das Eigenkapital","Die Erträge und Aufwände des Jahres"],e:"Aktiva = Vermögen = Mittelverwendung (Investition). Passiva = Kapital = Mittelherkunft (Finanzierung)."},en:{q:"What does the assets side of the balance sheet show?",o:["The source of funds, i.e. the company's financing","The use of funds, i.e. investment","Only the equity","The income and expenses of the year"],e:"Assets = use of funds (investment). Liabilities and equity = source of funds (financing)."},hu:{q:"Mit mutat a mérleg eszközoldala (aktívák)?",o:["A források eredetét, vagyis a vállalat finanszírozását","A források felhasználását, vagyis a beruházást","Csak a saját tőkét","Az év bevételeit és ráfordításait"],e:"Aktívák = vagyon = forrásfelhasználás (beruházás). Passzívák = tőke = forráseredet (finanszírozás)."}},{type:"number",level:3,value:35e4,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopys Bilanz: Anlagevermögen 300.000 €, Umlaufvermögen 200.000 €, Eigenkapital 150.000 €. Wie hoch ist das Fremdkapital?",e:"Aktiva = Passiva: 300.000 + 200.000 = 500.000 €. Fremdkapital = 500.000 − 150.000 = 350.000 €."},en:{q:"Loopy's balance sheet: fixed assets €300,000, current assets €200,000, equity €150,000. How much is the debt capital?",e:"Assets = liabilities and equity: 300,000 + 200,000 = €500,000. Debt capital = 500,000 − 150,000 = €350,000."},hu:{q:"Loopy mérlege: befektetett eszközök 300 000 €, forgóeszközök 200 000 €, saját tőke 150 000 €. Mennyi az idegen tőke?",e:"Aktívák = passzívák: 300 000 + 200 000 = 500 000 €. Idegen tőke = 500 000 − 150 000 = 350 000 €."}}],investitionsmanagement:[{type:"text",level:1,de:{q:"Loopy ersetzt eine kaputte Bonbonmaschine durch eine gleichwertige neue. Welche Investitionsart ist das?",a:["Ersatzinvestition","Ersatz-Investition","Ersatz"],e:"Investitionsanlässe: Neu-, Ersatz-, Rationalisierungs- und Erweiterungsinvestition."},en:{q:"Loopy replaces a broken sweet machine with an equivalent new one. What type of investment is this?",a:["replacement investment","replacement"],e:"Reasons for investment: new, replacement, rationalisation and expansion investment."},hu:{q:"Loopy egy elromlott cukorkagépet egy azonos értékű újra cserél. Milyen beruházásfajta ez?",a:["pótló beruházás","pótlóberuházás","pótlás"],e:"Beruházási okok: új, pótló, racionalizálási és bővítő beruházás."}},{type:"number",level:2,value:9e3,tol:0,unit:{de:"€ pro Jahr",en:"€ per year",hu:"€ évente"},de:{q:"Eine Maschine kostet 50.000 €, hat einen Restwert von 5.000 € und eine Nutzungsdauer von 5 Jahren. Wie hoch ist die kalkulatorische Abschreibung pro Jahr?",e:"Kalk. AfA = (AK − RW) ÷ Nutzungsdauer = (50.000 − 5.000) ÷ 5 = 9.000 € pro Jahr."},en:{q:"A machine costs €50,000, has a residual value of €5,000 and a useful life of 5 years. What is the imputed depreciation per year?",e:"Imputed depreciation = (cost − residual value) ÷ useful life = (50,000 − 5,000) ÷ 5 = €9,000 per year."},hu:{q:"Egy gép ára 50 000 €, maradványértéke 5000 €, hasznos élettartama 5 év. Mennyi az évi kalkulatív értékcsökkenés?",e:"Kalk. értékcsökkenés = (beszerzési ár − maradványérték) ÷ élettartam = (50 000 − 5000) ÷ 5 = 9000 € évente."}},{type:"number",level:3,value:20,tol:.05,unit:{de:"%",en:"%",hu:"%"},de:{q:"Eine neue Schokoladenanlage kostet 90.000 €, Restwert 10.000 €, kalkulatorischer Zinssatz 6 %. Sie bringt 7.000 € Gewinn pro Jahr. Wie hoch ist die Rentabilität in %?",e:"Ø Kapitaleinsatz = (90.000 + 10.000) ÷ 2 = 50.000 €. Kalk. Zinsen = 50.000 × 6 % = 3.000 €. Rentabilität = (7.000 + 3.000) × 100 ÷ 50.000 = 20 %."},en:{q:"A new chocolate plant costs €90,000, residual value €10,000, imputed interest rate 6%. It earns a profit of €7,000 per year. What is the return on investment in %?",e:"Average capital employed = (90,000 + 10,000) ÷ 2 = €50,000. Imputed interest = 50,000 × 6% = €3,000. Return = (7,000 + 3,000) × 100 ÷ 50,000 = 20%."},hu:{q:"Egy új csokoládégyártó berendezés ára 90 000 €, maradványértéke 10 000 €, a kalkulatív kamatláb 6%. Évi 7000 € nyereséget hoz. Mekkora a jövedelmezőség %-ban?",e:"Átlagos tőkelekötés = (90 000 + 10 000) ÷ 2 = 50 000 €. Kalk. kamat = 50 000 × 6% = 3000 €. Jövedelmezőség = (7000 + 3000) × 100 ÷ 50 000 = 20%."}}]},i={finanzmanagement:[{type:"text",level:1,de:{q:"Wie heißt die Finanzierung, bei der ein Unternehmen seine Gewinne einbehält, statt sie auszuschütten?",a:["Selbstfinanzierung","offene Selbstfinanzierung"],e:"Selbstfinanzierung = Innen- und Eigenfinanzierung. Offen: einbehaltene Gewinne; still: stille Reserven."},en:{q:"What is the type of financing called in which a company keeps its profits instead of paying them out?",a:["self-financing","self financing","retained earnings"],e:"Self-financing = internal equity financing. Open: retained profits; hidden: hidden reserves."},hu:{q:"Hogy hívják azt a finanszírozást, amelynél a vállalat visszatartja a nyereségét ahelyett, hogy kifizetné?",a:["önfinanszírozás","nyílt önfinanszírozás"],e:"Önfinanszírozás = belső és saját finanszírozás. Nyílt: visszatartott nyereség; rejtett: rejtett tartalékok."}},{type:"mc",level:2,correctIndex:2,de:{q:"Bei welcher Crowdfunding-Form bekommt das Unternehmen Fremdkapital?",o:["Donation-based","Reward-based","Lending-based","Equity-based"],e:"Lending-based Crowdfunding = Kredit von vielen Geldgebern → Fremdkapital, muss zurückgezahlt werden. Equity = Beteiligung (Eigenkapital)."},en:{q:"With which form of crowdfunding does the company receive debt capital?",o:["Donation-based","Reward-based","Lending-based","Equity-based"],e:"Lending-based crowdfunding = a loan from many lenders → debt capital that has to be repaid. Equity = a stake (equity capital)."},hu:{q:"Melyik közösségi finanszírozási formánál kap a vállalat idegen tőkét?",o:["Donation-based (adomány)","Reward-based (jutalom)","Lending-based (hitel)","Equity-based (részesedés)"],e:"Lending-based = sok hitelezőtől kapott kölcsön → idegen tőke, vissza kell fizetni. Equity = részesedés (saját tőke)."}},{type:"number",level:3,value:36,tol:.05,unit:{de:"%",en:"%",hu:"%"},de:{q:"Ein Lieferant bietet Loopy: „Zahlbar in 30 Tagen, bei Zahlung innerhalb von 10 Tagen 2 % Skonto.“ Wie hoch ist der Skonto-Jahreszinssatz? (360 Tage)",e:"Skonto-Jahreszins = Skonto % ÷ (Zahlungsziel − Skontofrist) × 360 = 2 ÷ (30 − 10) × 360 = 36 %. Daher lohnt sich sogar ein Kontokorrentkredit, um Skonto zu nutzen."},en:{q:'A supplier offers Loopy: "Payable in 30 days, 2% discount for payment within 10 days." What is the annual interest rate of the cash discount? (360 days)',e:"Annual discount rate = discount % ÷ (payment term − discount period) × 360 = 2 ÷ (30 − 10) × 360 = 36%. So it is even worth taking an overdraft to use the discount."},hu:{q:"Egy beszállító ezt ajánlja Loopynak: „Fizetendő 30 napon belül, 10 napon belüli fizetésnél 2% skontó.” Mekkora a skontó éves kamatlába? (360 nap)",e:"Skontó éves kamatlába = skontó % ÷ (fizetési határidő − skontóidő) × 360 = 2 ÷ (30 − 10) × 360 = 36%. Ezért még folyószámlahitel felvétele is megéri a skontó kihasználásához."}}],"finanzplan-analyse":[{type:"text",level:1,de:{q:"Wie heißt die Regel, dass das Anlagevermögen durch Eigenkapital und langfristiges Fremdkapital gedeckt sein soll?",a:["Goldene Bilanzregel","Goldene Regel","goldene Finanzierungsregel"],e:"Goldene Bilanzregel: Anlagendeckung = (EK + langfr. FK) × 100 ÷ AV ≥ 100 %."},en:{q:"What is the rule called that fixed assets should be covered by equity and long-term debt?",a:["golden balance sheet rule","golden rule","golden rule of financing"],e:"Golden balance sheet rule: fixed asset coverage = (equity + long-term debt) × 100 ÷ fixed assets ≥ 100%."},hu:{q:"Hogy hívják azt a szabályt, hogy a befektetett eszközöket saját tőkének és hosszú lejáratú idegen tőkének kell fedeznie?",a:["aranyszabály","arany mérlegszabály","arany finanszírozási szabály"],e:"Arany mérlegszabály: befektetett eszközök fedezete = (saját tőke + hosszú lejáratú idegen tőke) × 100 ÷ befektetett eszközök ≥ 100%."}},{type:"number",level:2,value:30,tol:.05,unit:{de:"%",en:"%",hu:"%"},de:{q:"Loopy hat 120.000 € Eigenkapital bei einem Gesamtkapital von 400.000 €. Wie hoch ist die Eigenkapitalquote?",e:"EK-Quote = EK × 100 ÷ GK = 120.000 × 100 ÷ 400.000 = 30 %. Über 20 % gilt als gesund."},en:{q:"Loopy has €120,000 equity and total capital of €400,000. What is the equity ratio?",e:"Equity ratio = equity × 100 ÷ total capital = 120,000 × 100 ÷ 400,000 = 30%. Above 20% counts as healthy."},hu:{q:"Loopynak 120 000 € saját tőkéje van, az összes tőke 400 000 €. Mekkora a saját tőke aránya?",e:"Saját tőke aránya = saját tőke × 100 ÷ összes tőke = 120 000 × 100 ÷ 400 000 = 30%. 20% felett egészségesnek számít."}},{type:"number",level:3,value:5,tol:.05,unit:{de:"Jahre",en:"years",hu:"év"},de:{q:"Loopy hat 500.000 € Fremdkapital und 50.000 € Zahlungsmittel. Der operative Cashflow beträgt 90.000 € pro Jahr. Wie hoch ist die fiktive Schuldentilgungsdauer?",e:"Fiktive Schuldentilgungsdauer = (FK − Zahlungsmittel) ÷ operativer Cashflow = (500.000 − 50.000) ÷ 90.000 = 5 Jahre."},en:{q:"Loopy has €500,000 debt capital and €50,000 cash. Operating cash flow is €90,000 per year. What is the notional debt repayment period?",e:"Notional debt repayment period = (debt − cash) ÷ operating cash flow = (500,000 − 50,000) ÷ 90,000 = 5 years."},hu:{q:"Loopynak 500 000 € idegen tőkéje és 50 000 € pénzeszköze van. Az operatív cash flow évi 90 000 €. Mennyi a fiktív adósságtörlesztési idő?",e:"Fiktív adósságtörlesztési idő = (idegen tőke − pénzeszközök) ÷ operatív cash flow = (500 000 − 50 000) ÷ 90 000 = 5 év."}}],"businessplan-3jg":[{type:"text",level:1,de:{q:"Wie heißt die kurze Zusammenfassung ganz am Anfang des Businessplans? (englischer Begriff)",a:["Executive Summary","Executive-Summary"],e:"Die Executive Summary fasst den ganzen Businessplan auf 1–2 Seiten zusammen – Geldgeber lesen sie zuerst."},en:{q:"What is the short summary at the very beginning of a business plan called?",a:["executive summary"],e:"The executive summary sums up the whole business plan on 1–2 pages – investors read it first."},hu:{q:"Hogy hívják az üzleti terv legelején található rövid összefoglalót? (angol kifejezés)",a:["Executive Summary","vezetői összefoglaló"],e:"Az executive summary (vezetői összefoglaló) 1–2 oldalon foglalja össze az egész üzleti tervet – a befektetők ezt olvassák el először."}},{type:"number",level:2,value:3e4,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy plant, 12.000 Packungen zu einem Nettoverkaufspreis von 2,50 € zu verkaufen. Wie hoch ist der Planumsatz?",e:"Planumsatz = Nettoverkaufspreis × Absatzmenge = 2,50 × 12.000 = 30.000 €."},en:{q:"Loopy plans to sell 12,000 packs at a net selling price of €2.50. What is the planned turnover?",e:"Planned turnover = net selling price × quantity sold = 2.50 × 12,000 = €30,000."},hu:{q:"Loopy 12 000 csomagot tervez eladni 2,50 € nettó eladási áron. Mennyi a tervezett árbevétel?",e:"Tervezett árbevétel = nettó eladási ár × értékesített mennyiség = 2,50 × 12 000 = 30 000 €."}},{type:"number",level:3,value:15e4,tol:1,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopys Planung: Umsatz 200.000 €, variable Kosten 120.000 €, Fixkosten 60.000 €. Wie hoch ist der Break-even-Umsatz?",e:"DBU-Quote = (200.000 − 120.000) × 100 ÷ 200.000 = 40 %. Break-even-Umsatz = Fixkosten ÷ DBU-Quote = 60.000 ÷ 0,40 = 150.000 €."},en:{q:"Loopy's plan: turnover €200,000, variable costs €120,000, fixed costs €60,000. What is the break-even turnover?",e:"Contribution margin ratio = (200,000 − 120,000) × 100 ÷ 200,000 = 40%. Break-even turnover = fixed costs ÷ CM ratio = 60,000 ÷ 0.40 = €150,000."},hu:{q:"Loopy terve: árbevétel 200 000 €, változó költségek 120 000 €, fix költségek 60 000 €. Mekkora a fedezeti pont árbevétele?",e:"Fedezeti hányad = (200 000 − 120 000) × 100 ÷ 200 000 = 40%. Fedezeti pont árbevétele = fix költségek ÷ fedezeti hányad = 60 000 ÷ 0,40 = 150 000 €."}}]},s={"unternehmensfuehrung-ueberblick":[{type:"tf",level:1,correct:!1,de:{q:"Je höher eine Hierarchieebene im Unternehmen liegt, desto mehr Führungskräfte gibt es auf dieser Ebene",e:"Falsch – die Hierarchie ist eine Pyramide: Je höher die Ebene, desto WENIGER Führungskräfte. An der Spitze steht oft nur die Geschäftsführung."},en:{q:"The higher a hierarchy level in a company, the more managers there are on that level",e:"False – the hierarchy is a pyramid: the higher the level, the FEWER managers. At the top there is often only the managing director(s)."},hu:{q:"Minél magasabban van egy hierarchiaszint a vállalatban, annál több vezető dolgozik ezen a szinten",e:"Hamis – a hierarchia piramis alakú: minél magasabb a szint, annál KEVESEBB a vezető. A csúcson gyakran csak az ügyvezetés áll."}},{type:"tf",level:1,correct:!0,de:{q:"In kleinen Betrieben gibt es oft nur eine oder zwei Hierarchiestufen",e:"Richtig – in einem Kleinbetrieb (z. B. Inhaberin + Mitarbeiter:innen) fallen Top-, Middle- und Lower Management oft zusammen; die volle Pyramide gibt es vor allem in großen Unternehmen."},en:{q:"Small businesses often have only one or two hierarchy levels",e:"True – in a small business (e.g. owner + employees) top, middle and lower management often coincide; the full pyramid exists mainly in large companies."},hu:{q:"A kisvállalkozásokban gyakran csak egy vagy két hierarchiaszint van",e:"Igaz – egy kisvállalkozásban (pl. tulajdonos + munkatársak) a felső, közép- és alsó vezetés gyakran egybeesik; a teljes piramis főleg a nagyvállalatokra jellemző."}},{type:"tf",level:3,correct:!1,de:{q:"Das operative Management ist in erster Linie Aufgabe des Topmanagements, weil die Umsetzung den Unternehmenserfolg am stärksten beeinflusst",e:"Falsch – normatives und strategisches Management liegen beim Top- und Middle Management, das operative Management (Umsetzung im Alltag) vor allem beim Lower Management."},en:{q:"Operational management is primarily the job of top management, because implementation has the strongest influence on business success",e:"False – normative and strategic management lie with top and middle management; operational management (day-to-day implementation) lies mainly with lower management."},hu:{q:"Az operatív menedzsment elsősorban a felső vezetés feladata, mert a megvalósítás befolyásolja leginkább a vállalat sikerét",e:"Hamis – a normatív és a stratégiai menedzsment a felső és a középvezetés feladata, az operatív menedzsment (a napi megvalósítás) elsősorban az alsó vezetésé."}},{type:"multi",level:1,correct:[0,1,2,5],de:{q:"Welche der folgenden sind digitale Tools für die Kommunikation im Unternehmen? Wähle alle zutreffenden.",o:["Microsoft Teams","Intranet","Slack","Organigramm","Stellenbeschreibung","Newsletter-Tools"],e:"Teams, Slack, Intranet und Newsletter-Tools dienen dem Informationsaustausch. Organigramm und Stellenbeschreibung sind Organisationsinstrumente, keine Kommunikationstools."},en:{q:"Which of the following are digital tools for communication within a company? Select all that apply.",o:["Microsoft Teams","Intranet","Slack","Organisation chart","Job description","Newsletter tools"],e:"Teams, Slack, the intranet and newsletter tools are used to exchange information. The organisation chart and the job description are organisational instruments, not communication tools."},hu:{q:"Az alábbiak közül melyek a vállalati kommunikáció digitális eszközei? Jelöld meg az összes helyeset.",o:["Microsoft Teams","Intranet","Slack","Szervezeti ábra","Munkaköri leírás","Hírlevélküldő eszközök"],e:"A Teams, a Slack, az intranet és a hírlevélküldő eszközök az információcserét szolgálják. A szervezeti ábra és a munkaköri leírás szervezési eszköz, nem kommunikációs eszköz."}},{type:"multi",level:3,correct:[0,1,3,4],de:{q:"Welche Aufgaben passen zum Middle Management (z. B. Abteilungsleitung)? Wähle alle zutreffenden.",o:["Eine Abteilung leiten","Zwischen Geschäftsführung und Teams vermitteln","Die Gesamtverantwortung für das Unternehmen tragen","Vorgaben der Geschäftsführung in die Abteilung weitergeben","An strategischen Entscheidungen mitwirken","Entscheidungen nur ausführen, ohne Führungsaufgabe"],e:"Das Middle Management leitet Abteilungen, vermittelt zwischen oben und unten und wirkt laut Buch auch beim normativen und strategischen Management mit. Die Gesamtverantwortung trägt das Topmanagement; reine Ausführung ist die Ausführungsebene."},en:{q:"Which tasks fit middle management (e.g. heads of department)? Select all that apply.",o:["Leading a department","Mediating between the managing directors and the teams","Bearing overall responsibility for the company","Passing on the managing directors’ targets to the department","Contributing to strategic decisions","Only carrying out decisions, with no management role"],e:"Middle management leads departments, mediates between top and bottom and, according to the book, also takes part in normative and strategic management. Overall responsibility lies with top management; pure execution is the operative level."},hu:{q:"Mely feladatok illenek a középvezetéshez (pl. osztályvezetés)? Jelöld meg az összes helyeset.",o:["Egy osztály vezetése","Közvetítés az ügyvezetés és a csapatok között","A vállalat egészéért viselt felelősség","Az ügyvezetés elvárásainak továbbítása az osztálynak","Közreműködés a stratégiai döntésekben","Csak a döntések végrehajtása, vezetői feladat nélkül"],e:"A középvezetés osztályokat irányít, közvetít a felső vezetés és a beosztottak között, és a tankönyv szerint a normatív és stratégiai menedzsmentben is részt vesz. Az átfogó felelősség a felső vezetésé; a puszta végrehajtás a végrehajtói szint feladata."}},{type:"order",level:2,de:{q:"Ordne die Hierarchiestufen von oben (Spitze der Pyramide) nach unten.",o:["Topmanagement (Geschäftsführung)","Middle Management (Abteilungsleitung)","Lower Management (Team-/Gruppenleitung)","Ausführungsebene (Mitarbeiter:innen)"],e:"Topmanagement → Middle Management → Lower Management → Ausführungsebene. Das Middle Management ist das Bindeglied zwischen oben und unten."},en:{q:"Put the hierarchy levels in order from the top (tip of the pyramid) to the bottom.",o:["Top management (managing directors)","Middle management (heads of department)","Lower management (team/group leaders)","Operative level (employees)"],e:"Top management → middle management → lower management → operative level. Middle management is the link between top and bottom."},hu:{q:"Rendezd sorba a hierarchiaszinteket felülről (a piramis csúcsától) lefelé.",o:["Felső vezetés (ügyvezetés)","Középvezetés (osztályvezetés)","Alsó vezetés (csapat-/csoportvezetés)","Végrehajtói szint (munkatársak)"],e:"Felső vezetés → középvezetés → alsó vezetés → végrehajtói szint. A középvezetés köti össze a felső szintet az alsóval."}},{type:"match",level:2,de:{q:"Ordne die Schritte aus dem Schiff-Beispiel der passenden Ebene zu.",p:[["Kapitän will sicher in New York ankommen","Vision"],["Kapitän legt Zweck und Leitlinien der Fahrt fest","Normatives Management"],["Kapitän plant mit dem Ersten Offizier die Route","Strategisches Management"],["Erster Offizier überwacht die laufende Fahrt","Operatives Management"]],e:"Von der Vision über die Strategie zur Umsetzung: Ziel (Vision) → Werte/Leitlinien (normativ) → langfristiger Plan (strategisch) → Durchführung und Überwachung (operativ)."},en:{q:"Match the steps from the ship example with the right level.",p:[["The captain wants to arrive safely in New York","Vision"],["The captain sets the purpose and guidelines of the voyage","Normative management"],["The captain plans the route with the first officer","Strategic management"],["The first officer monitors the ongoing voyage","Operational management"]],e:"From vision via strategy to implementation: goal (vision) → values/guidelines (normative) → long-term plan (strategic) → execution and monitoring (operational)."},hu:{q:"Párosítsd a hajós példa lépéseit a megfelelő szinttel.",p:[["A kapitány biztonságban akar New Yorkba érni","Jövőkép (vízió)"],["A kapitány meghatározza az út célját és irányelveit","Normatív menedzsment"],["A kapitány az első tiszttel megtervezi az útvonalat","Stratégiai menedzsment"],["Az első tiszt felügyeli a folyamatban lévő utat","Operatív menedzsment"]],e:"A víziótól a stratégián át a megvalósításig: cél (vízió) → értékek/irányelvek (normatív) → hosszú távú terv (stratégiai) → végrehajtás és felügyelet (operatív)."}},{type:"mc",level:2,correctIndex:2,de:{q:"Die Geschäftsführung der Hotel Alpenblick GmbH schickt eine Rundmail voller Fachbegriffe mit widersprüchlichen Anweisungen. Jede Abteilung versteht sie anders. Welcher Erfolgsfaktor der Kommunikation fehlt vor allem?",o:["Regelmäßigkeit","Empathie","Klarheit","Offenheit"],e:"Klarheit heißt: eindeutig und verständlich, ohne Missverständnisse. Regelmäßigkeit betrifft feste Kanäle und Zeitpunkte, Offenheit die Ehrlichkeit über Probleme – hier liegt das Problem aber in der unverständlichen Botschaft."},en:{q:"The management of Hotel Alpenblick GmbH sends an email to all staff full of jargon and with contradictory instructions. Every department understands it differently. Which success factor of communication is mainly missing?",o:["Regularity","Empathy","Clarity","Openness"],e:"Clarity means clear and understandable, without misunderstandings. Regularity is about fixed channels and timing, openness about honesty regarding problems – but here the problem is the incomprehensible message."},hu:{q:"Az Alpenblick Szálloda Kft. ügyvezetése szakkifejezésekkel teli, egymásnak ellentmondó utasításokat tartalmazó körlevelet küld. Minden osztály másképp érti. A kommunikáció melyik sikertényezője hiányzik leginkább?",o:["Rendszeresség","Empátia","Világosság","Nyitottság"],e:"A világosság egyértelmű, érthető, félreértésektől mentes közlést jelent. A rendszeresség az állandó csatornákra és időpontokra, a nyitottság a problémák őszinte kezelésére vonatkozik – itt viszont az üzenet érthetetlensége a gond."}},{type:"mc",level:3,correctIndex:0,de:{q:"Die Zentrale einer Bank beschließt die Strategie „Ausbau der Videoberatung“. Eine Filialleiterin legt daraufhin fest, welche Berater:innen ab März welche Termine übernehmen. Welche Aussage trifft zu?",o:["Sie handelt operativ: Sie setzt die Strategie konkret um","Sie handelt normativ: Sie legt die Werte der Bank fest","Sie handelt strategisch: Sie plant langfristig die Ausrichtung","Sie gehört zur Ausführungsebene ohne Führungsaufgabe"],e:"Die Strategie kommt von oben; die Filialleiterin plant im Detail, wer was wann macht – das ist operatives Management. Werte (normativ) und langfristige Ausrichtung (strategisch) hat sie nicht festgelegt; als Führungskraft ist sie auch nicht Ausführungsebene."},en:{q:"A bank’s head office decides on the strategy “expand video advice”. A branch manager then decides which advisers will take which appointments from March. Which statement is correct?",o:["She acts operationally: she puts the strategy into practice","She acts normatively: she sets the bank’s values","She acts strategically: she plans the long-term direction","She belongs to the operative level with no management role"],e:"The strategy comes from above; the branch manager plans in detail who does what and when – that is operational management. She did not set values (normative) or the long-term direction (strategic); as a manager she is not on the operative level either."},hu:{q:"Egy bank központja a „videós tanácsadás bővítése” stratégiáról dönt. Egy fiókvezető ezután meghatározza, mely tanácsadók mely időpontokat vállalják márciustól. Melyik állítás igaz?",o:["Operatívan cselekszik: konkrétan megvalósítja a stratégiát","Normatívan cselekszik: meghatározza a bank értékeit","Stratégiailag cselekszik: hosszú távra tervezi az irányt","A végrehajtói szinthez tartozik, vezetői feladat nélkül"],e:"A stratégia felülről érkezik; a fiókvezető részletesen megtervezi, ki mit és mikor csinál – ez operatív menedzsment. Értékeket (normatív) és hosszú távú irányt (stratégiai) nem ő határozott meg; vezetőként pedig nem a végrehajtói szinthez tartozik."}},{type:"text",level:2,de:{q:"Für welchen Bereich ist der Chief Sales Officer (CSO) zuständig?",a:["Vertrieb","Vertriebsleitung","Verkauf","Verkaufsleitung","Vertriebsleiter","Vertriebsleiterin"],e:"CSO = Chief Sales Officer = Vertriebsleitung. Nicht verwechseln mit COO (Chief Operating Officer, laufender Geschäftsbetrieb) und CEO (Geschäftsführung)."},en:{q:"Which area is the Chief Sales Officer (CSO) responsible for?",a:["sales","head of sales","sales management","selling"],e:"CSO = Chief Sales Officer = head of sales. Do not confuse with the COO (Chief Operating Officer, day-to-day operations) and the CEO (managing director)."},hu:{q:"Melyik területért felel a Chief Sales Officer (CSO)?",a:["értékesítés","értékesítési vezetés","értékesítésért","értékesítési vezető","kereskedelem","eladás"],e:"CSO = Chief Sales Officer = értékesítési vezető. Nem tévesztendő össze a COO-val (Chief Operating Officer, napi működés) és a CEO-val (ügyvezetés)."}}],"normatives-management":[{type:"tf",level:1,correct:!0,de:{q:"Nicht jedes Unternehmen hat eine Vision, aber jedes Unternehmen hat eine Mission",e:"Richtig – die Mission ist der Grund, warum es das Unternehmen gibt (Auftrag, Nutzen). Eine ausformulierte Vision als Zukunftsbild („Leuchtturm“) hat nicht jedes Unternehmen."},en:{q:"Not every company has a vision, but every company has a mission",e:"True – the mission is the reason the company exists (purpose, benefit). Not every company has a formulated vision as a picture of the future (the “lighthouse”)."},hu:{q:"Nem minden vállalatnak van jövőképe (víziója), de minden vállalatnak van küldetése",e:"Igaz – a küldetés az, amiért a vállalat létezik (feladata, haszna). Megfogalmazott jövőképe mint „világítótorony” nem minden vállalatnak van."}},{type:"tf",level:2,correct:!1,de:{q:"Die Unternehmenskultur entspricht automatisch dem, was im schriftlichen Unternehmensleitbild steht",e:"Falsch – das Leitbild ist das schriftlich formulierte Soll. Die Unternehmenskultur sind die tatsächlich GELEBTEN Werte; sie zeigt erst, ob das Leitbild wirklich gelebt wird."},en:{q:"Corporate culture automatically matches what is written in the company’s mission statement",e:"False – the mission statement is the written target. Corporate culture is the values actually LIVED; it shows whether the mission statement is really put into practice."},hu:{q:"A vállalati kultúra automatikusan megegyezik azzal, ami az írásos küldetésnyilatkozatban áll",e:"Hamis – a küldetésnyilatkozat az írásban rögzített elvárás. A vállalati kultúra a ténylegesen MEGÉLT értékeket jelenti; ez mutatja meg, hogy a küldetésnyilatkozatot valóban követik-e."}},{type:"tf",level:3,correct:!1,de:{q:"Die Berichtspflicht nach den ESG-Kriterien gilt laut Buch für jedes EU-Unternehmen, auch für Kleinbetriebe mit wenigen Mitarbeiter:innen",e:"Falsch – laut Buch ist der ESG-Bericht (Environmental, Social, Governance) nur für große EU-Unternehmen ab 250 Mitarbeiter:innen Pflicht. Kleinbetriebe können CSR freiwillig leben, z. B. nach den SDGs."},en:{q:"According to the book, the reporting obligation under the ESG criteria applies to every EU company, including small businesses with only a few employees",e:"False – according to the book, the ESG report (Environmental, Social, Governance) is only mandatory for large EU companies with 250 or more employees. Small businesses can practise CSR voluntarily, e.g. along the SDGs."},hu:{q:"A tankönyv szerint az ESG-kritériumok szerinti jelentéstételi kötelezettség minden uniós vállalatra vonatkozik, a néhány fős kisvállalkozásokra is",e:"Hamis – a tankönyv szerint az ESG-jelentés (Environmental, Social, Governance) csak a legalább 250 munkavállalót foglalkoztató nagy uniós vállalatok számára kötelező. A kisvállalkozások önkéntesen vállalhatnak CSR-t, pl. a fenntartható fejlődési célok (SDG) mentén."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Funktionen gehören zur INNENWIRKUNG des Unternehmensleitbilds? Wähle alle zutreffenden.",o:["Motivation der Mitarbeiter:innen","Zugehörigkeitsgefühl","Positives Image in der Öffentlichkeit","Kommunikation der Unternehmensziele","Attraktivität für neue Bewerber:innen"],e:"Innenwirkung = Wirkung auf die eigenen Mitarbeiter:innen: Motivation, Zugehörigkeit, Ziele kommunizieren. Image, Glaubwürdigkeit und Attraktivität für neue Mitarbeiter:innen sind Außenwirkung."},en:{q:"Which functions belong to the INTERNAL effect of the mission statement? Select all that apply.",o:["Motivating employees","Sense of belonging","Positive public image","Communicating the company’s goals","Attractiveness to new applicants"],e:"Internal effect = effect on the company’s own staff: motivation, belonging, communicating goals. Image, credibility and attractiveness to new employees are external effects."},hu:{q:"Mely funkciók tartoznak a küldetésnyilatkozat BELSŐ hatásához? Jelöld meg az összes helyeset.",o:["A munkatársak motiválása","Összetartozás érzése","Pozitív kép a nyilvánosság előtt","A vállalati célok kommunikálása","Vonzerő az új jelentkezők számára"],e:"Belső hatás = hatás a saját munkatársakra: motiváció, összetartozás, a célok kommunikálása. Az imázs, a hitelesség és az új munkatársak vonzása külső hatás."}},{type:"multi",level:3,correct:[0,2,4],de:{q:"Welche der folgenden Ziele sind MONETÄRE Ziele? Wähle alle zutreffenden.",o:["Umsatz um 10 % steigern","Marktanteil um 7 % erhöhen","Personalkosten um 50.000 € senken","Kundenzufriedenheit um 10 % steigern","Jahresgewinn auf 200.000 € erhöhen","Flexibles Arbeitszeitmodell einführen"],e:"Monetär = direkt in Geld messbar: Umsatz, Kosten, Gewinn. Marktanteil und Kundenzufriedenheit werden zwar in % gemessen, aber nicht in Geld – sie sind nicht-monetäre Ziele, ebenso das Arbeitszeitmodell."},en:{q:"Which of the following goals are MONETARY goals? Select all that apply.",o:["Increase revenue by 10%","Increase market share by 7%","Cut personnel costs by €50,000","Increase customer satisfaction by 10%","Raise annual profit to €200,000","Introduce a flexible working-time model"],e:"Monetary = directly measurable in money: revenue, costs, profit. Market share and customer satisfaction are measured in %, but not in money – they are non-monetary goals, as is the working-time model."},hu:{q:"Az alábbi célok közül melyek PÉNZBEN KIFEJEZHETŐ (monetáris) célok? Jelöld meg az összes helyeset.",o:["Az árbevétel növelése 10%-kal","A piaci részesedés növelése 7%-kal","A személyi költségek csökkentése 50 000 €-val","A vevői elégedettség növelése 10%-kal","Az éves nyereség növelése 200 000 €-ra","Rugalmas munkaidőmodell bevezetése"],e:"Monetáris = közvetlenül pénzben mérhető: árbevétel, költség, nyereség. A piaci részesedést és a vevői elégedettséget ugyan %-ban mérik, de nem pénzben – ezek nem monetáris célok, akárcsak a munkaidőmodell."}},{type:"match",level:1,de:{q:"Ordne jedem Bestandteil des Leitbilds die Frage zu, die er beantwortet.",p:[["Vision","Wohin will das Unternehmen?"],["Mission","Warum existiert das Unternehmen?"],["Unternehmensphilosophie","Welche Werte sind wichtig?"],["Unternehmensziele","Was will es konkret erreichen?"]],e:"Vision = Zukunftsbild, Mission = Auftrag und Nutzen, Philosophie = Werte, Ziele = konkret Angestrebtes (z. B. Marktanteil +7 %)."},en:{q:"Match each part of the mission statement with the question it answers.",p:[["Vision","Where does the company want to go?"],["Mission","Why does the company exist?"],["Corporate philosophy","Which values matter?"],["Corporate goals","What exactly does it want to achieve?"]],e:"Vision = picture of the future, mission = purpose and benefit, philosophy = values, goals = concrete targets (e.g. market share +7%)."},hu:{q:"Párosítsd a küldetésnyilatkozat egyes elemeit azzal a kérdéssel, amelyre választ adnak.",p:[["Jövőkép (vízió)","Hová akar eljutni a vállalat?"],["Küldetés (misszió)","Miért létezik a vállalat?"],["Vállalati filozófia","Mely értékek fontosak?"],["Vállalati célok","Mit akar konkrétan elérni?"]],e:"Jövőkép = a jövő képe, küldetés = feladat és haszon, filozófia = értékek, célok = konkrét elérendő eredmények (pl. piaci részesedés +7%)."}},{type:"match",level:2,de:{q:"Ziel: „Die Rezeptionsleiterin soll bis 30. Juni die Online-Buchungen des Hotels in Wien um 15 % steigern.“ Ordne die Teile den Elementen der Operationalisierung zu.",p:[["Online-Buchungen steigern","Zielinhalt"],["um 15 %","Zielausmaß"],["bis 30. Juni","Zieltermin"],["die Rezeptionsleiterin","Zielverantwortung"],["in Wien","Zielort"]],e:"Operationalisierte Ziele beantworten: Was? (Inhalt), Wie viel? (Ausmaß), Bis wann? (Termin), Wer? (Verantwortung), Wo? (Ort). Erst dann ist das Ziel überprüfbar."},en:{q:"Goal: “The head of reception is to increase the hotel’s online bookings in Vienna by 15% by 30 June.” Match the parts to the elements of operationalisation.",p:[["increase online bookings","Goal content"],["by 15%","Goal extent"],["by 30 June","Goal deadline"],["the head of reception","Goal responsibility"],["in Vienna","Goal location"]],e:"Operationalised goals answer: What? (content), How much? (extent), By when? (deadline), Who? (responsibility), Where? (location). Only then can the goal be checked."},hu:{q:"Cél: „A recepcióvezetőnek június 30-ig 15%-kal kell növelnie a szálloda online foglalásait Bécsben.” Párosítsd a részeket az operacionalizálás elemeivel.",p:[["online foglalások növelése","Cél tartalma"],["15%-kal","Cél mértéke"],["június 30-ig","Cél határideje"],["a recepcióvezető","Célért felelős személy"],["Bécsben","Cél helye"]],e:"Az operacionalizált cél megválaszolja: Mit? (tartalom), Mennyit? (mérték), Meddig? (határidő), Ki? (felelős), Hol? (hely). Csak így ellenőrizhető a cél."}},{type:"mc",level:2,correctIndex:3,de:{q:"Loopy schreibt in ihr Leitbild: „Ehrlichkeit gegenüber Lieferant:innen und ein respektvoller Umgang im Team sind uns wichtig.“ Welcher Bestandteil des Leitbilds ist das?",o:["Vision","Mission","Unternehmensziel","Unternehmensphilosophie"],e:"Werte wie Ehrlichkeit und Respekt gehören zur Unternehmensphilosophie (Welche Werte sind wichtig?). Die Mission beschreibt den Nutzen, die Vision das Zukunftsbild, ein Ziel wäre messbar."},en:{q:"Loopy writes in her mission statement: “Honesty towards suppliers and respectful teamwork matter to us.” Which part of the mission statement is this?",o:["Vision","Mission","Corporate goal","Corporate philosophy"],e:"Values such as honesty and respect belong to the corporate philosophy (Which values matter?). The mission describes the benefit, the vision the picture of the future, and a goal would be measurable."},hu:{q:"Loopy ezt írja a küldetésnyilatkozatába: „Fontos számunkra a beszállítókkal szembeni őszinteség és a tiszteletteljes csapatmunka.” A küldetésnyilatkozat melyik eleme ez?",o:["Jövőkép (vízió)","Küldetés (misszió)","Vállalati cél","Vállalati filozófia"],e:"Az olyan értékek, mint az őszinteség és a tisztelet, a vállalati filozófiához tartoznak (Mely értékek fontosak?). A küldetés a hasznot, a jövőkép a jövő képét írja le, egy cél pedig mérhető lenne."}},{type:"mc",level:3,correctIndex:1,de:{q:"Im Leitbild einer Softwarefirma steht „Unsere Mitarbeiter:innen stehen im Mittelpunkt“. Tatsächlich werden Ideen von Mitarbeiter:innen ignoriert und Führungskräfte geben nur Anweisungen. Was zeigt das?",o:["Das Leitbild wirkt nur nach außen – genau dafür ist es gedacht","Die gelebte Kultur weicht vom Leitbild ab – es wird nicht gelebt","Es liegt eine Zielkomplementarität zwischen Leitbild und Kultur vor","Das ist ein Problem des operativen Managements, nicht der Werte"],e:"Unternehmenskultur = die tatsächlich gelebten Werte. Widerspricht der Alltag dem Leitbild, wird es nicht gelebt – und verliert Innen- UND Außenwirkung. Positive Kultur entsteht, wenn die Führung die Werte authentisch vorlebt."},en:{q:"A software company’s mission statement says “Our employees are at the centre of everything”. In reality, employees’ ideas are ignored and managers only give orders. What does this show?",o:["The mission statement only works externally – that is its purpose","The lived culture differs from the mission statement – it is not lived","There is goal complementarity between mission statement and culture","It is a problem of operational management, not of values"],e:"Corporate culture = the values actually lived. If everyday reality contradicts the mission statement, it is not lived – and loses its internal AND external effect. A positive culture arises when managers authentically model the values."},hu:{q:"Egy szoftvercég küldetésnyilatkozatában ez áll: „Munkatársaink állnak a középpontban”. Valójában a munkatársak ötleteit figyelmen kívül hagyják, a vezetők pedig csak utasítanak. Mit mutat ez?",o:["A küldetésnyilatkozat csak kifelé hat – pont erre szolgál","A megélt kultúra eltér a küldetésnyilatkozattól – azt nem élik meg","A küldetésnyilatkozat és a kultúra között célkomplementaritás áll fenn","Ez az operatív menedzsment problémája, nem az értékeké"],e:"Vállalati kultúra = a ténylegesen megélt értékek. Ha a hétköznapok ellentmondanak a küldetésnyilatkozatnak, azt nem élik meg – így elveszíti belső ÉS külső hatását. Pozitív kultúra akkor alakul ki, ha a vezetés hitelesen példát mutat."}},{type:"text",level:2,de:{q:"Wie nennt man die Zielbeziehung, bei der das Erreichen eines Ziels das Erreichen eines anderen Ziels fördert?",a:["Zielkomplementarität","Zielharmonie","Komplementarität","komplementär","Zielkomplementarität (Harmonie)"],e:"Zielkomplementarität (Zielharmonie), z. B. Kundenzufriedenheit ↑ → Umsatz ↑. Gegenteil: Zielkonflikt; beeinflussen sich Ziele nicht, spricht man von Zielneutralität."},en:{q:"What is the goal relationship called in which achieving one goal helps to achieve another?",a:["goal complementarity","complementarity","complementary","goal harmony","complementary goals"],e:"Goal complementarity (harmony), e.g. customer satisfaction ↑ → revenue ↑. The opposite is goal conflict; if goals do not affect each other, they are neutral."},hu:{q:"Hogy hívják azt a célkapcsolatot, amelyben az egyik cél elérése elősegíti egy másik cél elérését?",a:["célkomplementaritás","komplementaritás","célharmónia","kiegészítő célkapcsolat","komplementer"],e:"Célkomplementaritás (célharmónia), pl. vevői elégedettség ↑ → árbevétel ↑. Ellentéte a célkonfliktus; ha a célok nem hatnak egymásra, célsemlegességről beszélünk."}}],"strategisches-operatives-management":[{type:"tf",level:1,correct:!0,de:{q:"Ein relativer Marktanteil von über 1,0 bedeutet, dass das Unternehmen Marktführer ist",e:"Richtig – relativer Marktanteil = eigener Marktanteil ÷ Marktanteil des größten Konkurrenten. Über 1,0 heißt: größer als der stärkste Mitbewerber, also Marktführer."},en:{q:"A relative market share of more than 1.0 means that the company is the market leader",e:"True – relative market share = own market share ÷ market share of the largest competitor. Above 1.0 means bigger than the strongest competitor, i.e. market leader."},hu:{q:"Az 1,0 feletti relatív piaci részesedés azt jelenti, hogy a vállalat piacvezető",e:"Igaz – relatív piaci részesedés = saját piaci részesedés ÷ a legnagyobb versenytárs piaci részesedése. Az 1,0 feletti érték azt jelenti, hogy nagyobb a legerősebb versenytársnál, tehát piacvezető."}},{type:"tf",level:1,correct:!0,de:{q:"Die Verhandlungsstärke der Kund:innen ist groß, wenn sie leicht zu einem anderen Anbieter wechseln können, etwa über Vergleichsportale",e:"Richtig – laut Fünf-Kräfte-Modell ist die Verhandlungsstärke der Kund:innen groß, wenn es wenige Abnehmer gibt oder der Wechsel einfach ist. Das drückt Preise und Gewinne der Branche."},en:{q:"Customers have strong bargaining power if they can easily switch to another supplier, for example via price comparison sites",e:"True – according to the five forces model, customers’ bargaining power is high if there are few buyers or switching is easy. This pushes down the industry’s prices and profits."},hu:{q:"A vevők alkupozíciója erős, ha könnyen át tudnak térni egy másik szolgáltatóra, például árösszehasonlító oldalak segítségével",e:"Igaz – az öt versenyerő modellje szerint a vevők alkuereje nagy, ha kevés a vevő, vagy könnyű a váltás. Ez lenyomja az iparág árait és nyereségét."}},{type:"tf",level:2,correct:!1,de:{q:"Cashcows sollten laut BCG-Portfolio besonders stark mit Investitionen gefördert werden, weil sie einen hohen Marktanteil haben",e:"Falsch – für Cashcows (hoher Marktanteil, geringes Marktwachstum) gilt die Abschöpfungsstrategie: Gewinne „melken“ und damit z. B. Stars oder Question Marks finanzieren. Stark gefördert werden Stars."},en:{q:"According to the BCG portfolio, cash cows should receive particularly heavy investment because they have a high market share",e:"False – for cash cows (high market share, low market growth) the harvesting strategy applies: “milk” the profits and use them to finance stars or question marks, for example. Stars are the ones promoted heavily."},hu:{q:"A BCG-portfólió szerint a fejőstehenekbe különösen sokat kell befektetni, mert nagy a piaci részesedésük",e:"Hamis – a fejőstehenekre (nagy piaci részesedés, kis piacnövekedés) a lefölözési stratégia érvényes: a nyereséget „lefejik”, és abból pl. a sztárokat vagy a kérdőjeleket finanszírozzák. Erősen a sztárokat kell támogatni."}},{type:"multi",level:1,correct:[0,2,4,5],de:{q:"Welche Faktoren werden bei der EXTERNEN Analyse untersucht? Wähle alle zutreffenden.",o:["Ein neuer Mindestlohn wird beschlossen","Die eigenen Maschinen sind veraltet","Trend zu gesunder Ernährung","Die Mitarbeiter:innen sind sehr motiviert","Rohstoffkosten steigen","Zölle werden erhöht"],e:"Externe Analyse (PESTEL, Fünf Kräfte) betrachtet das Umfeld: rechtlich, soziokulturell, wirtschaftlich, politisch. Maschinen und Motivation sind innere Stärken bzw. Schwächen – Thema der internen Analyse."},en:{q:"Which factors are examined in the EXTERNAL analysis? Select all that apply.",o:["A new minimum wage is introduced","The company’s own machines are outdated","Trend towards healthy eating","The employees are highly motivated","Raw material costs are rising","Tariffs are increased"],e:"External analysis (PESTEL, five forces) looks at the environment: legal, socio-cultural, economic, political. Machines and motivation are internal strengths or weaknesses – a topic for the internal analysis."},hu:{q:"Mely tényezőket vizsgálja a KÜLSŐ elemzés? Jelöld meg az összes helyeset.",o:["Új minimálbért vezetnek be","A saját gépek elavultak","Az egészséges táplálkozás felé mutató trend","A munkatársak nagyon motiváltak","Emelkednek a nyersanyagárak","Megemelik a vámokat"],e:"A külső elemzés (PESTEL, öt versenyerő) a környezetet vizsgálja: jogi, társadalmi-kulturális, gazdasági, politikai tényezők. A gépek és a motiváció belső erősségek, illetve gyengeségek – ezek a belső elemzés tárgyai."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen zur Budgetierung treffen zu? Wähle alle zutreffenden.",o:["Teilbudgets (Material, Personal, Umsatz …) werden zum Gesamtbudget zusammengeführt","Das Controlling überwacht, ob die Budgets eingehalten werden","Das Top-down-Verfahren eignet sich vor allem für voneinander abhängige Bereiche","Beim Bottom-up-Verfahren gibt die Leitung das Gesamtbudget vor","Die Budgetierung ist Aufgabe des normativen Managements"],e:"Budgetierung ist das Herzstück der OPERATIVEN Planung. Bottom-up: Bereichsleiter:innen erstellen Teilbudgets (für getrennte Bereiche); top-down: die Leitung gibt das Gesamtbudget vor (für abhängige Bereiche)."},en:{q:"Which statements about budgeting are correct? Select all that apply.",o:["Partial budgets (materials, personnel, sales …) are combined into the master budget","Controlling monitors whether the budgets are kept","The top-down method is particularly suitable for interdependent areas","In the bottom-up method, management sets the master budget","Budgeting is a task of normative management"],e:"Budgeting is the core of OPERATIONAL planning. Bottom-up: heads of area draw up partial budgets (for separate areas); top-down: management sets the master budget (for interdependent areas)."},hu:{q:"Mely állítások igazak a költségvetés-készítésre (budgetálásra)? Jelöld meg az összes helyeset.",o:["A részköltségvetéseket (anyag, személyi, árbevétel …) összesítik a teljes költségvetésbe","A kontrolling ellenőrzi a költségvetések betartását","A felülről lefelé (top-down) módszer főleg az egymástól függő területekhez illik","Az alulról felfelé (bottom-up) módszernél a vezetés adja meg a teljes költségvetést","A költségvetés-készítés a normatív menedzsment feladata"],e:"A költségvetés-készítés az OPERATÍV tervezés központi eleme. Bottom-up: a területi vezetők készítik el a részköltségvetéseket (elkülönült területeknél); top-down: a vezetés adja meg a teljes keretet (egymástól függő területeknél)."}},{type:"order",level:2,de:{q:"Bringe die Schritte der Strategieerarbeitung in die richtige Reihenfolge.",o:["Vorgaben aus dem normativen Management übernehmen","Externe und interne Analyse durchführen","Prognosen über zukünftige Entwicklungen erstellen","Ergebnisse in der SWOT-Analyse zusammenfassen","Mögliche Strategien entwickeln"],e:"Ausgangspunkt sind Vision, Werte und Ziele (normativ). Dann werden Umfeld und Unternehmen analysiert, Prognosen erstellt, alles in der SWOT-Analyse gebündelt – erst daraus leiten sich Strategien ab."},en:{q:"Put the steps of developing a strategy in the correct order.",o:["Adopt the guidelines from normative management","Carry out the external and internal analysis","Make forecasts about future developments","Summarise the results in a SWOT analysis","Develop possible strategies"],e:"The starting point is the vision, values and goals (normative). Then the environment and the company are analysed, forecasts made and everything combined in the SWOT analysis – only then are strategies derived."},hu:{q:"Rendezd helyes sorrendbe a stratégiaalkotás lépéseit.",o:["A normatív menedzsment irányelveinek átvétele","Külső és belső elemzés elvégzése","Előrejelzések készítése a jövőbeli fejleményekről","Az eredmények összefoglalása SWOT-elemzésben","Lehetséges stratégiák kidolgozása"],e:"A kiindulópont a jövőkép, az értékek és a célok (normatív szint). Ezután elemzik a környezetet és a vállalatot, előrejelzéseket készítenek, majd mindent a SWOT-elemzésben foglalnak össze – csak ebből vezetik le a stratégiákat."}},{type:"match",level:2,de:{q:"Ordne Loopys Plänen die passende Wachstumsstrategie nach Ansoff zu.",p:[["Mengenrabatt und mehr Werbung für bestehende Kund:innen","Marktdurchdringung"],["Bisherige Bonbons auch in Deutschland verkaufen","Marktentwicklung"],["Zuckerfreie Bonbons für die Stammkundschaft","Produktentwicklung"],["Ein Fitnessstudio für eine neue Zielgruppe eröffnen","Diversifikation"]],e:"Ansoff-Matrix: bestehendes Produkt + bestehender Markt = Marktdurchdringung; bestehendes Produkt + neuer Markt = Marktentwicklung; neues Produkt + bestehender Markt = Produktentwicklung; neues Produkt + neuer Markt = Diversifikation."},en:{q:"Match Loopy’s plans with the right Ansoff growth strategy.",p:[["Volume discounts and more advertising for existing customers","Market penetration"],["Selling the existing sweets in Germany as well","Market development"],["Sugar-free sweets for regular customers","Product development"],["Opening a gym for a new target group","Diversification"]],e:"Ansoff matrix: existing product + existing market = market penetration; existing product + new market = market development; new product + existing market = product development; new product + new market = diversification."},hu:{q:"Párosítsd Loopy terveit a megfelelő Ansoff-féle növekedési stratégiával.",p:[["Mennyiségi kedvezmény és több reklám a meglévő vevőknek","Piacpenetráció"],["A meglévő cukorkák értékesítése Németországban is","Piacfejlesztés"],["Cukormentes cukorkák a törzsvásárlóknak","Termékfejlesztés"],["Edzőterem nyitása egy új célcsoportnak","Diverzifikáció"]],e:"Ansoff-mátrix: meglévő termék + meglévő piac = piacpenetráció; meglévő termék + új piac = piacfejlesztés; új termék + meglévő piac = termékfejlesztés; új termék + új piac = diverzifikáció."}},{type:"mc",level:2,correctIndex:1,de:{q:"Ein Sportfachgeschäft in Linz hat keinen Webshop (Schwäche). Gleichzeitig kaufen immer mehr Kund:innen Sportartikel online (Chance). Welche Strategie empfiehlt die SWOT-Analyse?",o:["S-O: Stärken nutzen, um die Chance zu ergreifen","W-O: Schwäche überwinden, um die Chance zu nutzen","S-T: Stärken nutzen, um Risiken abzuwehren","W-T: Schwäche abbauen, damit sie kein Risiko wird"],e:"Schwäche (W) trifft auf Chance (O) → W-O-Strategie: einen Webshop aufbauen, um vom Online-Trend zu profitieren. S-O würde eine vorhandene Stärke voraussetzen, T-Strategien ein Risiko."},en:{q:"A sports shop in Linz has no online shop (weakness). At the same time, more and more customers buy sports goods online (opportunity). Which strategy does the SWOT analysis recommend?",o:["S-O: use strengths to seize the opportunity","W-O: overcome the weakness to use the opportunity","S-T: use strengths to fend off threats","W-T: reduce the weakness so it does not become a threat"],e:"A weakness (W) meets an opportunity (O) → W-O strategy: build an online shop to benefit from the online trend. S-O would require an existing strength, the T strategies a threat."},hu:{q:"Egy linzi sportszaküzletnek nincs webáruháza (gyengeség). Közben egyre több vásárló vesz online sportszereket (lehetőség). Melyik stratégiát javasolja a SWOT-elemzés?",o:["S-O: az erősségek kihasználása a lehetőség megragadására","W-O: a gyengeség leküzdése a lehetőség kihasználására","S-T: az erősségek kihasználása a veszélyek elhárítására","W-T: a gyengeség csökkentése, hogy ne váljon veszéllyé"],e:"Gyengeség (W) találkozik lehetőséggel (O) → W-O stratégia: webáruház kiépítése, hogy a vállalat profitáljon az online trendből. Az S-O meglévő erősséget, a T-stratégiák pedig veszélyt feltételeznének."}},{type:"mc",level:3,correctIndex:1,de:{q:"Eine kleine Zuckerfabrik kann ihren Zucker nur an zwei große Lebensmittelketten verkaufen. Diese können jederzeit auf ausländischen Zucker umsteigen. Welche Kraft nach Porter ist hier besonders stark?",o:["Verhandlungsstärke der Lieferanten","Verhandlungsstärke der Kunden","Bedrohung durch neue Wettbewerber","Bedrohung durch Substitute"],e:"Aus Sicht der Zuckerfabrik sind die Ketten ihre KUNDEN: wenige Abnehmer und ein einfacher Wechsel → hohe Verhandlungsstärke der Kunden. Die Falle: Die Fabrik ist selbst Lieferant, die Kraft „Lieferanten“ betrifft aber IHRE Lieferanten."},en:{q:"A small sugar factory can only sell its sugar to two large supermarket chains. These can switch to foreign sugar at any time. Which of Porter’s forces is particularly strong here?",o:["Bargaining power of suppliers","Bargaining power of customers","Threat of new entrants","Threat of substitutes"],e:"From the sugar factory’s point of view, the chains are its CUSTOMERS: few buyers and easy switching → strong bargaining power of customers. The trap: the factory is itself a supplier, but the force “suppliers” refers to ITS suppliers."},hu:{q:"Egy kis cukorgyár csak két nagy élelmiszerláncnak tudja eladni a cukrát. Ezek bármikor átállhatnak külföldi cukorra. Porter melyik versenyereje különösen erős itt?",o:["A beszállítók alkuereje","A vevők alkuereje","Új versenytársak belépésének veszélye","A helyettesítő termékek veszélye"],e:"A cukorgyár szemszögéből a láncok a VEVŐI: kevés vevő és könnyű váltás → a vevők alkuereje nagy. A csapda: a gyár maga is beszállító, de a „beszállítók” erő az Ő beszállítóira vonatkozik."}},{type:"number",level:3,value:5,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Eine Tischlerei plant die Teilbudgets Material 80.000 €, Personal 120.000 € und Sonstiges 50.000 €. Am Jahresende betragen die tatsächlichen Gesamtkosten 262.500 €. Um wie viel Prozent wurde das Gesamtbudget überschritten?",e:"Gesamtbudget = 80.000 + 120.000 + 50.000 = 250.000 €. Abweichung = 262.500 − 250.000 = 12.500 €. 12.500 ÷ 250.000 × 100 = 5 %. In der Abweichungsanalyse sucht man nun die Ursachen und steuert gegen."},en:{q:"A joinery plans partial budgets of €80,000 for materials, €120,000 for personnel and €50,000 for other costs. At the end of the year, actual total costs amount to €262,500. By what percentage was the master budget exceeded?",e:"Master budget = 80,000 + 120,000 + 50,000 = €250,000. Variance = 262,500 − 250,000 = €12,500. 12,500 ÷ 250,000 × 100 = 5%. The variance analysis then looks for the causes and takes corrective action."},hu:{q:"Egy asztalosüzem a következő részköltségvetéseket tervezi: anyag 80 000 €, személyi 120 000 €, egyéb 50 000 €. Év végén a tényleges összköltség 262 500 €. Hány százalékkal lépték túl a teljes költségvetést?",e:"Teljes költségvetés = 80 000 + 120 000 + 50 000 = 250 000 €. Eltérés = 262 500 − 250 000 = 12 500 €. 12 500 ÷ 250 000 × 100 = 5%. Az eltéréselemzés ezután feltárja az okokat, és beavatkozik."}}],"organisieren-und-fuehren":[{type:"tf",level:1,correct:!0,de:{q:"In einem Flussdiagramm werden Start und Ende mit einer abgerundeten Form dargestellt",e:"Richtig – Start/Ende = abgerundete Form, Prozessschritt = Rechteck, Entscheidung = Raute, Ablauflinie = Pfeil."},en:{q:"In a flowchart, start and end are shown with a rounded shape",e:"True – start/end = rounded shape, process step = rectangle, decision = diamond, flow line = arrow."},hu:{q:"A folyamatábrán a kezdetet és a véget lekerekített alakzat jelöli",e:"Igaz – kezdet/vég = lekerekített alakzat, folyamatlépés = téglalap, döntés = rombusz, folyamatvonal = nyíl."}},{type:"tf",level:2,correct:!0,de:{q:"Stabstellen können sowohl im Einliniensystem als auch im Mehrliniensystem eingesetzt werden",e:"Richtig – Stabstellen (z. B. Assistenz, Controlling, Rechtsabteilung) beraten Instanzen ohne Weisungsbefugnis. Sie lassen sich laut Buch in beiden Leitungssystemen einsetzen."},en:{q:"Staff positions can be used both in a line organisation and in a multiple-line organisation",e:"True – staff positions (e.g. assistant, controlling, legal department) advise managers without authority to give instructions. According to the book, they can be used in both systems."},hu:{q:"Törzskari munkakörök egyvonalas és többvonalas szervezetben is alkalmazhatók",e:"Igaz – a törzskari munkakörök (pl. asszisztencia, kontrolling, jogi osztály) utasítási jog nélkül adnak tanácsot a vezetőknek. A tankönyv szerint mindkét irányítási rendszerben alkalmazhatók."}},{type:"tf",level:3,correct:!1,de:{q:"Beim Management by Results werden die Ziele gemeinsam mit den Mitarbeiter:innen vereinbart",e:"Falsch – bei Management by Results werden Ergebnisse VORGEGEBEN und kontrolliert. Die gemeinsame Zielvereinbarung ist das Kennzeichen von Management by Objectives."},en:{q:"In management by results, goals are agreed together with the employees",e:"False – in management by results, results are SET from above and checked. Jointly agreeing goals is the hallmark of management by objectives."},hu:{q:"Az eredmények szerinti vezetésnél (management by results) a célokat a munkatársakkal közösen állapítják meg",e:"Hamis – a management by results esetén az eredményeket ELŐÍRJÁK és ellenőrzik. A közös célmegállapodás a célok szerinti vezetés (management by objectives) ismertetőjegye."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Vorteile hat das Einliniensystem? Wähle alle zutreffenden.",o:["Übersichtlichkeit","Klare Verantwortung","Kurze Kommunikationswege","Klarer Weisungsweg","Entlastung der oberen Instanzen"],e:"Im Einliniensystem hat jede Stelle nur eine Instanz → übersichtlich, klare Verantwortung und Weisungswege. Kurze Infowege und Entlastung der Leitung sind Vorteile des Mehrliniensystems; im Einliniensystem sind die Wege lang und obere Instanzen stark belastet."},en:{q:"What are the advantages of a line organisation? Select all that apply.",o:["Clear structure","Clear responsibility","Short communication channels","Clear chain of command","Relief for the upper levels of management"],e:"In a line organisation, each position has only one superior → clear structure, responsibility and chain of command. Short information channels and relief for management are advantages of the multiple-line system; in a line organisation, channels are long and upper levels are heavily loaded."},hu:{q:"Milyen előnyei vannak az egyvonalas szervezetnek? Jelöld meg az összes helyeset.",o:["Áttekinthetőség","Egyértelmű felelősség","Rövid kommunikációs utak","Egyértelmű utasítási út","A felső vezetési szintek tehermentesítése"],e:"Az egyvonalas rendszerben minden munkakörnek csak egy felettese van → áttekinthető, egyértelmű a felelősség és az utasítási út. A rövid információs utak és a vezetés tehermentesítése a többvonalas rendszer előnyei; az egyvonalas rendszerben hosszúak az utak, és a felső szintek túlterheltek."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen zu den Entscheidungsarten im Vroom-Yetton-Modell treffen zu? Wähle alle zutreffenden.",o:["AII: Die Führungskraft entscheidet allein, nachdem sie Informationen eingeholt hat","BII: Die Führungskraft entscheidet allein, nachdem sie das Problem mit der Gruppe besprochen hat","GII: Die Gruppe entscheidet gemeinsam","BI: Die Gruppe entscheidet gemeinsam mit der Führungskraft","AI: Die Führungskraft entscheidet nach Beratung mit einer Person"],e:"A = autoritär (AI allein, AII nach Infos), B = Beratung (BI mit einer Person, BII mit der Gruppe – entscheiden tut aber die Führungskraft), G = Gruppenentscheidung (GII). Je wichtiger die Akzeptanz, desto eher B oder G."},en:{q:"Which statements about the decision types in the Vroom-Yetton model are correct? Select all that apply.",o:["AII: the manager decides alone after gathering information","BII: the manager decides alone after discussing the problem with the group","GII: the group decides together","BI: the group decides together with the manager","AI: the manager decides after consulting one person"],e:"A = autocratic (AI alone, AII after gathering information), B = consultation (BI with one person, BII with the group – but the manager decides), G = group decision (GII). The more important acceptance is, the more likely B or G."},hu:{q:"Mely állítások igazak a Vroom–Yetton-modell döntéstípusaira? Jelöld meg az összes helyeset.",o:["AII: a vezető egyedül dönt, miután információt gyűjtött","BII: a vezető egyedül dönt, miután a csoporttal megbeszélte a problémát","GII: a csoport közösen dönt","BI: a csoport a vezetővel együtt dönt","AI: a vezető egy személlyel való konzultáció után dönt"],e:"A = autoriter (AI egyedül, AII információgyűjtés után), B = konzultáció (BI egy személlyel, BII a csoporttal – de a vezető dönt), G = csoportdöntés (GII). Minél fontosabb az elfogadás, annál inkább B vagy G."}},{type:"order",level:1,de:{q:"Ordne die Führungsstile der Reifegradtheorie (Hersey/Blanchard) vom niedrigsten zum höchsten Reifegrad der Mitarbeiter:innen.",o:["Telling – Unterweisen","Selling – Verkaufen","Participating – Partizipieren","Delegating – Delegieren"],e:"Je reifer (fähiger und motivierter) die Mitarbeiter:innen, desto weniger Vorgaben: von genauen Anweisungen (Telling) über Erklären (Selling) und Beteiligen (Participating) bis zum Abgeben der Aufgabe (Delegating)."},en:{q:"Put the leadership styles of situational leadership (Hersey/Blanchard) in order from the lowest to the highest maturity of the employees.",o:["Telling","Selling","Participating","Delegating"],e:"The more mature (able and motivated) the employees, the fewer instructions: from precise instructions (telling) via explaining (selling) and involving (participating) to handing over the task (delegating)."},hu:{q:"Rendezd az érettségi elmélet (Hersey/Blanchard) vezetési stílusait a munkatársak legalacsonyabb érettségi szintjétől a legmagasabbig.",o:["Telling – utasítás","Selling – meggyőzés","Participating – bevonás","Delegating – delegálás"],e:"Minél érettebbek (képesebbek és motiváltabbak) a munkatársak, annál kevesebb az előírás: a pontos utasítástól (telling) a magyarázaton (selling) és a bevonáson (participating) át a feladat átadásáig (delegating)."}},{type:"match",level:2,de:{q:"Ordne die Positionen im Verhaltensgitter (Aufgaben- . Mitarbeiterorientierung) ihrem Namen zu.",p:[["1.1","Überlebensmanagement"],["9.1","Befehl-Gehorsam-Management"],["1.9","Glacéhandschuh-Management"],["5.5","Organisationsmanagement"],["9.9","Teammanagement"]],e:"Die erste Zahl steht für die Aufgaben-, die zweite für die Mitarbeiterorientierung. 9.1 = nur Leistung, strenge Kontrolle; 1.9 = Wohlfühlklima, wenig Leistung; 9.9 = optimal, Leistung UND Motivation."},en:{q:"Match the positions in the managerial grid (task . people orientation) with their names.",p:[["1.1","Impoverished management"],["9.1","Authority-compliance management"],["1.9","Country club management"],["5.5","Middle-of-the-road management"],["9.9","Team management"]],e:"The first number stands for task orientation, the second for people orientation. 9.1 = only performance, strict control; 1.9 = feel-good climate, little performance; 9.9 = optimal, performance AND motivation."},hu:{q:"Párosítsd a vezetési rács (feladat- . emberorientáció) pozícióit a nevükkel.",p:[["1.1","Túlélő vezetés"],["9.1","Parancsuralmi vezetés"],["1.9","Kesztyűs kezű (klubszerű) vezetés"],["5.5","Középutas (szervezeti) vezetés"],["9.9","Csapatvezetés"]],e:"Az első szám a feladatorientációt, a második az emberorientációt jelöli. 9.1 = csak teljesítmény, szigorú ellenőrzés; 1.9 = jó hangulat, kevés teljesítmény; 9.9 = optimális, teljesítmény ÉS motiváció."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Lebensmittelkonzern ist in die Sparten Süßwaren und Getränke gegliedert. Zusätzlich gibt es zentrale Leitungen für Einkauf und Marketing. Produktmanager:innen erhalten Weisungen von der Spartenleitung UND von der Funktionsleitung. Welche Organisationsform liegt vor?",o:["Funktionale Organisation (Einliniensystem)","Divisionale Organisation (Einliniensystem)","Matrixorganisation (Mehrliniensystem)","Stablinienorganisation (Einliniensystem)"],e:"Zwei Weisungslinien – nach Divisionen (Sparten) UND nach Funktionen – kennzeichnen die Matrixorganisation, eine Form des Mehrliniensystems. Bei rein divisionaler oder funktionaler Gliederung hätte jede Stelle nur eine Instanz."},en:{q:"A food group is divided into the divisions confectionery and beverages. In addition, there are central heads of purchasing and marketing. Product managers receive instructions from the division head AND from the functional head. Which organisational form is this?",o:["Functional organisation (line system)","Divisional organisation (line system)","Matrix organisation (multiple-line system)","Line-and-staff organisation (line system)"],e:"Two lines of authority – by divisions AND by functions – are the hallmark of the matrix organisation, a form of the multiple-line system. With a purely divisional or functional structure, each position would have only one superior."},hu:{q:"Egy élelmiszeripari konszern édesség és italok divíziókra tagolódik. Emellett központi beszerzési és marketingvezetés is működik. A termékmenedzserek a divízióvezetőtől ÉS a funkcionális vezetőtől is kapnak utasítást. Milyen szervezeti formáról van szó?",o:["Funkcionális szervezet (egyvonalas rendszer)","Divizionális szervezet (egyvonalas rendszer)","Mátrixszervezet (többvonalas rendszer)","Törzskari-vonalas szervezet (egyvonalas rendszer)"],e:"A két utasítási vonal – divíziók ÉS funkciók szerint – a mátrixszervezet ismertetőjegye, amely a többvonalas rendszer egyik formája. Tisztán divizionális vagy funkcionális tagolásnál minden munkakörnek csak egy felettese lenne."}},{type:"mc",level:2,correctIndex:0,de:{q:"In einer Steuerberatungskanzlei betreut eine erfahrene Mitarbeiterin ihre Klient:innen völlig eigenständig. Die Chefin greift nur ein, wenn Probleme auftreten. Welches Führungskonzept ist das?",o:["Management by Delegation","Management by Results","Management by Objectives","Management by Motivation"],e:"Eigener Verantwortungsbereich + Eingreifen nur bei Problemen = Management by Delegation. Bei MbO würden Ziele gemeinsam vereinbart, bei MbR Ergebnisse vorgegeben, bei MbM gezielte Leistungsanreize gesetzt."},en:{q:"In a tax consultancy, an experienced employee looks after her clients completely independently. The boss only steps in when problems arise. Which management concept is this?",o:["Management by delegation","Management by results","Management by objectives","Management by motivation"],e:"Own area of responsibility + intervention only when problems arise = management by delegation. In MbO goals would be agreed jointly, in MbR results set from above, in MbM targeted incentives used."},hu:{q:"Egy adótanácsadó irodában egy tapasztalt munkatárs teljesen önállóan gondozza az ügyfeleit. A főnöke csak akkor avatkozik be, ha probléma adódik. Melyik vezetési koncepcióról van szó?",o:["Management by delegation (delegálás útján)","Management by results (eredmények szerint)","Management by objectives (célok szerint)","Management by motivation (motiválás útján)"],e:"Saját felelősségi terület + beavatkozás csak probléma esetén = management by delegation. MbO-nál közösen állapítanák meg a célokat, MbR-nél előírnák az eredményeket, MbM-nél célzott ösztönzőket alkalmaznának."}},{type:"text",level:1,de:{q:"Wie heißt der Führungsstil nach Lewin, bei dem die Mitarbeiter:innen viel Freiraum haben und die Führungskraft nur bei Problemen eingreift?",a:["Laissez-faire","Laissez faire","Laisser-faire","Laissez-faire-Führungsstil","laissez-faire-Stil"],e:"Laissez-faire bietet Freiraum und Kreativität, birgt aber die Gefahr von Überforderung und Kontrollverlust. Die anderen Stile nach Lewin: autoritär und kooperativ."},en:{q:"What is the name of Lewin’s leadership style in which employees have a lot of freedom and the manager only steps in when there are problems?",a:["laissez-faire","laissez faire","laisser-faire","laissez-faire style"],e:"Laissez-faire offers freedom and creativity but carries the risk of employees being overwhelmed and of loss of control. Lewin’s other styles: authoritarian and cooperative."},hu:{q:"Hogy hívják Lewin azon vezetési stílusát, amelyben a munkatársak nagy szabadságot kapnak, és a vezető csak probléma esetén avatkozik be?",a:["laissez-faire","laissez faire","laisser-faire","laissez-faire stílus","engedékeny"],e:"A laissez-faire szabadságot és kreativitást ad, de fennáll a túlterhelés és az ellenőrzés elvesztésének veszélye. Lewin további stílusai: autoriter és kooperatív (demokratikus)."}}],personalbedarfsplanung:[{type:"tf",level:1,correct:!0,de:{q:"Eine Stellenanzeige muss in Österreich eine Angabe zum Gehalt enthalten",e:"Richtig – die Gehaltsangabe ist Pflicht (meist das kollektivvertragliche Mindestgehalt und ob eine Überzahlung möglich ist). Außerdem muss geschlechtsneutral ausgeschrieben werden, z. B. (m/w/d)."},en:{q:"In Austria, a job advertisement must state the salary",e:"True – stating the salary is mandatory (usually the minimum salary under the collective agreement and whether more may be paid). The advertisement must also be gender-neutral, e.g. (m/f/d)."},hu:{q:"Ausztriában egy álláshirdetésnek tartalmaznia kell a fizetésre vonatkozó adatot",e:"Igaz – a fizetés feltüntetése kötelező (általában a kollektív szerződés szerinti minimálbér, és hogy lehetséges-e túlfizetés). Emellett a hirdetésnek nemsemlegesnek kell lennie, pl. (f/n/x)."}},{type:"tf",level:2,correct:!0,de:{q:"Ist der Personalbedarf kleiner als der Ist-Stand, kann statt einer Kündigung auch eine Umschulung eine sinnvolle Maßnahme sein",e:"Richtig – bei Bedarf < Ist-Stand kommt Personalfreisetzung ODER Personalentwicklung (z. B. Umschulung für einen anderen Bereich) in Frage. So bleibt Know-how im Unternehmen."},en:{q:"If the personnel requirement is lower than the actual headcount, retraining can be a sensible measure instead of dismissal",e:"True – if requirement < actual headcount, either releasing staff OR personnel development (e.g. retraining for another area) is possible. This keeps know-how in the company."},hu:{q:"Ha a létszámszükséglet kisebb a tényleges létszámnál, felmondás helyett az átképzés is ésszerű intézkedés lehet",e:"Igaz – ha a szükséglet < tényleges létszám, szóba jöhet a létszámleépítés VAGY a személyzetfejlesztés (pl. átképzés egy másik területre). Így a tudás a vállalatnál marad."}},{type:"tf",level:3,correct:!1,de:{q:"Die Abfertigung aus der Mitarbeitervorsorgekasse wird bei Beendigung des Arbeitsverhältnisses auch dann ausbezahlt, wenn erst ein Jahr lang eingezahlt wurde",e:"Falsch – laut Buch ist eine Auszahlung erst nach mindestens 3 Einzahlungsjahren möglich. Vorher bleibt das Geld in der MVK und wandert in den „Rucksack“ zum nächsten Arbeitgeber."},en:{q:"Severance pay from the employee provision fund (MVK) is paid out when employment ends even if contributions have only been paid for one year",e:"False – according to the book, a payout is only possible after at least 3 years of contributions. Until then the money stays in the fund and moves with the employee in their “backpack” to the next employer."},hu:{q:"A munkavállalói végkielégítési pénztárból (MVK) a munkaviszony megszűnésekor akkor is kifizetik a végkielégítést, ha csak egy évig fizettek be",e:"Hamis – a tankönyv szerint kifizetés csak legalább 3 befizetési év után lehetséges. Addig a pénz a pénztárban marad, és „hátizsákként” a munkavállalóval együtt a következő munkáltatóhoz kerül."}},{type:"multi",level:1,correct:[0,1,2,4],de:{q:"Was prüft ein Unternehmen bei der Vorauswahl der Bewerbungsunterlagen? Wähle alle zutreffenden.",o:["Sind die wichtigsten Kriterien des Anforderungsprofils erfüllt?","Gibt es Lücken im Werdegang?","Gab es häufige Jobwechsel?","Welcher Religion gehört die Person an?","Stimmen Lebenslauf und Zeugnisse überein?"],e:"Bei der Vorauswahl werden die Unterlagen auf Anforderungsprofil, Lücken, Jobwechsel und Stimmigkeit geprüft. Die Religion ist nicht arbeitsrelevant – danach zu fragen ist unzulässig."},en:{q:"What does a company check when pre-selecting application documents? Select all that apply.",o:["Are the most important criteria of the job requirements met?","Are there gaps in the CV?","Were there frequent job changes?","Which religion does the person belong to?","Do the CV and the certificates match?"],e:"In pre-selection, documents are checked for the job requirements, gaps, job changes and consistency. Religion is not relevant to the job – asking about it is not allowed."},hu:{q:"Mit vizsgál egy vállalat a pályázati anyagok előszűrésénél? Jelöld meg az összes helyeset.",o:["Teljesülnek-e a követelményprofil legfontosabb kritériumai?","Vannak-e hézagok a szakmai életútban?","Voltak-e gyakori munkahelyváltások?","Milyen vallású a jelentkező?","Összhangban van-e az önéletrajz a bizonyítványokkal?"],e:"Az előszűrésnél a követelményprofilt, a hézagokat, a munkahelyváltásokat és az adatok összhangját vizsgálják. A vallás nem munkával kapcsolatos – erre rákérdezni nem megengedett."}},{type:"multi",level:3,correct:[0,1,3],de:{q:"Welche Maßnahmen zählen zur internen Personalsuche OHNE Personalbewegung? Wähle alle zutreffenden.",o:["Überstunden","Urlaubsverschiebung","Versetzung in eine andere Abteilung","Personalentwicklung","Beförderung","Innerbetriebliche Stellenausschreibung"],e:"Ohne Personalbewegung wechselt niemand die Stelle: Mehrarbeit (Überstunden), verschobener Urlaub oder Weiterqualifizierung decken den Bedarf. Versetzung, Beförderung und innerbetriebliche Ausschreibung sind interne Suche MIT Personalbewegung."},en:{q:"Which measures count as internal recruitment WITHOUT staff movement? Select all that apply.",o:["Overtime","Postponing holidays","Transfer to another department","Personnel development","Promotion","Internal job posting"],e:"Without staff movement nobody changes position: extra work (overtime), postponed holidays or further training cover the need. Transfer, promotion and internal job postings are internal recruitment WITH staff movement."},hu:{q:"Mely intézkedések tartoznak a személyzetmozgás NÉLKÜLI belső munkaerő-toborzáshoz? Jelöld meg az összes helyeset.",o:["Túlóra","A szabadság elhalasztása","Áthelyezés egy másik osztályra","Személyzetfejlesztés","Előléptetés","Belső álláspályázat"],e:"Személyzetmozgás nélkül senki sem vált munkakört: többletmunka (túlóra), elhalasztott szabadság vagy továbbképzés fedezi a szükségletet. Az áthelyezés, az előléptetés és a belső pályázat személyzetmozgással járó belső toborzás."}},{type:"match",level:1,de:{q:"Ordne die Maßnahmen der passenden Personalentwicklungs-Methode zu.",p:[["Traineeprogramm für Berufseinsteiger:innen","Into the Job"],["Qualitätszirkel mit Kolleg:innen","Near the Job"],["Fördergespräch und Karriereplanung","Along the Job"],["Outplacement-Beratung beim Ausscheiden","Out of the Job"]],e:"Into = Vorbereitung auf die Stelle, Near = nahe am Arbeitsplatz (Projekte, Qualitätszirkel), Along = laufbahnbegleitend, Out of = Ausstieg (Ruhestandsvorbereitung, Outplacement)."},en:{q:"Match the measures with the right personnel development method.",p:[["Trainee programme for career starters","Into the job"],["Quality circle with colleagues","Near the job"],["Development review and career planning","Along the job"],["Outplacement counselling when leaving","Out of the job"]],e:"Into = preparing for the job, near = close to the workplace (projects, quality circles), along = accompanying the career, out of = leaving (retirement preparation, outplacement)."},hu:{q:"Párosítsd az intézkedéseket a megfelelő személyzetfejlesztési módszerrel.",p:[["Gyakornoki (trainee) program pályakezdőknek","Into the job"],["Minőségi kör a kollégákkal","Near the job"],["Fejlesztési beszélgetés és karriertervezés","Along the job"],["Outplacement-tanácsadás távozáskor","Out of the job"]],e:"Into = felkészítés a munkakörre, near = a munkahely közelében (projektek, minőségi körök), along = a pályafutást kísérő, out of = kilépés (nyugdíjra való felkészítés, outplacement)."}},{type:"match",level:2,de:{q:"Ordne jedem Fall die passende Art der Beendigung des Arbeitsverhältnisses zu.",p:[["Befristeter Vertrag für die Sommersaison endet am 31. August","Zeitablauf"],["Mitarbeiter stiehlt aus der Kassa, Chefin beendet sofort","Entlassung"],["Seit Monaten kein Gehalt, Mitarbeiterin beendet sofort","Austritt"],["Beide einigen sich auf ein Ende in zwei Wochen","Einvernehmliche Auflösung"],["Neuer Mitarbeiter wird in der zweiten Woche ohne Grund beendet","Lösung in der Probezeit"]],e:"Zeitablauf = befristet, endet automatisch. Entlassung = Arbeitgeber, sofort, schwerer Verstoß. Austritt = Arbeitnehmer, sofort, schwerer Verstoß des Arbeitgebers. Einvernehmlich = keine Fristen. Probezeit (max. 1 Monat) = jederzeit ohne Grund."},en:{q:"Match each case with the right way of ending the employment relationship.",p:[["Fixed-term contract for the summer season ends on 31 August","Expiry of term"],["Employee steals from the till, the boss ends it immediately","Summary dismissal"],["No salary for months, the employee quits immediately","Resignation for cause"],["Both agree to end it in two weeks","Termination by mutual consent"],["New employee is let go in the second week without reason","Termination during probation"]],e:"Expiry = fixed-term, ends automatically. Summary dismissal = employer, immediate, serious breach. Resignation for cause = employee, immediate, serious breach by the employer. Mutual consent = no notice periods. Probation (max. 1 month) = any time without reason."},hu:{q:"Párosítsd az eseteket a munkaviszony megszűnésének megfelelő módjával.",p:[["A nyári idényre szóló határozott idejű szerződés augusztus 31-én lejár","Határidő lejárta"],["A munkatárs lop a kasszából, a főnök azonnal megszünteti","Azonnali hatályú elbocsátás"],["Hónapok óta nincs fizetés, a munkatárs azonnal kilép","Munkavállalói azonnali kilépés"],["Mindketten megegyeznek, hogy két hét múlva vége","Közös megegyezéses megszüntetés"],["Az új munkatársat a második héten indoklás nélkül elküldik","Megszüntetés a próbaidő alatt"]],e:"Határidő lejárta = határozott idejű, automatikusan megszűnik. Elbocsátás = munkáltató, azonnal, súlyos kötelezettségszegés miatt. Kilépés = munkavállaló, azonnal, a munkáltató súlyos mulasztása miatt. Közös megegyezés = nincs határidő. Próbaidő (max. 1 hónap) = bármikor, indoklás nélkül."}},{type:"mc",level:2,correctIndex:2,de:{q:"Eine Hotelkette eröffnet im Frühjahr ein neues Haus in Graz. Die Personalabteilung fragt: „An welchem Standort brauchen wir die neuen Mitarbeiter:innen?“ Welche Dimension des Personalbedarfs ist das?",o:["Quantitativer Personalbedarf","Qualitativer Personalbedarf","Örtlicher Personalbedarf","Zeitlicher Personalbedarf"],e:"Die Frage nach dem WO betrifft den örtlichen Personalbedarf. Quantitativ = wie viele, qualitativ = welche Qualifikationen, zeitlich = wann und wie lange."},en:{q:"A hotel chain opens a new hotel in Graz in spring. The HR department asks: “At which location do we need the new employees?” Which dimension of personnel requirements is this?",o:["Quantitative personnel requirement","Qualitative personnel requirement","Local personnel requirement","Temporal personnel requirement"],e:"The question WHERE concerns the local personnel requirement. Quantitative = how many, qualitative = which qualifications, temporal = when and for how long."},hu:{q:"Egy szállodalánc tavasszal új szállodát nyit Grazban. A HR-osztály azt kérdezi: „Melyik telephelyen van szükségünk az új munkatársakra?” A létszámszükséglet melyik dimenziójáról van szó?",o:["Mennyiségi létszámszükséglet","Minőségi létszámszükséglet","Területi (helyi) létszámszükséglet","Időbeli létszámszükséglet"],e:"A HOL kérdése a területi létszámszükségletre vonatkozik. Mennyiségi = hány fő, minőségi = milyen képzettség, időbeli = mikor és mennyi ideig."}},{type:"mc",level:3,correctIndex:1,de:{q:"Eine Angestellte ist seit 4 Jahren bei einer GmbH beschäftigt. Die GmbH will ihr zum 30. Juni (Quartalsende) kündigen. Bis wann muss die Kündigung der Angestellten laut Buch spätestens zugehen?",o:["31. Mai","30. April","15. Mai","31. März"],e:"Im 3.–5. Dienstjahr beträgt die Frist bei Arbeitgeberkündigung 2 Monate. Termin 30. Juni minus 2 Monate → Zugang spätestens am 30. April. 15. Mai wäre die 6-Wochen-Frist (1.–2. Jahr), 31. März die 3-Monats-Frist (ab dem 6. Jahr)."},en:{q:"A salaried employee has worked for a GmbH for 4 years. The company wants to give her notice to 30 June (end of the quarter). According to the book, by when must she receive the notice at the latest?",o:["31 May","30 April","15 May","31 March"],e:"In the 3rd–5th year of service, the notice period for the employer is 2 months. Termination date 30 June minus 2 months → notice must be received by 30 April. 15 May would be the 6-week period (years 1–2), 31 March the 3-month period (from year 6)."},hu:{q:"Egy alkalmazott 4 éve dolgozik egy Kft.-nél. A cég június 30-i hatállyal (negyedév vége) fel akar mondani neki. A tankönyv szerint legkésőbb mikor kell a felmondást kézhez kapnia?",o:["Május 31.","Április 30.","Május 15.","Március 31."],e:"A 3–5. szolgálati évben a munkáltatói felmondási idő 2 hónap. Megszűnés napja június 30. mínusz 2 hónap → legkésőbb április 30-án kell kézhez kapnia. Május 15. a 6 hetes (1–2. év), március 31. a 3 hónapos határidő lenne (a 6. évtől)."}},{type:"number",level:2,value:7.7,tol:.01,unit:{de:"Stunden",en:"hours",hu:"óra"},de:{q:"Einem Angestellten wird vom Arbeitgeber gekündigt. Seine Wochenarbeitszeit beträgt laut KV 38,5 Stunden. Wie viele Stunden bezahlte Freizeit pro Woche stehen ihm während der Kündigungsfrist für die Postensuche zu?",e:"Postensuchtage: 1/5 der wöchentlichen Arbeitszeit bezahlt frei, wenn der Arbeitgeber kündigt. 38,5 ÷ 5 = 7,7 Stunden pro Woche. Der Anspruch besteht laut Buch bei Kündigung durch den Arbeitgeber."},en:{q:"An employee is given notice by his employer. His weekly working time under the collective agreement is 38.5 hours. How many hours of paid time off per week is he entitled to during the notice period to look for a new job?",e:"Job-search time: 1/5 of the weekly working time off with pay if the employer gives notice. 38.5 ÷ 5 = 7.7 hours per week. According to the book, the entitlement applies when the employer gives notice."},hu:{q:"Egy alkalmazottnak a munkáltató felmond. Heti munkaideje a kollektív szerződés szerint 38,5 óra. Hány óra fizetett szabadidő jár neki hetente a felmondási idő alatt álláskeresésre?",e:"Álláskeresési idő: munkáltatói felmondás esetén a heti munkaidő 1/5-e fizetett szabadidőként jár. 38,5 ÷ 5 = 7,7 óra hetente. A tankönyv szerint ez a jog munkáltatói felmondás esetén illeti meg."}}],personaleinsatzgestaltung:[{type:"tf",level:1,correct:!0,de:{q:"Die Pflichten der Arbeitnehmer:innen sind zugleich die Rechte der Arbeitgeber:innen – und umgekehrt",e:"Richtig – z. B. ist die Arbeitspflicht des Arbeitnehmers das Recht des Arbeitgebers auf Arbeitsleistung, die Entgeltpflicht des Arbeitgebers das Recht des Arbeitnehmers auf Lohn bzw. Gehalt."},en:{q:"The duties of employees are at the same time the rights of employers – and vice versa",e:"True – e.g. the employee’s duty to work is the employer’s right to the work performance, and the employer’s duty to pay is the employee’s right to wages or salary."},hu:{q:"A munkavállalók kötelezettségei egyben a munkáltatók jogai – és fordítva",e:"Igaz – pl. a munkavállaló munkavégzési kötelezettsége a munkáltató joga a munkateljesítményre, a munkáltató bérfizetési kötelezettsége pedig a munkavállaló joga a bérre vagy fizetésre."}},{type:"tf",level:2,correct:!1,de:{q:"Um in den Betriebsrat gewählt zu werden, genügt es, 16 Jahre alt zu sein",e:"Falsch – ab 16 hat man das AKTIVE Wahlrecht (darf wählen). Für das PASSIVE Wahlrecht (gewählt werden) muss man mindestens 18 sein und seit 6 Monaten im Betrieb arbeiten."},en:{q:"To be elected to the works council, it is enough to be 16 years old",e:"False – from 16 you have the ACTIVE right to vote (you may vote). For the PASSIVE right (to be elected), you must be at least 18 and have worked in the company for 6 months."},hu:{q:"Ahhoz, hogy valakit az üzemi tanácsba válasszanak, elég 16 évesnek lennie",e:"Hamis – 16 éves kortól van AKTÍV választójog (szavazhat). A PASSZÍV választójoghoz (megválasztható legyen) legalább 18 évesnek kell lennie, és 6 hónapja az üzemben kell dolgoznia."}},{type:"tf",level:3,correct:!1,de:{q:"Den vollen Urlaubsanspruch für das erste Arbeitsjahr erwirbt man erst, wenn man ein ganzes Jahr im Betrieb gearbeitet hat",e:"Falsch – das volle Urlaubsausmaß (25 Arbeitstage bei einer Fünftagewoche) entsteht laut Buch bereits nach 6 Monaten. Die Urlaubszeit muss aber mit dem Arbeitgeber vereinbart werden."},en:{q:"You only acquire the full holiday entitlement for the first year of employment once you have worked in the company for a whole year",e:"False – according to the book, the full holiday entitlement (25 working days with a five-day week) arises after just 6 months. The timing of the holiday must, however, be agreed with the employer."},hu:{q:"Az első munkaévre járó teljes szabadságot csak akkor szerzi meg a munkavállaló, ha egy egész évet ledolgozott az üzemben",e:"Hamis – a tankönyv szerint a teljes szabadság (ötnapos munkahétnél 25 munkanap) már 6 hónap után jár. A szabadság időpontjában azonban meg kell állapodni a munkáltatóval."}},{type:"multi",level:1,correct:[0,1,3,5],de:{q:"Welche Pflichten gehören zur FÜRSORGEPFLICHT des Arbeitgebers? Wähle alle zutreffenden.",o:["Schutz vor Gefahren am Arbeitsplatz","Gleichbehandlung der Mitarbeiter:innen","Verschwiegenheit über Betriebsgeheimnisse","Sonderschutz für Jugendliche und Schwangere","Konkurrenzverbot","Schutz der Gesundheit"],e:"Die Fürsorgepflicht ist eine Arbeitgeberpflicht: Schutz vor Gefahren, Gesundheit, Gleichbehandlung, Sonderschutz. Verschwiegenheit und Konkurrenzverbot gehören zur TREUEPFLICHT des Arbeitnehmers."},en:{q:"Which obligations belong to the employer’s DUTY OF CARE? Select all that apply.",o:["Protection from hazards at work","Equal treatment of employees","Confidentiality about trade secrets","Special protection for young people and pregnant women","Non-compete obligation","Protection of health"],e:"The duty of care is an employer’s obligation: protection from hazards, health, equal treatment, special protection. Confidentiality and the non-compete obligation belong to the employee’s DUTY OF LOYALTY."},hu:{q:"Mely kötelezettségek tartoznak a munkáltató GONDOSKODÁSI kötelezettségéhez? Jelöld meg az összes helyeset.",o:["Védelem a munkahelyi veszélyekkel szemben","A munkatársak egyenlő bánásmódja","Titoktartás az üzleti titkokról","Fiatalkorúak és várandósok különleges védelme","Versenytilalom","Az egészség védelme"],e:"A gondoskodási kötelezettség a munkáltatót terheli: veszélyek elleni védelem, egészség, egyenlő bánásmód, különleges védelem. A titoktartás és a versenytilalom a munkavállaló HŰSÉGKÖTELEZETTSÉGÉHEZ tartozik."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen zum Stufenbau im Arbeitsrecht treffen zu? Wähle alle zutreffenden.",o:["Der Kollektivvertrag wird von den Sozialpartnern (Gewerkschaft und Wirtschaftskammer) für eine Branche abgeschlossen","Eine Betriebsvereinbarung wird zwischen Betriebsrat und Arbeitgeber geschlossen","Der Arbeitsvertrag darf ein höheres Gehalt vorsehen als der Kollektivvertrag","Eine Betriebsvereinbarung darf ein niedrigeres Entgelt als der KV festlegen, wenn der Betriebsrat zustimmt","Das Europarecht steht im Stufenbau unter den nationalen Gesetzen"],e:"Reihenfolge: Europarecht → Gesetze → KV → Betriebsvereinbarung → Einzelarbeitsvertrag. Untere Stufen dürfen nur ZUGUNSTEN der Arbeitnehmer:innen abweichen – ein niedrigeres Entgelt als im KV ist auch mit Zustimmung des Betriebsrats unzulässig."},en:{q:"Which statements about the hierarchy of norms in labour law are correct? Select all that apply.",o:["The collective agreement is concluded by the social partners (trade union and Chamber of Commerce) for an industry","A works agreement is concluded between the works council and the employer","The employment contract may provide for a higher salary than the collective agreement","A works agreement may set lower pay than the collective agreement if the works council agrees","EU law ranks below national laws in the hierarchy"],e:"Order: EU law → laws → collective agreement → works agreement → individual employment contract. Lower levels may only deviate IN FAVOUR of employees – pay below the collective agreement is not allowed, even with the works council’s consent."},hu:{q:"Mely állítások igazak a munkajogi jogforrási hierarchiára? Jelöld meg az összes helyeset.",o:["A kollektív szerződést a szociális partnerek (szakszervezet és gazdasági kamara) kötik meg egy ágazatra","Az üzemi megállapodást az üzemi tanács és a munkáltató köti meg","A munkaszerződés magasabb fizetést írhat elő, mint a kollektív szerződés","Az üzemi megállapodás a kollektív szerződésnél alacsonyabb bért is megállapíthat, ha az üzemi tanács beleegyezik","Az uniós jog a hierarchiában a nemzeti törvények alatt áll"],e:"Sorrend: uniós jog → törvények → kollektív szerződés → üzemi megállapodás → egyéni munkaszerződés. Az alsóbb szintek csak a munkavállalók JAVÁRA térhetnek el – a kollektív szerződésnél alacsonyabb bér az üzemi tanács beleegyezésével sem megengedett."}},{type:"order",level:1,de:{q:"Ordne die Stufen der Bedürfnispyramide nach Maslow von unten (Basis) nach oben.",o:["Grundbedürfnisse","Sicherheit","Soziale Bedürfnisse","Anerkennung","Selbstverwirklichung"],e:"Erst wenn untere Bedürfnisse erfüllt sind, werden höhere wichtig: Grundbedürfnisse (Verpflegung) → Sicherheit (faires Entgelt, unbefristeter Vertrag) → Soziales (Betriebsklima) → Anerkennung (Lob, Prämien) → Selbstverwirklichung (Weiterbildung, Karriere)."},en:{q:"Put the levels of Maslow’s hierarchy of needs in order from the bottom (base) to the top.",o:["Basic needs","Safety","Social needs","Esteem","Self-actualisation"],e:"Only once lower needs are met do higher ones become important: basic needs (food) → safety (fair pay, permanent contract) → social (working atmosphere) → esteem (praise, bonuses) → self-actualisation (training, career)."},hu:{q:"Rendezd a Maslow-féle szükségletpiramis szintjeit alulról (az alaptól) felfelé.",o:["Alapvető (fiziológiai) szükségletek","Biztonság","Társas szükségletek","Elismerés","Önmegvalósítás"],e:"Csak ha az alsóbb szükségletek teljesültek, válnak fontossá a magasabbak: alapszükségletek (étkezés) → biztonság (tisztességes bér, határozatlan idejű szerződés) → társas (munkahelyi légkör) → elismerés (dicséret, prémium) → önmegvalósítás (továbbképzés, karrier)."}},{type:"match",level:2,de:{q:"Ordne jedem Fall die passende Maßnahme der Arbeitsgestaltung zu.",p:[["Verkäuferin übernimmt zusätzlich die Preisauszeichnung","Jobenlargement"],["Verkäufer darf künftig selbst Lieferant:innen auswählen","Jobenrichment"],["Lehrling wechselt alle drei Monate die Abteilung","Jobrotation"],["Mitarbeiterin wählt Beginn und Ende rund um eine Kernzeit","Gleitzeit"]],e:"Jobenlargement = zusätzliche Aufgaben mit GLEICHEN Anforderungen; Jobenrichment = HÖHERE Anforderungen und mehr Verantwortung; Jobrotation = systematischer Arbeitsplatzwechsel; Gleitzeit = flexible Arbeitszeit innerhalb einer Kernarbeitszeit."},en:{q:"Match each case with the right work design measure.",p:[["Shop assistant also takes over price labelling","Job enlargement"],["Shop assistant may now choose suppliers himself","Job enrichment"],["Apprentice changes department every three months","Job rotation"],["Employee chooses start and end time around core hours","Flexitime"]],e:"Job enlargement = additional tasks with the SAME requirements; job enrichment = HIGHER requirements and more responsibility; job rotation = systematic change of workplace; flexitime = flexible working time around core hours."},hu:{q:"Párosítsd az eseteket a megfelelő munkaszervezési intézkedéssel.",p:[["Az eladó az árcímkézést is átveszi","Munkakörbővítés (job enlargement)"],["Az eladó ezentúl maga választhatja ki a beszállítókat","Munkagazdagítás (job enrichment)"],["A tanuló háromhavonta osztályt vált","Munkakör-rotáció (job rotation)"],["A munkatárs törzsidő körül választja meg a kezdést és a végzést","Rugalmas (csúsztatott) munkaidő"]],e:"Munkakörbővítés = további, AZONOS szintű feladatok; munkagazdagítás = MAGASABB követelmények és több felelősség; rotáció = rendszeres munkahelyváltás; rugalmas munkaidő = szabadon választható munkaidő a törzsidő körül."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Buchhalterin einer Steuerberatungskanzlei beendet ihren Arbeitstag wegen eines Jahresabschlusses um 21:30 Uhr. Wann darf sie laut Buch am nächsten Tag frühestens wieder zu arbeiten beginnen?",o:["6:30 Uhr","8:30 Uhr","7:30 Uhr","9:30 Uhr"],e:"Nach Ende der täglichen Arbeitszeit ist eine ununterbrochene Ruhezeit von mindestens 11 Stunden einzuhalten: 21:30 + 11 Stunden = 8:30 Uhr."},en:{q:"An accountant at a tax consultancy finishes work at 9:30 p.m. because of year-end closing. According to the book, when may she start work again at the earliest the next day?",o:["6:30 a.m.","8:30 a.m.","7:30 a.m.","9:30 a.m."],e:"After the end of daily working time, an uninterrupted rest period of at least 11 hours must be observed: 9:30 p.m. + 11 hours = 8:30 a.m."},hu:{q:"Egy adótanácsadó iroda könyvelője az éves zárás miatt 21:30-kor fejezi be a munkát. A tankönyv szerint másnap legkorábban mikor kezdhet újra dolgozni?",o:["6:30-kor","8:30-kor","7:30-kor","9:30-kor"],e:"A napi munkaidő vége után legalább 11 óra megszakítás nélküli pihenőidőt kell biztosítani: 21:30 + 11 óra = 8:30."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Logistikunternehmen plant in der Hochsaison verschiedene Arbeitswochen. Welche Planung verstößt gegen die Höchstarbeitszeit laut Buch (inkl. Überstunden)?",o:["5 Tage zu je 12 Stunden","5 Tage zu je 11 Stunden","6 Tage zu je 10,5 Stunden","4 Tage zu je 12 Stunden und 1 Tag zu 10 Stunden"],e:"Höchstgrenze: 12 Stunden pro Tag UND 60 Stunden pro Woche. 6 × 10,5 = 63 Stunden → über 60, obwohl kein Tag über 12 Stunden liegt. Die anderen Wochen: 60, 55 und 58 Stunden – zulässig."},en:{q:"In peak season, a logistics company plans different working weeks. Which plan violates the maximum working time according to the book (incl. overtime)?",o:["5 days of 12 hours each","5 days of 11 hours each","6 days of 10.5 hours each","4 days of 12 hours and 1 day of 10 hours"],e:"Maximum: 12 hours per day AND 60 hours per week. 6 × 10.5 = 63 hours → over 60, even though no single day exceeds 12 hours. The other weeks: 60, 55 and 58 hours – allowed."},hu:{q:"Egy logisztikai vállalat a főszezonban különböző munkaheteket tervez. Melyik terv sérti a tankönyv szerinti maximális munkaidőt (a túlórákkal együtt)?",o:["5 nap, naponta 12 óra","5 nap, naponta 11 óra","6 nap, naponta 10,5 óra","4 nap 12 órával és 1 nap 10 órával"],e:"Felső határ: napi 12 óra ÉS heti 60 óra. 6 × 10,5 = 63 óra → több mint 60, pedig egyik nap sem haladja meg a 12 órát. A többi hét: 60, 55 és 58 óra – megengedett."}},{type:"number",level:2,value:216,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein Lagerarbeiter verdient 18 € pro Stunde. In einer Woche leistet er 4 Überstunden an Werktagen (50 % Zuschlag) und 3 Überstunden am Sonntag (100 % Zuschlag). Wie viel € erhält er insgesamt für diese Überstunden?",e:"Werktag: 18 × 1,5 = 27 € × 4 = 108 €. Sonntag: 18 × 2 = 36 € × 3 = 108 €. Summe = 108 + 108 = 216 €."},en:{q:"A warehouse worker earns €18 per hour. In one week he works 4 hours of overtime on weekdays (50% surcharge) and 3 hours of overtime on Sunday (100% surcharge). How much in € does he receive in total for this overtime?",e:"Weekday: 18 × 1.5 = €27 × 4 = €108. Sunday: 18 × 2 = €36 × 3 = €108. Total = 108 + 108 = €216."},hu:{q:"Egy raktári dolgozó órabére 18 €. Egy héten hétköznap 4 túlórát (50% pótlék), vasárnap pedig 3 túlórát (100% pótlék) teljesít. Összesen hány €-t kap ezekért a túlórákért?",e:"Hétköznap: 18 × 1,5 = 27 € × 4 = 108 €. Vasárnap: 18 × 2 = 36 € × 3 = 108 €. Összesen = 108 + 108 = 216 €."}}],personalbeurteilung:[{type:"tf",level:1,correct:!1,de:{q:"Akkordlohn und Prämienlohn zählen zu den Zeitlöhnen",e:"Falsch – beide sind Leistungslöhne: Akkordlohn hängt von der Menge ab, Prämienlohn ist Zeitlohn PLUS Prämie für Mehrleistung. Beim reinen Zeitlohn zählt nur die Zeit (Stunde, Monat)."},en:{q:"Piece-rate pay and bonus pay are forms of time-based pay",e:"False – both are performance-based pay: piece-rate pay depends on the quantity, bonus pay is time-based pay PLUS a bonus for extra performance. With pure time-based pay, only the time counts (hour, month)."},hu:{q:"Az akkordbér és a prémiumos bér az időbérek közé tartozik",e:"Hamis – mindkettő teljesítménybér: az akkordbér a mennyiségtől függ, a prémiumos bér időbér PLUSZ prémium a többletteljesítményért. A tiszta időbérnél csak az idő számít (óra, hónap)."}},{type:"tf",level:2,correct:!0,de:{q:"Bei der Selbstbeurteilung ist die Akzeptanz hoch, das Selbstbild weicht aber oft vom Fremdbild ab",e:"Richtig – wer sich selbst beurteilt, akzeptiert das Ergebnis eher. Das Selbstbild deckt sich aber oft nicht mit der Sicht von Vorgesetzten oder Kolleg:innen, daher wird es meist mit einer Fremdbeurteilung kombiniert."},en:{q:"Self-assessment enjoys high acceptance, but the self-image often differs from how others see the person",e:"True – people who assess themselves are more likely to accept the result. But the self-image often does not match the view of supervisors or colleagues, so it is usually combined with an external assessment."},hu:{q:"Az önértékelés elfogadottsága magas, de az önkép gyakran eltér a mások által alkotott képtől",e:"Igaz – aki saját magát értékeli, könnyebben elfogadja az eredményt. Az önkép azonban gyakran nem egyezik a felettesek vagy a kollégák véleményével, ezért általában külső értékeléssel kombinálják."}},{type:"tf",level:3,correct:!0,de:{q:"Urlaubs- und Weihnachtsgeld zählen laut Buch zu den tariflichen Sozialleistungen",e:"Richtig – Urlaubs- und Weihnachtsgeld (13./14. Gehalt) sind in Österreich nicht gesetzlich, sondern im Kollektivvertrag geregelt, also tariflich. Gesetzlich ist z. B. der Arbeitgeberanteil zur Sozialversicherung, freiwillig z. B. die Kantine."},en:{q:"According to the book, holiday pay and Christmas bonus are collective-agreement (tariff) social benefits",e:"True – in Austria, holiday pay and Christmas bonus (13th/14th salary) are not set by law but by the collective agreement, i.e. they are tariff benefits. A statutory example is the employer’s share of social insurance; a voluntary one is the canteen."},hu:{q:"A tankönyv szerint a szabadságpénz és a karácsonyi pénz a kollektív szerződésen alapuló szociális juttatások közé tartozik",e:"Igaz – Ausztriában a szabadságpénzt és a karácsonyi pénzt (13./14. havi fizetés) nem törvény, hanem a kollektív szerződés szabályozza. Törvényi juttatás pl. a munkáltatói társadalombiztosítási járulék, önkéntes pl. az üzemi étkezde."}},{type:"multi",level:1,correct:[0,2,4,5],de:{q:"Welche der folgenden sind QUANTITATIVE Methoden (Kennzahlen) des Personalcontrollings? Wähle alle zutreffenden.",o:["Fluktuationsrate","Mitarbeiterbefragung","Bewerber:innen pro Stelle","Potenzialanalyse","Personalkosten pro Mitarbeiter:in","Anzahl der Überstunden"],e:"Quantitativ = in Zahlen messbar: Fluktuationsrate, Bewerber:innen pro Stelle, Personalkosten, Überstunden, Weiterbildungskosten. Mitarbeiterbefragungen und Potenzialanalysen sind qualitative Methoden."},en:{q:"Which of the following are QUANTITATIVE methods (key figures) of HR controlling? Select all that apply.",o:["Staff turnover rate","Employee survey","Applicants per vacancy","Potential analysis","Personnel costs per employee","Number of overtime hours"],e:"Quantitative = measurable in numbers: turnover rate, applicants per vacancy, personnel costs, overtime, training costs. Employee surveys and potential analyses are qualitative methods."},hu:{q:"Az alábbiak közül melyek a személyügyi kontrolling MENNYISÉGI módszerei (mutatói)? Jelöld meg az összes helyeset.",o:["Fluktuációs ráta","Munkatársi elégedettségi felmérés","Jelentkezők száma álláshelyenként","Potenciálelemzés","Egy munkatársra jutó személyi költség","A túlórák száma"],e:"Mennyiségi = számokkal mérhető: fluktuációs ráta, jelentkezők álláshelyenként, személyi költségek, túlórák, továbbképzési költségek. A munkatársi felmérések és a potenciálelemzések minőségi módszerek."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Erwartungen an die Arbeitswelt werden laut Buch der Generation Y (1981–1995) zugeschrieben? Wähle alle zutreffenden.",o:["Flexibilität","Sinn in der Arbeit","Klare, strenge Hierarchien","Flache Hierarchien","Sicherheit durch lebenslange Loyalität zu einem Betrieb"],e:"Generation Y gilt als teamorientiert und technikaffin und erwartet Flexibilität, Sinn und flache Hierarchien. Klare Hierarchien und Sicherheit sind laut Buch eher die Erwartungen der Babyboomer."},en:{q:"According to the book, which expectations of the working world are attributed to Generation Y (1981–1995)? Select all that apply.",o:["Flexibility","Meaningful work","Clear, strict hierarchies","Flat hierarchies","Security through lifelong loyalty to one company"],e:"Generation Y is seen as team-oriented and tech-savvy and expects flexibility, meaning and flat hierarchies. According to the book, clear hierarchies and security are more the expectations of baby boomers."},hu:{q:"A tankönyv szerint milyen munkahelyi elvárásokat tulajdonítanak az Y generációnak (1981–1995)? Jelöld meg az összes helyeset.",o:["Rugalmasság","Értelmes, tartalmas munka","Világos, szigorú hierarchia","Lapos hierarchia","Biztonság egy vállalathoz való életre szóló hűség révén"],e:"Az Y generáció csapatorientált és technológiakedvelő, rugalmasságot, értelmes munkát és lapos hierarchiát vár el. A tankönyv szerint a világos hierarchia és a biztonság inkább a baby boomerek elvárásai."}},{type:"order",level:1,de:{q:"Ordne die Generationen nach ihrem Geburtszeitraum, beginnend mit der ältesten.",o:["Babyboomer","Generation X","Generation Y","Generation Z","Generation Alpha"],e:"Babyboomer (1946–1964) → Generation X (1965–1980) → Generation Y (1981–1995) → Generation Z (1996–2010) → Generation Alpha (ab 2010). Bis zu 5 Generationen arbeiten heute gleichzeitig in Unternehmen."},en:{q:"Put the generations in order of their birth period, starting with the oldest.",o:["Baby boomers","Generation X","Generation Y","Generation Z","Generation Alpha"],e:"Baby boomers (1946–1964) → Generation X (1965–1980) → Generation Y (1981–1995) → Generation Z (1996–2010) → Generation Alpha (from 2010). Up to 5 generations work in companies at the same time today."},hu:{q:"Rendezd a generációkat születési időszakuk szerint, a legidősebbel kezdve.",o:["Baby boomerek","X generáció","Y generáció","Z generáció","Alfa generáció"],e:"Baby boomerek (1946–1964) → X generáció (1965–1980) → Y generáció (1981–1995) → Z generáció (1996–2010) → Alfa generáció (2010-től). Ma akár 5 generáció is dolgozik egyszerre egy vállalatnál."}},{type:"match",level:2,de:{q:"Ordne jedem Grundsatz „gerechter“ Entlohnung zu, was er berücksichtigt.",p:[["leistungsgerecht","Arbeitsergebnis und Leistung"],["anforderungsgerecht","Schwierigkeit und Aufwand der Arbeit"],["qualifikationsgerecht","die erforderliche Ausbildung"],["marktgerecht","was andere für dieselbe Position zahlen"],["sozial gerecht","Familienstand und Alter"]],e:"Gerechte Entlohnung verbindet mehrere Maßstäbe: Leistung, Anforderung, Qualifikation, Marktniveau und soziale Lage. Eine einzige Größe allein wird selten als fair empfunden."},en:{q:"Match each principle of “fair” pay with what it takes into account.",p:[["performance-based","work results and performance"],["requirement-based","difficulty and effort of the work"],["qualification-based","the training required"],["market-based","what others pay for the same position"],["socially fair","marital status and age"]],e:"Fair pay combines several yardsticks: performance, requirements, qualification, market level and social situation. A single factor on its own is rarely seen as fair."},hu:{q:"Párosítsd az „igazságos” bérezés elveit azzal, amit figyelembe vesznek.",p:[["teljesítményarányos","a munka eredménye és a teljesítmény"],["követelményarányos","a munka nehézsége és ráfordítása"],["képzettségarányos","a szükséges képzettség"],["piackonform","amit mások fizetnek ugyanazért a pozícióért"],["szociálisan igazságos","családi állapot és életkor"]],e:"Az igazságos bérezés több szempontot ötvöz: teljesítmény, követelmények, képzettség, piaci szint és szociális helyzet. Egyetlen tényező önmagában ritkán tűnik méltányosnak."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine börsennotierte AG bietet ihren Mitarbeiter:innen Aktien des eigenen Unternehmens zu einem vergünstigten Preis an. Um welche Form der Mitarbeiterbeteiligung handelt es sich?",o:["Erfolgsbeteiligung","Kapitalbeteiligung","Gewinnbeteiligung","Prämienlohn"],e:"Belegschaftsaktien (oder eine Mitarbeiterstiftung) machen Mitarbeiter:innen zu Miteigentümer:innen → Kapitalbeteiligung. Gewinnbeteiligung = Anteil am ausgeschütteten Gewinn, Erfolgsbeteiligung = Bonus für besondere Leistungen."},en:{q:"A listed stock corporation offers its employees shares in the company at a reduced price. Which form of employee participation is this?",o:["Performance-related participation","Capital participation","Profit sharing","Bonus pay"],e:"Employee shares (or an employee foundation) make employees co-owners → capital participation. Profit sharing = share of the distributed profit, performance-related participation = bonus for special achievements."},hu:{q:"Egy tőzsdén jegyzett részvénytársaság kedvezményes áron kínál saját részvényeket a munkatársainak. A munkavállalói részesedés melyik formájáról van szó?",o:["Eredményrészesedés","Tőkerészesedés","Nyereségrészesedés","Prémiumos bér"],e:"A dolgozói részvények (vagy egy munkavállalói alapítvány) résztulajdonossá teszik a munkatársakat → tőkerészesedés. Nyereségrészesedés = részesedés a kifizetett nyereségből, eredményrészesedés = bónusz különleges teljesítményért."}},{type:"mc",level:3,correctIndex:0,de:{q:"Ein Bauunternehmen zahlt (1) den Arbeitgeberanteil zur Sozialversicherung, (2) eine Schmutzzulage laut Kollektivvertrag und (3) einen Zuschuss zum Fitnessstudio. Welche Zuordnung der Sozialleistungen ist richtig?",o:["(1) gesetzlich, (2) tariflich, (3) freiwillig","(1) tariflich, (2) gesetzlich, (3) freiwillig","(1) gesetzlich, (2) freiwillig, (3) tariflich","(1) freiwillig, (2) tariflich, (3) gesetzlich"],e:"Der SV-Arbeitgeberanteil ist gesetzlich vorgeschrieben, die Schmutzzulage kommt aus dem KV (tariflich), der Fitnesszuschuss ist eine freiwillige Leistung. Typische Falle: KV-Leistungen für gesetzlich halten."},en:{q:"A construction company pays (1) the employer’s share of social insurance, (2) a dirt allowance under the collective agreement and (3) a gym subsidy. Which classification of the social benefits is correct?",o:["(1) statutory, (2) tariff, (3) voluntary","(1) tariff, (2) statutory, (3) voluntary","(1) statutory, (2) voluntary, (3) tariff","(1) voluntary, (2) tariff, (3) statutory"],e:"The employer’s social insurance share is required by law, the dirt allowance comes from the collective agreement (tariff), and the gym subsidy is voluntary. Typical trap: taking collective-agreement benefits for statutory ones."},hu:{q:"Egy építőipari vállalat fizeti (1) a munkáltatói társadalombiztosítási járulékot, (2) a kollektív szerződés szerinti szennyezettségi pótlékot és (3) egy edzőtermi hozzájárulást. Melyik besorolás helyes?",o:["(1) törvényi, (2) kollektív szerződéses, (3) önkéntes","(1) kollektív szerződéses, (2) törvényi, (3) önkéntes","(1) törvényi, (2) önkéntes, (3) kollektív szerződéses","(1) önkéntes, (2) kollektív szerződéses, (3) törvényi"],e:"A munkáltatói tb-járulékot törvény írja elő, a szennyezettségi pótlék a kollektív szerződésből ered, az edzőtermi hozzájárulás önkéntes juttatás. Tipikus csapda: a kollektív szerződéses juttatásokat törvényinek gondolni."}},{type:"number",level:3,value:162,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine Mitarbeiterin in einer Verpackungsabteilung wird im Zeitakkord bezahlt. Der Akkordrichtsatz beträgt 18 € pro Stunde, die Vorgabezeit 12 Minuten pro Stück. An einem Tag schafft sie 45 Stück. Wie hoch ist ihr Akkordlohn für diesen Tag?",e:"Minutenfaktor = 18 € ÷ 60 = 0,30 € pro Minute. Vorgabeminuten = 45 Stück × 12 Min. = 540 Min. Akkordlohn = 540 × 0,30 = 162 €. (Zum Vergleich: 540 Min. = 9 Stunden Vorgabezeit – wer schneller arbeitet, verdient pro tatsächlicher Stunde mehr.)"},en:{q:"An employee in a packaging department is paid by time-based piece rate. The base piece rate is €18 per hour and the standard time is 12 minutes per piece. On one day she completes 45 pieces. What is her piece-rate pay for that day?",e:"Minute factor = €18 ÷ 60 = €0.30 per minute. Standard minutes = 45 pieces × 12 min = 540 min. Piece-rate pay = 540 × 0.30 = €162. (For comparison: 540 min = 9 hours of standard time – whoever works faster earns more per actual hour.)"},hu:{q:"Egy csomagolórészleg munkatársát időakkordban fizetik. Az akkord-alapbér óránként 18 €, a normaidő darabonként 12 perc. Egy nap alatt 45 darabot készít el. Mennyi az aznapi akkordbére?",e:"Percérték = 18 € ÷ 60 = 0,30 € percenként. Normapercek = 45 darab × 12 perc = 540 perc. Akkordbér = 540 × 0,30 = 162 €. (Összehasonlításul: 540 perc = 9 óra normaidő – aki gyorsabban dolgozik, a ténylegesen ledolgozott órára vetítve többet keres.)"}}]},r={produktionsbetriebe:[{type:"tf",level:1,correct:!0,de:{q:"Ein Hersteller von Industrierobotern, der ausschließlich Autowerke beliefert, ist ein Investitionsgüterbetrieb",e:"Richtig. Investitionsgüterbetriebe erzeugen Sachgüter für andere Unternehmen (z. B. Roboter, Fließbänder). Konsumgüterbetriebe liefern dagegen an Endverbraucher:innen."},en:{q:"A manufacturer of industrial robots that supplies only car plants is a capital goods producer",e:"True. Capital goods producers make physical goods for other businesses (e.g. robots, conveyor belts). Consumer goods producers, by contrast, supply end consumers."},hu:{q:"Az az ipari robotokat gyártó vállalat, amely kizárólag autógyárakat lát el, beruházási javakat gyártó üzem",e:"Igaz. A beruházási javakat gyártó üzemek más vállalatok számára állítanak elő tárgyi javakat (pl. robotokat, futószalagokat). A fogyasztási cikkeket gyártó üzemek ezzel szemben a végső fogyasztókat látják el."}},{type:"tf",level:1,correct:!1,de:{q:"Industriebetriebe sind vor allem arbeitsintensiv, Gewerbebetriebe dagegen vor allem anlagenintensiv",e:"Falsch – genau umgekehrt. Gewerbe ist arbeitsintensiv (Material und Arbeitskraft bestimmen), Industrie ist anlagenintensiv (hohes Anlagevermögen, hohe Fixkosten, viel Automatisierung)."},en:{q:"Industrial companies are mainly labour-intensive, whereas trade/craft businesses are mainly capital-intensive",e:"False – it is the other way round. Craft businesses are labour-intensive (materials and labour dominate); industry is capital-intensive (large fixed assets, high fixed costs, lots of automation)."},hu:{q:"Az ipari vállalatok elsősorban munkaigényesek, a kisipari (iparos) vállalkozások viszont elsősorban eszközigényesek",e:"Hamis – éppen fordítva. A kisipar munkaigényes (az anyag és a munkaerő a meghatározó), az ipar eszközigényes (nagy befektetett eszközállomány, magas fix költségek, erős automatizáltság)."}},{type:"tf",level:3,correct:!1,de:{q:"Durch die Fixkostendegression sinken die gesamten Fixkosten eines Betriebs, wenn mehr Stück produziert werden",e:"Falsch. Die gesamten Fixkosten bleiben gleich (z. B. Miete, Abschreibung). Sie verteilen sich nur auf mehr Stück – deshalb sinken die Fixkosten PRO STÜCK."},en:{q:"Through fixed cost degression, a company's total fixed costs fall when more units are produced",e:"False. Total fixed costs stay the same (e.g. rent, depreciation). They are simply spread over more units – which is why fixed costs PER UNIT fall."},hu:{q:"A fix költségek degressziója miatt egy üzem összes fix költsége csökken, ha több darabot gyártanak",e:"Hamis. Az összes fix költség változatlan marad (pl. bérleti díj, értékcsökkenés). Csak több darabra oszlik el – ezért az EGY DARABRA jutó fix költség csökken."}},{type:"multi",level:3,correct:[0,1,3],de:{q:"Welche Standortfaktoren zählen zu den beschaffungsseitigen Faktoren? Wähle alle zutreffenden.",o:["Verfügbarkeit von Arbeitskräften","Nähe zu Lieferanten und Rohstoffen","Kundennähe","Höhe der Mieten","Image des Standorts","Höhe der Steuern"],e:"Beschaffungsseitig sind Fläche, Infrastruktur, Arbeitskräfte, Lieferanten-/Rohstoffnähe, Mieten und Forschung. Steuern zählen zu den produktionsbezogenen, Kundennähe und Image zu den absatzorientierten Faktoren."},en:{q:"Which location factors are procurement-related factors? Select all that apply.",o:["Availability of workers","Proximity to suppliers and raw materials","Proximity to customers","Level of rents","Image of the location","Level of taxes"],e:"Procurement-related factors are land, infrastructure, workers, proximity to suppliers/raw materials, rents and research. Taxes are production-related; proximity to customers and image are sales-oriented factors."},hu:{q:"Mely telephelyi tényezők tartoznak a beszerzési oldali tényezők közé? Jelöld meg az összes helyeset.",o:["Munkaerő rendelkezésre állása","Beszállítók és nyersanyagok közelsége","Vevők közelsége","A bérleti díjak szintje","A telephely imázsa","Az adók mértéke"],e:"Beszerzési oldali tényező a terület, az infrastruktúra, a munkaerő, a beszállítók/nyersanyagok közelsége, a bérleti díjak és a kutatás. Az adók a termeléshez kapcsolódó, a vevők közelsége és az imázs az értékesítési oldali tényezők közé tartoznak."}},{type:"multi",level:2,correct:[1,2,4],de:{q:"Welche Merkmale sind typisch für einen Gewerbebetrieb? Wähle alle zutreffenden.",o:["Hoher Automatisierungsgrad","Die Inhaberin bzw. der Inhaber führt das Unternehmen","Material und Arbeitskraft sind die bestimmenden Faktoren","Hohe Fixkosten durch großes Anlagevermögen","Meist ein Klein- oder Mittelbetrieb"],e:"Gewerbebetriebe sind meist KMU, werden vom Inhaber bzw. von der Inhaberin geführt und sind arbeitsintensiv. Hohe Automatisierung und hohe Fixkosten durch Anlagen kennzeichnen den Industriebetrieb."},en:{q:"Which characteristics are typical of a trade/craft business? Select all that apply.",o:["High degree of automation","The owner manages the business","Materials and labour are the dominant factors","High fixed costs due to large fixed assets","Usually a small or medium-sized business"],e:"Craft businesses are usually SMEs, are run by the owner and are labour-intensive. High automation and high fixed costs from plant and machinery are typical of industrial companies."},hu:{q:"Mely jellemzők tipikusak egy kisipari (iparos) vállalkozásra? Jelöld meg az összes helyeset.",o:["Magas fokú automatizáltság","A tulajdonos vezeti a vállalkozást","Az anyag és a munkaerő a meghatározó tényező","Magas fix költségek a nagy befektetett eszközállomány miatt","Többnyire kis- vagy középvállalkozás"],e:"A kisipari vállalkozások többnyire kkv-k, a tulajdonos vezeti őket, és munkaigényesek. A magas automatizáltság és a gépek miatti magas fix költségek az ipari vállalatra jellemzők."}},{type:"match",level:1,de:{q:"Ordne die Nachhaltigkeitsdimension der passenden Maßnahme eines Produktionsbetriebs zu.",p:[["People – sozial","Weiterbildungsangebote für Mitarbeiter:innen"],["Planet – ökologisch","Umstieg auf Strom aus Photovoltaik"],["Profit – ökonomisch","Gesetze einhalten, keine Korruption"]],e:"Nachhaltige Produktion umfasst drei Dimensionen: sozial (faires Arbeitsumfeld), ökologisch (erneuerbare Energie, Effizienz) und ökonomisch (verantwortungsvoll und fair wirtschaften)."},en:{q:"Match each sustainability dimension with a suitable measure taken by a manufacturer.",p:[["People – social","Training opportunities for employees"],["Planet – ecological","Switching to solar (PV) electricity"],["Profit – economic","Obeying laws, no corruption"]],e:"Sustainable production has three dimensions: social (fair working environment), ecological (renewable energy, efficiency) and economic (doing business responsibly and fairly)."},hu:{q:"Párosítsd a fenntarthatósági dimenziót egy termelő vállalat megfelelő intézkedésével.",p:[["People – társadalmi","Továbbképzési lehetőségek a munkatársaknak"],["Planet – ökológiai","Átállás napelemes áramra"],["Profit – gazdasági","A törvények betartása, korrupciómentesség"]],e:"A fenntartható termelésnek három dimenziója van: társadalmi (tisztességes munkakörnyezet), ökológiai (megújuló energia, hatékonyság) és gazdasági (felelős és tisztességes gazdálkodás)."}},{type:"mc",level:2,correctIndex:2,de:{q:"Eine Papierfabrik sucht einen neuen Standort. Sie braucht große Mengen Holz und Wasser und muss schwere Rohstoffe anliefern lassen. Welcher Standort passt am besten?",o:["Einkaufsstraße in der Wiener Innenstadt mit vielen Passanten","Bürokomplex nahe dem Flughafen mit sehr gutem Image","Gewerbegebiet an einem Fluss mit Bahnanschluss nahe Wäldern","Ortszentrum einer Tourismusgemeinde mit hoher Kaufkraft"],e:"Für Produktionsbetriebe zählen vor allem beschaffungsseitige und produktionsbezogene Faktoren – hier Rohstoffnähe, Wasser und Transportwege. Passant:innen, Image und Kaufkraft sind absatzorientierte Faktoren, die für den Handel wichtiger sind."},en:{q:"A paper mill is looking for a new location. It needs large amounts of wood and water and has heavy raw materials delivered. Which location fits best?",o:["Shopping street in central Vienna with lots of passers-by","Office complex near the airport with an excellent image","Industrial estate on a river with rail access near forests","Centre of a tourist town with high purchasing power"],e:"For manufacturers, procurement- and production-related factors matter most – here proximity to raw materials, water and transport routes. Passers-by, image and purchasing power are sales-oriented factors that matter more to retailers."},hu:{q:"Egy papírgyár új telephelyet keres. Nagy mennyiségű fára és vízre van szüksége, és nehéz nyersanyagokat kell beszállíttatnia. Melyik telephely a legmegfelelőbb?",o:["Bevásárlóutca Bécs belvárosában, sok járókelővel","Irodakomplexum a repülőtér közelében, kiváló imázzsal","Ipari terület folyóparton, vasúttal, erdők közelében","Egy turistaközség központja magas vásárlóerővel"],e:"A termelő vállalatoknál elsősorban a beszerzési oldali és a termeléshez kapcsolódó tényezők számítanak – itt a nyersanyagok és a víz közelsége, valamint a szállítási útvonalak. A járókelők, az imázs és a vásárlóerő értékesítési oldali tényezők, amelyek a kereskedelemnek fontosabbak."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein oberösterreichischer Hersteller von Kunststoffteilen verkauft 80 % seiner Produktion an einen Kunden in den USA. Wegen neuer Zölle baut er ein Werk direkt neben dessen Fabrik in den USA. Was beschreibt diese Entscheidung am besten?",o:["Market-Pull; beschaffungsseitiger Faktor Rohstoffnähe","Follow-the-Customer; absatzorientierter Faktor Kundennähe","Fixkostendegression; produktionsbezogener Faktor Steuern","Follow-the-Customer; beschaffungsseitiger Faktor Arbeitskräfte"],e:"Die Produktion wird dorthin verlegt, wo der wichtigste Kunde ist (Follow-the-Customer), um nah dran zu sein und Zölle zu vermeiden. Ausschlaggebend ist die Kundennähe – ein absatzorientierter Faktor, nicht Rohstoffe oder Arbeitskräfte."},en:{q:"A plastic parts manufacturer from Upper Austria sells 80% of its output to one customer in the USA. Because of new tariffs, it builds a plant right next to that customer's factory in the USA. What best describes this decision?",o:["Market pull; procurement factor proximity to raw materials","Follow-the-customer; sales factor proximity to customers","Fixed cost degression; production factor taxes","Follow-the-customer; procurement factor availability of workers"],e:"Production is moved to where the key customer is (follow-the-customer) to be close by and avoid tariffs. The decisive factor is proximity to the customer – a sales-oriented factor, not raw materials or workers."},hu:{q:"Egy felső-ausztriai műanyagalkatrész-gyártó termelése 80%-át egyetlen amerikai vevőnek adja el. Az új vámok miatt gyárat épít közvetlenül a vevő amerikai üzeme mellé. Mi írja le legjobban ezt a döntést?",o:["Market-Pull; beszerzési oldali tényező: nyersanyagok közelsége","Follow-the-Customer; értékesítési oldali tényező: vevők közelsége","Fix költségek degressziója; termelési tényező: adók","Follow-the-Customer; beszerzési oldali tényező: munkaerő"],e:"A termelést oda telepítik, ahol a legfontosabb vevő van (Follow-the-Customer), hogy közel legyenek hozzá, és elkerüljék a vámokat. A döntő tényező a vevő közelsége – ez értékesítési oldali tényező, nem a nyersanyag vagy a munkaerő."}},{type:"number",level:2,value:3.9,tol:.01,de:{q:"Loopy bewertet einen möglichen Standort für ihre neue Süßwarenfabrik mit der Scoring-Methode (1–5 Punkte): Arbeitskräfte (Gewichtung 40 %) 4 Punkte, Förderungen (35 %) 3 Punkte, Verkehrsanbindung (25 %) 5 Punkte. Wie hoch ist der gewichtete Nutzwert des Standorts?",e:"Punkte × Gewichtung und addieren: 4 · 0,40 = 1,60; 3 · 0,35 = 1,05; 5 · 0,25 = 1,25. Nutzwert = 1,60 + 1,05 + 1,25 = 3,9 Punkte."},en:{q:"Loopy rates a possible location for her new confectionery factory with the scoring method (1–5 points): workers (weight 40%) 4 points, subsidies (35%) 3 points, transport links (25%) 5 points. What is the weighted score of the location?",e:"Multiply points by weight and add: 4 · 0.40 = 1.60; 3 · 0.35 = 1.05; 5 · 0.25 = 1.25. Weighted score = 1.60 + 1.05 + 1.25 = 3.9 points."},hu:{q:"Loopy pontozásos módszerrel (1–5 pont) értékeli új édességgyárának egyik lehetséges telephelyét: munkaerő (súly 40%) 4 pont, támogatások (35%) 3 pont, közlekedési kapcsolatok (25%) 5 pont. Mekkora a telephely súlyozott pontszáma?",e:"A pontokat megszorozzuk a súllyal, majd összeadjuk: 4 · 0,40 = 1,60; 3 · 0,35 = 1,05; 5 · 0,25 = 1,25. Súlyozott pontszám = 1,60 + 1,05 + 1,25 = 3,9 pont."}},{type:"text",level:1,de:{q:"Wie nennt man das Merkmal, durch das sich ein Produkt klar und einzigartig von der Konkurrenz abhebt?",a:["Alleinstellungsmerkmal","USP","Unique Selling Proposition","Unique Selling Point"],e:"Das Alleinstellungsmerkmal (USP) macht ein Produkt einzigartig und ist eine Voraussetzung für die Wettbewerbsfähigkeit von Produktionsbetrieben."},en:{q:"What is the feature called that makes a product clearly and uniquely stand out from the competition?",a:["unique selling proposition","USP","unique selling point"],e:"The unique selling proposition (USP) makes a product unique and is a prerequisite for a manufacturer's competitiveness."},hu:{q:"Hogyan nevezzük azt a jellemzőt, amely révén egy termék egyértelműen és egyedi módon kiemelkedik a versenytársak közül?",a:["egyedi értékesítési ajánlat","USP","egyedi eladási ajánlat","egyedi értékajánlat","egyedi jellemző"],e:"Az egyedi értékesítési ajánlat (USP) teszi a terméket egyedivé, és a termelő vállalatok versenyképességének egyik feltétele."}}],"leistungserstellungsprozess-produktion":[{type:"tf",level:1,correct:!0,de:{q:"Bei der Vorratsproduktion (make to stock) wird nach der prognostizierten Absatzmenge produziert, noch bevor konkrete Kundenaufträge vorliegen",e:"Richtig. Vorratsproduktion orientiert sich an der Absatzprognose – das Unternehmen ist immer lieferfähig (z. B. Waschmittel). Bei der Auftragsproduktion wird erst nach Bestellung produziert."},en:{q:"In make-to-stock production, goods are produced according to the forecast sales volume before specific customer orders exist",e:"True. Make-to-stock follows the sales forecast, so the company can always deliver (e.g. detergent). In make-to-order production, goods are only produced once an order has been placed."},hu:{q:"Készletre gyártásnál (make to stock) az előrejelzett értékesítési mennyiség alapján gyártanak, még mielőtt konkrét vevői megrendelések lennének",e:"Igaz. A készletre gyártás az értékesítési előrejelzéshez igazodik, így a vállalat mindig szállítóképes (pl. mosószer). Megrendelésre gyártásnál csak a megrendelés után kezdődik a gyártás."}},{type:"tf",level:2,correct:!1,de:{q:"Die Rüstzeit gehört zur Übergangszeit, weil die Maschine in dieser Zeit noch nicht produziert",e:"Falsch. Die Rüstzeit (Maschine vorbereiten) gehört gemeinsam mit der Bearbeitungszeit zur Durchführungszeit. Die Übergangszeit besteht aus Liege- und Transportzeit."},en:{q:"Set-up time is part of the transition time because the machine is not yet producing during it",e:"False. Set-up time (preparing the machine) belongs, together with processing time, to the execution time. Transition time consists of waiting time and transport time."},hu:{q:"Az átállási idő az átmeneti időhöz tartozik, mert ezalatt a gép még nem termel",e:"Hamis. Az átállási idő (a gép előkészítése) a megmunkálási idővel együtt a végrehajtási időhöz tartozik. Az átmeneti idő a várakozási és a szállítási időből áll."}},{type:"tf",level:2,correct:!1,de:{q:"Eine Auslastung von 80 % bedeutet, dass die Kapazitätsnachfrage um 20 % über dem Kapazitätsangebot liegt",e:"Falsch. Auslastung = Kapazitätsnachfrage · 100 / Kapazitätsangebot. Bei 80 % werden nur 80 % der vorhandenen Kapazität gebraucht – 20 % sind frei. Überlastung liegt erst über 100 % vor."},en:{q:"A capacity utilisation of 80% means that capacity demand is 20% higher than capacity supply",e:"False. Utilisation = capacity demand · 100 / capacity supply. At 80%, only 80% of the available capacity is needed – 20% is idle. Overload only exists above 100%."},hu:{q:"A 80%-os kapacitáskihasználtság azt jelenti, hogy a kapacitásigény 20%-kal meghaladja a rendelkezésre álló kapacitást",e:"Hamis. Kihasználtság = kapacitásigény · 100 / rendelkezésre álló kapacitás. 80%-nál a meglévő kapacitásnak csak 80%-ára van szükség, 20% szabad. Túlterhelés csak 100% felett áll fenn."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Aussagen zur Vorwärtsterminierung treffen zu? Wähle alle zutreffenden.",o:["Die Produktion startet sofort nach Auftragseingang","Sie führt zum frühestmöglichen Endtermin","Fertige Produkte liegen oft auf Lager und binden Kapital","Sie verursacht die geringsten Lagerkosten","Es wird vom Liefertermin aus zurückgerechnet"],e:"Vorwärtsterminierung: sofort starten, frühester Endtermin, wenig Zeitdruck – aber Kapitalbindung durch Lager. Geringe Lagerkosten und das Zurückrechnen vom Liefertermin kennzeichnen die Rückwärtsterminierung."},en:{q:"Which statements about forward scheduling are correct? Select all that apply.",o:["Production starts immediately after the order is received","It leads to the earliest possible completion date","Finished products often sit in stock and tie up capital","It causes the lowest storage costs","Planning works backwards from the delivery date"],e:"Forward scheduling: start immediately, earliest completion date, little time pressure – but capital tied up in stock. Low storage costs and working backwards from the delivery date are features of backward scheduling."},hu:{q:"Mely állítások igazak az előre ütemezésre? Jelöld meg az összes helyeset.",o:["A gyártás közvetlenül a megrendelés beérkezése után indul","A lehető legkorábbi befejezési időponthoz vezet","A késztermékek gyakran raktáron állnak és tőkét kötnek le","Ez okozza a legalacsonyabb raktározási költséget","A szállítási határidőtől visszafelé számolnak"],e:"Előre ütemezés: azonnali kezdés, legkorábbi befejezés, kevés időnyomás – de a készlet tőkét köt le. Az alacsony raktározási költség és a szállítási határidőtől való visszaszámolás a visszafelé ütemezés jellemzője."}},{type:"multi",level:3,correct:[0,2,5],de:{q:"Eine Abteilung ist zu 120 % ausgelastet. Welche Maßnahmen sind QUANTITATIVE Anpassungen? Wähle alle zutreffenden.",o:["Eine zusätzliche Maschine anschaffen","Überstunden anordnen","Zusätzliches Personal einstellen","Mitarbeiter:innen weiterbilden, um schneller zu arbeiten","Liefertermine verschieben","Eine zweite Fertigungslinie in Betrieb nehmen"],e:"Quantitativ = mehr Maschinen oder mehr Personal. Überstunden und das Verschieben von Lieferterminen sind zeitliche Anpassungen, Weiterbildung zur Produktivitätssteigerung ist eine intensitätsmäßige Anpassung."},en:{q:"A department is running at 120% utilisation. Which measures are QUANTITATIVE adjustments? Select all that apply.",o:["Buying an additional machine","Ordering overtime","Hiring additional staff","Training employees so they work faster","Postponing delivery dates","Starting up a second production line"],e:"Quantitative = more machines or more staff. Overtime and postponing delivery dates are time-based adjustments; training to raise productivity is an intensity-based adjustment."},hu:{q:"Egy részleg kihasználtsága 120%. Mely intézkedések MENNYISÉGI alkalmazkodások? Jelöld meg az összes helyeset.",o:["Egy további gép beszerzése","Túlóra elrendelése","További munkaerő felvétele","A munkatársak továbbképzése a gyorsabb munkavégzés érdekében","A szállítási határidők elhalasztása","Egy második gyártósor üzembe helyezése"],e:"Mennyiségi alkalmazkodás = több gép vagy több munkaerő. A túlóra és a határidők elhalasztása időbeli alkalmazkodás, a termelékenységet növelő továbbképzés intenzitásbeli alkalmazkodás."}},{type:"order",level:2,de:{q:"Bringe die Schritte des Leistungserstellungsprozesses in die richtige Reihenfolge.",o:["Produktinnovation","Absatzplanung","Produktionsprogrammplanung","Materialbedarfsplanung","Planung des zeitlichen Ablaufs","Durchführung der Produktion"],e:"Zuerst wird das Produkt entwickelt, dann die verkaufbare Menge geschätzt. Daraus folgt das Produktionsprogramm (was, wann, wie viel), daraus der Materialbedarf, dann die zeitliche Planung und schließlich die Durchführung."},en:{q:"Put the steps of the production process in the correct order.",o:["Product innovation","Sales planning","Production programme planning","Material requirements planning","Scheduling of the process","Carrying out production"],e:"First the product is developed, then the saleable quantity is estimated. This leads to the production programme (what, when, how many), then the material requirements, then scheduling and finally production itself."},hu:{q:"Állítsd helyes sorrendbe a teljesítmény-előállítási folyamat lépéseit.",o:["Termékinnováció","Értékesítéstervezés","Termelésiprogram-tervezés","Anyagszükséglet-tervezés","Az időbeli lefolyás tervezése","A termelés végrehajtása"],e:"Először kifejlesztik a terméket, majd megbecsülik az eladható mennyiséget. Ebből következik a termelési program (mit, mikor, mennyit), ebből az anyagszükséglet, majd az időbeli tervezés, végül a végrehajtás."}},{type:"match",level:2,de:{q:"Ordne die Stufe des Qualitätsmanagements ihrem Kennzeichen zu.",p:[["Qualitätskontrolle","Stichproben am fertigen Produkt"],["Qualitätssicherung","Fehler schon während der Herstellung erkennen"],["Umfassendes Qualitätsmanagement","Alle Prozesse auf Kundenbedürfnisse ausrichten"],["Business Excellence","Beste Führung für alle Stakeholder"]],e:"Die Entwicklung verläuft vom Aussortieren fehlerhafter Endprodukte (Kontrolle) über die Überwachung des Prozesses (Sicherung) und die kundenorientierte Ausrichtung aller Prozesse bis zur ständigen Verbesserung für alle Stakeholder."},en:{q:"Match each stage of quality management with its key feature.",p:[["Quality control","Samples of the finished product"],["Quality assurance","Detecting defects during production"],["Total quality management","Aligning all processes with customer needs"],["Business excellence","Best management for all stakeholders"]],e:"The development goes from sorting out faulty end products (control), to monitoring the process (assurance), to aligning all processes with customers, up to continuous improvement for all stakeholders."},hu:{q:"Párosítsd a minőségirányítás fejlődési szakaszát a jellemzőjével.",p:[["Minőség-ellenőrzés","Szúrópróba a késztermékeken"],["Minőségbiztosítás","A hibák felismerése már gyártás közben"],["Teljes körű minőségirányítás","Minden folyamat a vevői igényekhez igazítva"],["Business Excellence","Kiváló vezetés minden érintett számára"]],e:"A fejlődés a hibás késztermékek kiválogatásától (ellenőrzés) a folyamat felügyeletén (biztosítás) és az összes folyamat vevőközpontú kialakításán át az összes érintett javát szolgáló folyamatos fejlesztésig tart."}},{type:"mc",level:2,correctIndex:3,de:{q:"Ein Bauunternehmen errichtet nach individueller Planung eine neue Brücke über die Enns. Material, Maschinen und Arbeitskräfte werden an den Bauplatz gebracht. Welche Kombination trifft zu?",o:["Serienfertigung und Fließbandfertigung","Massenfertigung und Werkstattfertigung","Serienfertigung und Gruppenfertigung","Einzelfertigung und Baustellenfertigung"],e:"Ein einziges Stück nach individuellen Vorgaben = Einzelfertigung (Fertigungsart). Weil alles zum Einsatzort gebracht wird, ist der Organisationstyp die Baustellenfertigung – wie beim Tunnelbau."},en:{q:"A construction company builds a new, individually designed bridge over the River Enns. Materials, machines and workers are brought to the site. Which combination applies?",o:["Batch production and assembly-line production","Mass production and workshop production","Batch production and group production","One-off production and site production"],e:"A single item built to individual specifications = one-off production (type of manufacturing). Because everything is brought to the place of use, the type of organisation is site production – as in tunnel building."},hu:{q:"Egy építőipari vállalat egyedi tervek alapján új hidat épít az Enns folyó felett. Az anyagot, a gépeket és a munkaerőt a helyszínre szállítják. Melyik kombináció igaz?",o:["Sorozatgyártás és futószalagos gyártás","Tömeggyártás és műhelyrendszerű gyártás","Sorozatgyártás és csoportos gyártás","Egyedi gyártás és helyszíni gyártás"],e:"Egyetlen darab egyedi igények szerint = egyedi gyártás (gyártási mód). Mivel mindent a felhasználás helyére visznek, a szervezési forma a helyszíni gyártás – mint az alagútépítésnél."}},{type:"mc",level:3,correctIndex:0,de:{q:"Ein Kunde bestellt am 1. März 500 Spezialventile mit Liefertermin 30. April. Der Betrieb will die Lagerkosten so gering wie möglich halten. Welche Terminierung passt, und welches Risiko entsteht?",o:["Rückwärtsterminierung – spätester Start, aber kein Zeitpuffer","Vorwärtsterminierung – sofortiger Start, geringste Lagerkosten","Rückwärtsterminierung – frühester Endtermin, viel Zeitpuffer","Vorwärtsterminierung – spätester Start, keine Kapitalbindung"],e:"Bei der Rückwärtsterminierung wird vom Liefertermin zurückgerechnet, die Produktion endet knapp vor der Lieferung – das spart Lagerkosten. Nachteil: Es gibt keinen Zeitpuffer, jede Störung gefährdet den Termin. Die Vorwärtsterminierung bindet dagegen Kapital im Lager."},en:{q:"On 1 March a customer orders 500 special valves for delivery on 30 April. The company wants to keep storage costs as low as possible. Which scheduling method fits, and what risk arises?",o:["Backward scheduling – latest start, but no time buffer","Forward scheduling – immediate start, lowest storage costs","Backward scheduling – earliest end date, plenty of buffer","Forward scheduling – latest start, no capital tied up"],e:"Backward scheduling works back from the delivery date, so production finishes just before delivery – this saves storage costs. Drawback: there is no time buffer, so any disruption puts the deadline at risk. Forward scheduling, by contrast, ties up capital in stock."},hu:{q:"Egy vevő március 1-jén 500 speciális szelepet rendel április 30-i szállítással. Az üzem a lehető legalacsonyabban akarja tartani a raktározási költséget. Melyik ütemezés illik ide, és milyen kockázattal jár?",o:["Visszafelé ütemezés – legkésőbbi kezdés, de nincs időtartalék","Előre ütemezés – azonnali kezdés, legkisebb raktározási költség","Visszafelé ütemezés – legkorábbi befejezés, sok időtartalék","Előre ütemezés – legkésőbbi kezdés, nincs tőkelekötés"],e:"Visszafelé ütemezésnél a szállítási határidőtől számolnak vissza, a gyártás közvetlenül a szállítás előtt fejeződik be – ez raktározási költséget takarít meg. Hátránya: nincs időtartalék, minden zavar veszélyezteti a határidőt. Az előre ütemezés viszont tőkét köt le a raktárban."}},{type:"number",level:1,value:115,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Die Spritzgussabteilung der Kunststoff GmbH hat im Mai ein Kapazitätsangebot von 2.000 Maschinenstunden. Die Aufträge erfordern 2.300 Maschinenstunden. Wie hoch ist die Auslastung in %?",e:"Auslastung = Kapazitätsnachfrage · 100 / Kapazitätsangebot = 2.300 · 100 / 2.000 = 115 %. Die Abteilung ist überlastet – es braucht eine zeitliche, quantitative oder intensitätsmäßige Anpassung."},en:{q:"In May, the injection moulding department of Kunststoff GmbH has a capacity supply of 2,000 machine hours. The orders require 2,300 machine hours. What is the capacity utilisation in %?",e:"Utilisation = capacity demand · 100 / capacity supply = 2,300 · 100 / 2,000 = 115%. The department is overloaded – a time-based, quantitative or intensity-based adjustment is needed."},hu:{q:"A Kunststoff GmbH fröccsöntő részlegének májusban 2000 gépóra kapacitása van. A megrendelések 2300 gépórát igényelnek. Hány százalék a kapacitáskihasználtság?",e:"Kihasználtság = kapacitásigény · 100 / rendelkezésre álló kapacitás = 2300 · 100 / 2000 = 115%. A részleg túlterhelt – időbeli, mennyiségi vagy intenzitásbeli alkalmazkodásra van szükség."}}],"investition-finanzierung-ueberblick":[{type:"tf",level:1,correct:!1,de:{q:"Die Passivseite der Bilanz zeigt, wofür das Kapital im Unternehmen verwendet wurde",e:"Falsch. Die Passiva zeigen die Mittelherkunft (woher kommt das Geld? → Finanzierung). Wofür es verwendet wurde (Mittelverwendung → Investition), zeigen die Aktiva."},en:{q:"The liabilities and equity side of the balance sheet shows what the capital was used for",e:"False. The liabilities and equity side shows the source of funds (where does the money come from? → financing). What it was used for (use of funds → investment) is shown on the assets side."},hu:{q:"A mérleg forrásoldala azt mutatja, mire használták fel a tőkét a vállalatban",e:"Hamis. A források a pénzeszközök eredetét mutatják (honnan származik a pénz? → finanszírozás). Azt, hogy mire használták fel (eszközfelhasználás → beruházás), az eszközoldal mutatja."}},{type:"tf",level:1,correct:!0,de:{q:"In jeder Bilanz ist das Gesamtvermögen genau gleich hoch wie das Gesamtkapital",e:"Richtig. Jeder Euro Vermögen (Aktiva) muss irgendwoher finanziert sein (Passiva) – deshalb gilt immer: Gesamtvermögen = Gesamtkapital."},en:{q:"In every balance sheet, total assets are exactly equal to total capital",e:"True. Every euro of assets must be financed from somewhere (liabilities and equity) – so total assets always equal total capital."},hu:{q:"Minden mérlegben az eszközök összege pontosan megegyezik a források összegével",e:"Igaz. Minden euró vagyont (eszközt) valahonnan finanszírozni kell (források) – ezért mindig érvényes: eszközök összesen = források összesen."}},{type:"tf",level:2,correct:!0,de:{q:"Ein Unternehmen mit hohem Gewinn kann trotzdem zahlungsunfähig werden",e:"Richtig. Gewinn ist nicht gleich Geld am Konto. Steckt das Geld z. B. in Investitionen, Vorräten oder offenen Forderungen, fehlt die Liquidität für Gehälter und Rechnungen."},en:{q:"A company with high profits can still become insolvent",e:"True. Profit is not the same as cash in the bank. If the money is tied up in investments, inventory or unpaid receivables, there is no liquidity left for salaries and bills."},hu:{q:"Egy magas nyereséget elérő vállalat is fizetésképtelenné válhat",e:"Igaz. A nyereség nem azonos a számlán lévő pénzzel. Ha a pénz pl. beruházásokban, készletekben vagy kintlévőségekben van lekötve, hiányzik a likviditás a bérek és a számlák kifizetéséhez."}},{type:"multi",level:3,correct:[0,1,3],de:{q:"Welche Bilanzposten gehören zum Fremdkapital? Wähle alle zutreffenden.",o:["Bankkredit","Verbindlichkeiten gegenüber Lieferanten","Gewinnrücklagen","Rückstellungen","Einlagen der Gesellschafter:innen"],e:"Fremdkapital umfasst Rückstellungen, Kredite und Verbindlichkeiten. Rücklagen und Einlagen gehören wie der Gewinn zum Eigenkapital."},en:{q:"Which balance sheet items are part of debt (borrowed capital)? Select all that apply.",o:["Bank loan","Trade payables to suppliers","Retained earnings reserves","Provisions","Shareholders' contributions"],e:"Debt comprises provisions, loans and payables. Reserves and contributions belong to equity, just like profit."},hu:{q:"Mely mérlegtételek tartoznak az idegen tőkéhez? Jelöld meg az összes helyeset.",o:["Bankhitel","Szállítókkal szembeni kötelezettségek","Eredménytartalék","Céltartalékok","A tagok (tulajdonosok) betétei"],e:"Az idegen tőke a céltartalékokat, a hiteleket és a kötelezettségeket foglalja magában. A tartalékok és a betétek a nyereséghez hasonlóan a saját tőkéhez tartoznak."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Aussagen zu Investition und Finanzierung treffen zu? Wähle alle zutreffenden.",o:["Investition beschreibt die Mittelverwendung","Finanzierung beschreibt die Mittelherkunft","Investitionen stehen auf der Passivseite","Erst die Finanzierung ermöglicht eine Investition","Das Eigenkapital ist ein Teil der Aktiva"],e:"Investition = wofür (Aktiva), Finanzierung = woher (Passiva); die Finanzierung ermöglicht die Investition. Investitionen stehen auf der Aktivseite, das Eigenkapital auf der Passivseite."},en:{q:"Which statements about investment and financing are correct? Select all that apply.",o:["Investment describes the use of funds","Financing describes the source of funds","Investments appear on the liabilities side","Financing is what makes an investment possible","Equity is part of the assets"],e:"Investment = what for (assets), financing = where from (liabilities and equity); financing makes investment possible. Investments appear on the assets side, equity on the liabilities and equity side."},hu:{q:"Mely állítások igazak a beruházásra és a finanszírozásra? Jelöld meg az összes helyeset.",o:["A beruházás az eszközfelhasználást írja le","A finanszírozás a források eredetét írja le","A beruházások a forrásoldalon szerepelnek","A finanszírozás teszi lehetővé a beruházást","A saját tőke az eszközök része"],e:"Beruházás = mire (eszközök), finanszírozás = honnan (források); a finanszírozás teszi lehetővé a beruházást. A beruházások az eszközoldalon, a saját tőke a forrásoldalon szerepel."}},{type:"order",level:1,de:{q:"Ordne die Ebenen der Finanzplanung von der langfristigsten zur kurzfristigsten.",o:["Normative Ebene: langfristige finanzielle Ziele festlegen","Strategische Ebene: Budgets planen, Investitionsprojekte bewerten","Operative Ebene: Kosten kontrollieren, Liquidität sichern"],e:"Normativ werden die langfristigen Ziele gesetzt, strategisch werden daraus Budgets und Investitionsprojekte abgeleitet, operativ geht es um die laufende Kostenkontrolle und die Zahlungsfähigkeit im Tagesgeschäft."},en:{q:"Order the levels of financial planning from the most long-term to the most short-term.",o:["Normative level: setting long-term financial goals","Strategic level: planning budgets, evaluating investment projects","Operational level: controlling costs, securing liquidity"],e:"At the normative level long-term goals are set; at the strategic level budgets and investment projects are derived from them; the operational level deals with day-to-day cost control and the ability to pay."},hu:{q:"Rendezd a pénzügyi tervezés szintjeit a leghosszabb távútól a legrövidebb távúig.",o:["Normatív szint: hosszú távú pénzügyi célok kitűzése","Stratégiai szint: költségvetés tervezése, beruházási projektek értékelése","Operatív szint: költségek ellenőrzése, likviditás biztosítása"],e:"Normatív szinten tűzik ki a hosszú távú célokat, stratégiai szinten ebből vezetik le a költségvetést és a beruházási projekteket, operatív szinten a folyamatos költségellenőrzésről és a napi fizetőképességről van szó."}},{type:"match",level:2,de:{q:"Ordne den Bilanzposten der richtigen Gruppe zu.",p:[["Patent","Immaterielles Anlagevermögen"],["Produktionsmaschine","Sachanlagen"],["Langfristige Beteiligung an einer GmbH","Finanzanlagen"],["Gewinnrücklage","Eigenkapital"],["Lieferantenverbindlichkeit","Fremdkapital"]],e:"Das Anlagevermögen gliedert sich in immaterielle Güter, Sachanlagen und Finanzanlagen (Aktiva). Rücklagen sind Eigenkapital, Verbindlichkeiten sind Fremdkapital (Passiva)."},en:{q:"Match each balance sheet item with the correct group.",p:[["Patent","Intangible fixed assets"],["Production machine","Tangible fixed assets"],["Long-term stake in a GmbH","Financial assets"],["Retained earnings reserve","Equity"],["Trade payable","Debt"]],e:"Fixed assets are divided into intangible assets, tangible assets and financial assets (assets side). Reserves are equity, payables are debt (liabilities and equity side)."},hu:{q:"Párosítsd a mérlegtételt a megfelelő csoporttal.",p:[["Szabadalom","Immateriális javak"],["Gyártógép","Tárgyi eszközök"],["Tartós részesedés egy GmbH-ban","Befektetett pénzügyi eszközök"],["Eredménytartalék","Saját tőke"],["Szállítói kötelezettség","Idegen tőke"]],e:"A befektetett eszközök immateriális javakra, tárgyi eszközökre és befektetett pénzügyi eszközökre tagolódnak (eszközoldal). A tartalékok a saját tőkéhez, a kötelezettségek az idegen tőkéhez tartoznak (forrásoldal)."}},{type:"mc",level:2,correctIndex:1,de:{q:"Loopy kauft für ihre Produktion eine Schokoladenanlage um 80.000 € und finanziert sie zur Gänze mit einem Bankkredit. Wie wirkt sich das auf die Bilanz aus?",o:["Aktiva +80.000 €, Eigenkapital +80.000 €","Aktiva +80.000 €, Fremdkapital +80.000 €","Aktiva unverändert, Fremdkapital +80.000 €","Aktiva −80.000 €, Fremdkapital +80.000 €"],e:"Die Anlage erhöht das Anlagevermögen (Investition, Aktiva), der Kredit erhöht das Fremdkapital (Finanzierung, Passiva) – beide Seiten wachsen um 80.000 €. Ein Kredit ist kein Eigenkapital."},en:{q:"Loopy buys a chocolate production line for €80,000 and finances it entirely with a bank loan. How does this affect the balance sheet?",o:["Assets +€80,000, equity +€80,000","Assets +€80,000, debt +€80,000","Assets unchanged, debt +€80,000","Assets −€80,000, debt +€80,000"],e:"The machine increases fixed assets (investment, assets side) and the loan increases debt (financing, liabilities side) – both sides grow by €80,000. A loan is not equity."},hu:{q:"Loopy 80 000 €-ért csokoládégyártó berendezést vásárol, és teljes egészében bankhitelből finanszírozza. Hogyan hat ez a mérlegre?",o:["Eszközök +80 000 €, saját tőke +80 000 €","Eszközök +80 000 €, idegen tőke +80 000 €","Eszközök változatlanok, idegen tőke +80 000 €","Eszközök −80 000 €, idegen tőke +80 000 €"],e:"A berendezés növeli a befektetett eszközöket (beruházás, eszközoldal), a hitel növeli az idegen tőkét (finanszírozás, forrásoldal) – mindkét oldal 80 000 €-val nő. A hitel nem saját tőke."}},{type:"mc",level:3,correctIndex:2,de:{q:"Loopy zahlt einen Bankkredit von 10.000 € vorzeitig von ihrem Bankguthaben zurück. Was passiert in der Bilanz?",o:["Nur das Fremdkapital sinkt, die Aktiva bleiben gleich","Das Eigenkapital sinkt um 10.000 €","Aktiva und Passiva sinken jeweils um 10.000 €","Die Bilanzsumme bleibt gleich, nur die Aktiva tauschen"],e:"Das Bankguthaben (Umlaufvermögen, Aktiva) und der Kredit (Fremdkapital, Passiva) sinken gleichzeitig um 10.000 € – die Bilanzsumme wird kürzer. Das Eigenkapital ist nicht betroffen, weil die Tilgung kein Aufwand ist."},en:{q:"Loopy repays a €10,000 bank loan early from her bank balance. What happens in the balance sheet?",o:["Only debt falls; assets stay the same","Equity falls by €10,000","Assets and liabilities each fall by €10,000","The total stays the same; only assets swap"],e:"The bank balance (current assets) and the loan (debt) fall at the same time by €10,000 – the balance sheet total shrinks. Equity is not affected because a repayment is not an expense."},hu:{q:"Loopy egy 10 000 €-s bankhitelt előtörleszt a bankszámlájáról. Mi történik a mérlegben?",o:["Csak az idegen tőke csökken, az eszközök változatlanok","A saját tőke 10 000 €-val csökken","Az eszközök és a források is 10 000 €-val csökkennek","A mérlegfőösszeg változatlan, csak eszközcsere történik"],e:"A bankbetét (forgóeszköz) és a hitel (idegen tőke) egyszerre csökken 10 000 €-val – a mérlegfőösszeg csökken. A saját tőkét nem érinti, mert a törlesztés nem ráfordítás."}},{type:"number",level:2,value:82e3,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Aus Loopys Bilanz: Vorräte 40.000 €, Forderungen aus Lieferungen 25.000 €, Bankguthaben 15.000 €, Kassa 2.000 €, Maschinen 120.000 €, Patent 10.000 €. Wie hoch ist das Umlaufvermögen?",e:"Zum Umlaufvermögen zählen Vorräte, Forderungen, Kassa und Bankguthaben: 40.000 + 25.000 + 15.000 + 2.000 = 82.000 €. Maschinen (Sachanlage) und Patent (immateriell) gehören zum Anlagevermögen."},en:{q:"From Loopy's balance sheet: inventory €40,000, trade receivables €25,000, bank balance €15,000, cash €2,000, machines €120,000, patent €10,000. What is the amount of current assets?",e:"Current assets include inventory, receivables, cash and bank balances: 40,000 + 25,000 + 15,000 + 2,000 = €82,000. Machines (tangible) and the patent (intangible) are fixed assets."},hu:{q:"Loopy mérlegéből: készletek 40 000 €, vevőkövetelések 25 000 €, bankbetét 15 000 €, pénztár 2000 €, gépek 120 000 €, szabadalom 10 000 €. Mekkora a forgóeszközök értéke?",e:"A forgóeszközökhöz a készletek, a követelések, a pénztár és a bankbetét tartozik: 40 000 + 25 000 + 15 000 + 2000 = 82 000 €. A gépek (tárgyi eszköz) és a szabadalom (immateriális jószág) a befektetett eszközök közé tartoznak."}}],investitionsmanagement:[{type:"tf",level:1,correct:!0,de:{q:"Der Kauf eines Patents ist eine immaterielle Investition",e:"Richtig. Nach dem Investitionsgut unterscheidet man Sachinvestitionen (z. B. Maschine), Finanzinvestitionen (Wertpapiere) und immaterielle Investitionen (z. B. Patente, Lizenzen)."},en:{q:"Buying a patent is an intangible investment",e:"True. By type of asset, we distinguish tangible investments (e.g. a machine), financial investments (securities) and intangible investments (e.g. patents, licences)."},hu:{q:"Egy szabadalom megvásárlása immateriális beruházás",e:"Igaz. A beruházás tárgya szerint megkülönböztetünk tárgyi beruházást (pl. gép), pénzügyi befektetést (értékpapírok) és immateriális beruházást (pl. szabadalmak, licencek)."}},{type:"tf",level:2,correct:!1,de:{q:"Die Amortisationsrechnung zeigt, welche Investition über die gesamte Nutzungsdauer den höchsten Gewinn bringt",e:"Falsch. Sie zeigt nur, wie schnell das eingesetzte Kapital zurückfließt (Risiko). Über den langfristigen Gewinn nach der Amortisation sagt sie nichts aus."},en:{q:"The payback method shows which investment generates the highest profit over its entire useful life",e:"False. It only shows how quickly the capital invested flows back (risk). It says nothing about long-term profit after the payback point."},hu:{q:"A megtérülési számítás megmutatja, melyik beruházás hozza a legnagyobb nyereséget a teljes hasznos élettartam alatt",e:"Hamis. Csak azt mutatja meg, milyen gyorsan térül meg a befektetett tőke (kockázat). A megtérülés utáni hosszú távú nyereségről semmit sem mond."}},{type:"tf",level:3,correct:!0,de:{q:"Haben zwei Anlagen unterschiedliche Ausbringungsmengen, müssen bei der Kostenvergleichsrechnung die Stückkosten statt der Gesamtkosten verglichen werden",e:"Richtig. Gesamtkosten sind nur bei gleicher Ausbringungsmenge vergleichbar. Sonst rechnet man Stückkosten = Gesamtkosten / Ausbringungsmenge – eine Anlage mit höheren Gesamtkosten kann pro Stück günstiger sein."},en:{q:"If two machines have different output volumes, the cost comparison method must compare unit costs instead of total costs",e:"True. Total costs are only comparable at equal output. Otherwise you calculate unit cost = total costs / output – a machine with higher total costs may be cheaper per unit."},hu:{q:"Ha két berendezés kibocsátása eltérő, a költség-összehasonlító számításnál az összköltség helyett a darabköltséget kell összehasonlítani",e:"Igaz. Az összköltségek csak azonos kibocsátás mellett hasonlíthatók össze. Egyébként darabköltséget számolunk = összköltség / kibocsátás – a magasabb összköltségű berendezés darabonként olcsóbb is lehet."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Welche Grenzen haben die statischen Investitionsrechenverfahren? Wähle alle zutreffenden.",o:["Sie betrachten nur eine (Durchschnitts-)Periode","Sie unterstellen gleichbleibende Kosten und Erlöse","Sie berücksichtigen den Zeitwert des Geldes nicht","Sie können keine Kosten vergleichen","Sie berücksichtigen nur qualitative Kriterien"],e:"Statische Verfahren rechnen mit Durchschnittswerten einer Periode, ohne Auf- und Abzinsung – dynamische Verfahren beheben das. Sie berücksichtigen nur quantitative Kriterien (Hard Facts); Soft Facts erfasst die Scoring-Methode."},en:{q:"What are the limitations of static investment appraisal methods? Select all that apply.",o:["They look at only one (average) period","They assume constant costs and revenues","They ignore the time value of money","They cannot compare costs","They consider only qualitative criteria"],e:"Static methods use average figures for one period without compounding or discounting – dynamic methods solve this. They consider only quantitative criteria (hard facts); soft facts are covered by the scoring method."},hu:{q:"Melyek a statikus beruházás-gazdaságossági számítások korlátai? Jelöld meg az összes helyeset.",o:["Csak egy (átlagos) időszakot vizsgálnak","Állandó költségeket és bevételeket feltételeznek","Nem veszik figyelembe a pénz időértékét","Nem tudnak költségeket összehasonlítani","Csak minőségi szempontokat vesznek figyelembe"],e:"A statikus módszerek egy időszak átlagértékeivel számolnak, kamatoztatás és diszkontálás nélkül – ezt a dinamikus módszerek küszöbölik ki. Csak mennyiségi szempontokat (hard facts) vesznek figyelembe; a soft factsot a pontozásos módszer kezeli."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Entscheidungskriterien sind qualitativ (Soft Facts)? Wähle alle zutreffenden.",o:["Umweltfreundlichkeit","Rückflussdauer","Zuverlässigkeit","Kapitaleinsatz","Arbeitsschutz","Rentabilität"],e:"Qualitative Kriterien sind nicht zahlenmäßig erfassbar: Umweltfreundlichkeit, Qualität, Zuverlässigkeit, Service, Arbeitsschutz. Rückflussdauer, Kapitaleinsatz und Rentabilität sind quantitative Hard Facts."},en:{q:"Which decision criteria are qualitative (soft facts)? Select all that apply.",o:["Environmental friendliness","Payback period","Reliability","Capital employed","Occupational safety","Return on investment"],e:"Qualitative criteria cannot be measured in numbers: environmental friendliness, quality, reliability, service, occupational safety. Payback period, capital employed and return are quantitative hard facts."},hu:{q:"Mely döntési szempontok minőségiek (soft facts)? Jelöld meg az összes helyeset.",o:["Környezetbarát jelleg","Megtérülési idő","Megbízhatóság","Tőkeráfordítás","Munkavédelem","Jövedelmezőség"],e:"A minőségi szempontok számszerűen nem mérhetők: környezetbarát jelleg, minőség, megbízhatóság, szerviz, munkavédelem. A megtérülési idő, a tőkeráfordítás és a jövedelmezőség mennyiségi hard facts."}},{type:"order",level:2,de:{q:"Bringe die Schritte der Scoring-Methode (Nutzwertanalyse) in die richtige Reihenfolge.",o:["Kriterien festlegen (quantitativ und qualitativ)","Kriterien gewichten (zusammen 100 %)","Alternativen mit Punkten bewerten","Punkte mit der Gewichtung multiplizieren und addieren","Alternative mit dem höchsten Nutzwert wählen"],e:"Erst die Kriterien bestimmen und gewichten, dann jede Alternative je Kriterium bepunkten. Punkte × Gewichtung ergibt den Nutzwert – die Alternative mit dem höchsten Nutzwert gewinnt."},en:{q:"Put the steps of the scoring method (utility analysis) in the correct order.",o:["Define criteria (quantitative and qualitative)","Weight the criteria (total 100%)","Award points to each alternative","Multiply points by weights and add up","Choose the alternative with the highest score"],e:"First define and weight the criteria, then score each alternative per criterion. Points × weight gives the utility value – the alternative with the highest value wins."},hu:{q:"Állítsd helyes sorrendbe a pontozásos módszer (hasznosságelemzés) lépéseit.",o:["Szempontok meghatározása (mennyiségi és minőségi)","Szempontok súlyozása (összesen 100%)","Az alternatívák pontozása","A pontok súllyal való szorzása és összeadása","A legmagasabb pontszámú alternatíva kiválasztása"],e:"Először meghatározzák és súlyozzák a szempontokat, majd szempontonként pontozzák az alternatívákat. Pont × súly adja a hasznossági értéket – a legmagasabb értékű alternatíva nyer."}},{type:"match",level:1,de:{q:"Ordne das Beispiel dem passenden Investitionsanlass zu.",p:[["Ein Hotel baut einen zusätzlichen Zimmertrakt","Erweiterungsinvestition"],["Ein Start-up kauft seine erste Büroausstattung","Neuinvestition"],["Ein defekter Lieferwagen wird durch den gleichen Typ ersetzt","Ersatzinvestition"],["Ein Roboter übernimmt das Verpacken und spart Kosten","Rationalisierungsinvestition"]],e:"Neu = erstmalig/Gründung, Ersatz = gleichartiger Ersatz, Rationalisierung = effizienter produzieren, Erweiterung = mehr Kapazität."},en:{q:"Match each example with the correct reason for investment.",p:[["A hotel builds an additional wing of rooms","Expansion investment"],["A start-up buys its first office equipment","Initial investment"],["A broken delivery van is replaced by the same model","Replacement investment"],["A robot takes over packing and cuts costs","Rationalisation investment"]],e:"Initial = first time/start-up, replacement = like-for-like, rationalisation = producing more efficiently, expansion = more capacity."},hu:{q:"Párosítsd a példát a beruházás megfelelő okával.",p:[["Egy szálloda új szárnyat épít további szobákkal","Bővítő beruházás"],["Egy startup megvásárolja első irodai berendezését","Új (alapító) beruházás"],["Egy elromlott kisteherautót ugyanolyan típusúra cserélnek","Pótló beruházás"],["Egy robot átveszi a csomagolást és költséget takarít meg","Racionalizálási beruházás"]],e:"Új beruházás = első alkalommal/alapításkor, pótló = azonos értékű csere, racionalizálási = hatékonyabb termelés, bővítő = nagyobb kapacitás."}},{type:"mc",level:2,correctIndex:0,de:{q:"Ein Hotel wählt zwischen zwei Kaffeevollautomaten mit gleichem Kapitaleinsatz. Der größere hat höhere Kosten, ermöglicht aber zusätzliche Erlöse durch Coffee-to-go. Welches statische Verfahren ist am besten geeignet?",o:["Gewinnvergleichsrechnung","Kostenvergleichsrechnung","Amortisationsrechnung","Kritische-Menge-Rechnung"],e:"Bei unterschiedlicher Kapazität bzw. unterschiedlichen Erlösen reicht der Kostenvergleich nicht – die Gewinnvergleichsrechnung bezieht die Erlöse mit ein. Bei gleichem Kapitaleinsatz bringt die Rentabilitätsrechnung keine zusätzliche Information."},en:{q:"A hotel is choosing between two fully automatic coffee machines with the same capital outlay. The larger one costs more but brings extra revenue from coffee-to-go. Which static method is most suitable?",o:["Profit comparison method","Cost comparison method","Payback method","Critical volume calculation"],e:"With different capacities or revenues, comparing costs is not enough – the profit comparison method includes revenues. With equal capital employed, a return calculation adds no extra information."},hu:{q:"Egy szálloda két azonos tőkeigényű automata kávégép közül választ. A nagyobb költségesebb, de a coffee-to-go révén többletbevételt hoz. Melyik statikus módszer a legmegfelelőbb?",o:["Nyereség-összehasonlító számítás","Költség-összehasonlító számítás","Megtérülési számítás","Kritikus mennyiség számítása"],e:"Eltérő kapacitás vagy bevétel esetén a költség-összehasonlítás nem elég – a nyereség-összehasonlító számítás a bevételeket is figyelembe veszi. Azonos tőkeráfordításnál a jövedelmezőségi számítás nem ad többletinformációt."}},{type:"mc",level:3,correctIndex:0,de:{q:"Maschine 1: Fixkosten 221.000 €/Jahr, variable Kosten 150 €/h. Maschine 2: Fixkosten 292.500 €/Jahr, variable Kosten 110 €/h. Die kritische Menge liegt bei 1.787,5 h. Loopy rechnet mit 2.200 Maschinenstunden pro Jahr. Welche Entscheidung ist richtig?",o:["Maschine 2, da über der kritischen Menge die variablen Kosten zählen","Maschine 1, weil sie bei jeder Auslastung die niedrigeren Fixkosten hat","Maschine 1, weil über der kritischen Menge die niedrigeren Fixkosten zählen","Egal, weil beide ab der kritischen Menge gleich hohe Kosten haben"],e:"Über der kritischen Menge ist die Alternative mit den niedrigeren variablen Kosten günstiger: Bei 2.200 h kostet Maschine 1 221.000 + 330.000 = 551.000 €, Maschine 2 292.500 + 242.000 = 534.500 €. Gleich hoch sind die Kosten nur genau bei 1.787,5 h."},en:{q:"Machine 1: fixed costs €221,000/year, variable costs €150/h. Machine 2: fixed costs €292,500/year, variable costs €110/h. The critical volume is 1,787.5 h. Loopy expects 2,200 machine hours per year. Which decision is correct?",o:["Machine 2, as above the critical volume variable costs matter","Machine 1, because it has the lower fixed costs at every utilisation","Machine 1, because above the critical volume lower fixed costs count","Either, because both cost the same once the critical volume is passed"],e:"Above the critical volume, the alternative with lower variable costs is cheaper: at 2,200 h machine 1 costs 221,000 + 330,000 = €551,000 and machine 2 costs 292,500 + 242,000 = €534,500. Costs are equal only at exactly 1,787.5 h."},hu:{q:"1. gép: fix költség 221 000 €/év, változó költség 150 €/óra. 2. gép: fix költség 292 500 €/év, változó költség 110 €/óra. A kritikus mennyiség 1787,5 óra. Loopy évi 2200 gépórával számol. Melyik döntés helyes?",o:["A 2. gép, mert a kritikus mennyiség felett a változó költség számít","Az 1. gép, mert minden kihasználtság mellett alacsonyabb a fix költsége","Az 1. gép, mert a kritikus mennyiség felett az alacsonyabb fix költség számít","Mindegy, mert a kritikus mennyiségtől kezdve mindkettő ugyanannyiba kerül"],e:"A kritikus mennyiség felett az alacsonyabb változó költségű alternatíva olcsóbb: 2200 óránál az 1. gép 221 000 + 330 000 = 551 000 €, a 2. gép 292 500 + 242 000 = 534 500 € költséget okoz. A költségek csak pontosan 1787,5 óránál egyenlők."}},{type:"number",level:3,value:2.6,tol:.01,unit:{de:"Jahre",en:"years",hu:"év"},de:{q:"Eine neue Abfüllanlage für Loopys Bonbons kostet 100.000 € (kein Restwert). Die jährlichen Rückflüsse (Gewinn + Abschreibung) sind unterschiedlich: Jahr 1: 30.000 €, Jahr 2: 40.000 €, Jahr 3: 50.000 €, Jahr 4: 50.000 €. Wie lange dauert die Amortisation nach der Kumulationsmethode? (auf 1 Kommastelle)",e:"Rückflüsse addieren: nach Jahr 1 30.000 €, nach Jahr 2 70.000 €. Es fehlen noch 30.000 €. Im 3. Jahr fließen 50.000 € zurück: 30.000 / 50.000 = 0,6 Jahre. Amortisationsdauer = 2 + 0,6 = 2,6 Jahre."},en:{q:"A new filling machine for Loopy's sweets costs €100,000 (no residual value). The annual cash returns (profit + depreciation) differ: year 1: €30,000, year 2: €40,000, year 3: €50,000, year 4: €50,000. What is the payback period using the cumulative method? (1 decimal place)",e:"Add up the returns: after year 1 €30,000, after year 2 €70,000. €30,000 is still missing. In year 3, €50,000 flows back: 30,000 / 50,000 = 0.6 years. Payback period = 2 + 0.6 = 2.6 years."},hu:{q:"Loopy cukorkáihoz egy új töltőberendezés 100 000 €-ba kerül (maradványérték nincs). Az éves visszaáramlások (nyereség + értékcsökkenés) eltérőek: 1. év: 30 000 €, 2. év: 40 000 €, 3. év: 50 000 €, 4. év: 50 000 €. Mennyi a megtérülési idő a kumulációs módszer szerint? (1 tizedesjegyre)",e:"A visszaáramlásokat összeadjuk: az 1. év után 30 000 €, a 2. év után 70 000 €. Még 30 000 € hiányzik. A 3. évben 50 000 € térül meg: 30 000 / 50 000 = 0,6 év. Megtérülési idő = 2 + 0,6 = 2,6 év."}}],finanzmanagement:[{type:"tf",level:1,correct:!1,de:{q:"Beim Leasing wird der Leasingnehmer mit der Übergabe des Objekts dessen Eigentümer",e:"Falsch. Leasing ist eine mittel- oder langfristige Miete: Eigentümer bleibt der Leasinggeber. Der Leasingnehmer nutzt das Objekt und zahlt dafür Leasingraten."},en:{q:"In leasing, the lessee becomes the owner of the asset when it is handed over",e:"False. Leasing is medium- or long-term renting: the lessor remains the owner. The lessee uses the asset and pays lease instalments for it."},hu:{q:"Lízing esetén a lízingbevevő az eszköz átadásával annak tulajdonosává válik",e:"Hamis. A lízing közép- vagy hosszú távú bérlet: a tulajdonos a lízingbeadó marad. A lízingbevevő használja az eszközt, és lízingdíjat fizet érte."}},{type:"tf",level:2,correct:!0,de:{q:"Bei einer stillen Zession erfährt der Kunde nicht, dass seine Schuld an die Bank abgetreten wurde",e:"Richtig. Bei der Forderungsabtretung (Zession) gibt es eine offene Form (Kunde wird informiert und zahlt an die Bank) und eine stille Form (Kunde zahlt weiter an das Unternehmen und erfährt nichts)."},en:{q:"In a silent assignment of receivables, the customer is not informed that the debt has been assigned to the bank",e:"True. An assignment of receivables can be open (the customer is informed and pays the bank) or silent (the customer keeps paying the company and is not told)."},hu:{q:"Csendes engedményezésnél a vevő nem tudja meg, hogy a vele szembeni követelést a bankra engedményezték",e:"Igaz. A követelésengedményezés lehet nyílt (a vevőt értesítik, és a banknak fizet) vagy csendes (a vevő továbbra is a vállalatnak fizet, és nem értesül róla)."}},{type:"tf",level:3,correct:!1,de:{q:"Im Konkurs werden Mezzaninkapitalgeber vor den übrigen Fremdkapitalgebern bedient, weil sie keine Sicherheiten haben",e:"Falsch. Mezzaninkapital ist nachrangig: Im Konkurs werden zuerst die übrigen Gläubiger bedient. Gerade wegen dieses höheren Risikos (keine Sicherheiten, Nachrang) gibt es eine gewinnabhängige, meist höhere Verzinsung."},en:{q:"In bankruptcy, mezzanine capital providers are paid before other lenders because they have no collateral",e:"False. Mezzanine capital is subordinated: in bankruptcy, the other creditors are paid first. It is precisely because of this higher risk (no collateral, subordination) that it pays profit-linked, usually higher interest."},hu:{q:"Csődeljárásban a mezzanine tőke nyújtói a többi hitelező előtt kapnak kifizetést, mert nincs biztosítékuk",e:"Hamis. A mezzanine tőke alárendelt: csődben előbb a többi hitelezőt elégítik ki. Éppen e magasabb kockázat (nincs biztosíték, alárendeltség) miatt nyereségfüggő, általában magasabb kamatot fizet."}},{type:"multi",level:3,correct:[0,2,4],de:{q:"Welche Finanzierungsformen zählen zur Außenfinanzierung? Wähle alle zutreffenden.",o:["Bankkredit","Selbstfinanzierung aus einbehaltenen Gewinnen","Kapital eines Business Angels","Rückstellungsfinanzierung","Mezzaninkapital","Finanzierung aus Abschreibungen"],e:"Außenfinanzierung kommt von externen Geldgebern: Kredite, Beteiligungen (z. B. Business Angel) und Mezzaninkapital. Selbst-, Rückstellungs- und Abschreibungsfinanzierung (Umschichtung) stammen aus der eigenen betrieblichen Tätigkeit – also Innenfinanzierung."},en:{q:"Which forms of financing are external financing? Select all that apply.",o:["Bank loan","Self-financing from retained profits","Capital from a business angel","Financing through provisions","Mezzanine capital","Financing from depreciation"],e:"External financing comes from outside providers: loans, equity stakes (e.g. a business angel) and mezzanine capital. Self-financing, provisions and depreciation (restructuring) come from the company's own operations – i.e. internal financing."},hu:{q:"Mely finanszírozási formák tartoznak a külső finanszírozáshoz? Jelöld meg az összes helyeset.",o:["Bankhitel","Önfinanszírozás a visszatartott nyereségből","Egy üzleti angyal tőkéje","Céltartalékokból történő finanszírozás","Mezzanine tőke","Értékcsökkenésből történő finanszírozás"],e:"A külső finanszírozás külső tőkeadóktól származik: hitelek, részesedések (pl. üzleti angyal) és mezzanine tőke. Az önfinanszírozás, a céltartalékokból és az értékcsökkenésből (átcsoportosítás) történő finanszírozás a saját üzleti tevékenységből ered – tehát belső finanszírozás."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Vorteile bringt eine hohe Eigenkapitalquote? Wähle alle zutreffenden.",o:["Größere Unabhängigkeit von Gläubigern","Auf Eigenkapital fallen keine Zinsen an","Bessere Bonität bei der Bank","Eigenkapitalgeber haben kein Mitspracherecht","Eigenkapital muss nach fixer Laufzeit zurückgezahlt werden"],e:"Viel Eigenkapital bedeutet Unabhängigkeit, keine Zinsen, leichteres Abdecken von Verlusten und bessere Kreditwürdigkeit. Eigenkapitalgeber haben aber Informations- und Mitspracherechte, und Eigenkapital ist unbefristet."},en:{q:"What are the advantages of a high equity ratio? Select all that apply.",o:["Greater independence from creditors","No interest is payable on equity","Better credit rating with the bank","Equity providers have no say in decisions","Equity must be repaid after a fixed term"],e:"A lot of equity means independence, no interest, losses are easier to absorb and better creditworthiness. Equity providers do, however, have information and co-determination rights, and equity has no fixed term."},hu:{q:"Milyen előnyökkel jár a magas saját tőke arány? Jelöld meg az összes helyeset.",o:["Nagyobb függetlenség a hitelezőktől","A saját tőke után nem kell kamatot fizetni","Jobb hitelminősítés a banknál","A saját tőke nyújtóinak nincs beleszólási joguk","A saját tőkét meghatározott futamidő után vissza kell fizetni"],e:"A sok saját tőke függetlenséget, kamatmentességet, a veszteségek könnyebb fedezését és jobb hitelképességet jelent. A saját tőke nyújtóinak viszont van tájékoztatási és beleszólási joguk, és a saját tőke határozatlan időre áll rendelkezésre."}},{type:"match",level:2,de:{q:"Ordne die Finanzierungsart ihrem Platz in der Finanzierungstabelle zu.",p:[["Selbstfinanzierung","Innenfinanzierung + Eigenfinanzierung"],["Rückstellungsfinanzierung","Innenfinanzierung + Fremdfinanzierung"],["Kreditfinanzierung","Außenfinanzierung + Fremdfinanzierung"],["Beteiligungsfinanzierung","Außenfinanzierung + Eigenfinanzierung"],["Umschichtungsfinanzierung","Innenfinanzierung, Mischform"]],e:"Herkunft (innen/außen) und Rechtsstellung des Kapitalgebers (Eigen/Fremd) bestimmen den Platz. Selbst-, Umschichtungs- und Rückstellungsfinanzierung sind innen; Beteiligungen und Kredite kommen von außen."},en:{q:"Match each type of financing with its place in the financing table.",p:[["Self-financing","Internal + equity financing"],["Financing through provisions","Internal + debt financing"],["Loan financing","External + debt financing"],["Equity participation financing","External + equity financing"],["Restructuring financing","Internal, hybrid form"]],e:"The source (internal/external) and the legal position of the provider (equity/debt) determine the place. Self-financing, restructuring and provisions are internal; equity stakes and loans come from outside."},hu:{q:"Párosítsd a finanszírozási formát a finanszírozási táblázatban elfoglalt helyével.",p:[["Önfinanszírozás","Belső + saját finanszírozás"],["Céltartalékokból történő finanszírozás","Belső + idegen finanszírozás"],["Hitelfinanszírozás","Külső + idegen finanszírozás"],["Részesedésfinanszírozás","Külső + saját finanszírozás"],["Átcsoportosításos finanszírozás","Belső, vegyes forma"]],e:"A helyet a tőke eredete (belső/külső) és a tőkeadó jogi helyzete (saját/idegen) határozza meg. Az önfinanszírozás, az átcsoportosítás és a céltartalékok belsők; a részesedések és a hitelek kívülről érkeznek."}},{type:"order",level:2,de:{q:"Bringe den Ablauf eines Leasinggeschäfts in die richtige Reihenfolge.",o:["Leasingnehmer einigt sich mit dem Händler über das Objekt","Kaufvertrag Händler–Leasinggeber und Leasingvertrag Leasinggeber–Leasingnehmer","Händler übergibt das Objekt an den Leasingnehmer","Leasinggeber zahlt den Kaufpreis an den Händler","Leasingnehmer zahlt laufend Leasingraten"],e:"Der Leasingnehmer sucht das Objekt aus, dann werden Kauf- und Leasingvertrag geschlossen. Nach der Übergabe bezahlt der Leasinggeber den Händler, und der Leasingnehmer zahlt ab dann die Raten."},en:{q:"Put the steps of a leasing transaction in the correct order.",o:["The lessee agrees on the asset with the dealer","Purchase contract dealer–lessor and lease contract lessor–lessee","The dealer hands the asset over to the lessee","The lessor pays the purchase price to the dealer","The lessee pays regular lease instalments"],e:"The lessee chooses the asset, then the purchase and lease contracts are concluded. After handover, the lessor pays the dealer, and from then on the lessee pays the instalments."},hu:{q:"Állítsd helyes sorrendbe egy lízingügylet lépéseit.",o:["A lízingbevevő megállapodik a kereskedővel az eszközről","Adásvételi szerződés kereskedő–lízingbeadó, lízingszerződés lízingbeadó–lízingbevevő","A kereskedő átadja az eszközt a lízingbevevőnek","A lízingbeadó kifizeti a vételárat a kereskedőnek","A lízingbevevő rendszeresen fizeti a lízingdíjakat"],e:"A lízingbevevő kiválasztja az eszközt, majd megkötik az adásvételi és a lízingszerződést. Az átadás után a lízingbeadó kifizeti a kereskedőt, a lízingbevevő pedig ettől kezdve fizeti a díjakat."}},{type:"mc",level:2,correctIndex:3,de:{q:"Die Druckerei Berger GmbH braucht kurzfristig 400.000 € Liquidität. Ihr Betriebsgebäude gehört ihr, sie möchte es aber unbedingt weiter nutzen. Welche Finanzierung passt am besten?",o:["Operating-Leasing einer neuen Druckmaschine","Stille Selbstfinanzierung durch stille Reserven","Lieferantenkredit mit längerem Zahlungsziel","Sale and Lease Back des Betriebsgebäudes"],e:"Bei Sale and Lease Back verkauft das Unternehmen das eigene Gebäude an einen Leasinggeber und least es sofort zurück – es fließt Geld zu, die Nutzung bleibt. Stille Reserven bringen erst beim Auflösen Geld, ein Lieferantenkredit reicht für 400.000 € kaum."},en:{q:"Berger GmbH, a printing company, needs €400,000 in liquidity at short notice. It owns its business premises but definitely wants to keep using them. Which financing fits best?",o:["Operating lease for a new printing press","Silent self-financing through hidden reserves","Supplier credit with a longer payment term","Sale and lease back of the business premises"],e:"With sale and lease back, the company sells its own building to a lessor and immediately leases it back – cash flows in and the company keeps using it. Hidden reserves only bring cash when released, and supplier credit is hardly enough for €400,000."},hu:{q:"A Berger GmbH nyomda rövid időn belül 400 000 € likviditásra szorul. Az üzemépület a saját tulajdona, de mindenképpen tovább akarja használni. Melyik finanszírozás a legmegfelelőbb?",o:["Egy új nyomdagép operatív lízingje","Csendes önfinanszírozás rejtett tartalékokból","Szállítói hitel hosszabb fizetési határidővel","Az üzemépület sale and lease back konstrukciója"],e:"Sale and lease back esetén a vállalat eladja saját épületét egy lízingbeadónak, és azonnal visszalízingeli – pénz folyik be, a használat megmarad. A rejtett tartalékok csak feloldáskor hoznak pénzt, a szállítói hitel pedig aligha elég 400 000 €-hoz."}},{type:"mc",level:3,correctIndex:0,de:{q:"Die Tischlerei Holzmann GmbH braucht einen langfristigen Kredit über 300.000 € für eine neue Werkshalle. Sie besitzt ein unbelastetes Betriebsgrundstück. Welche Sicherheit wird die Bank am ehesten verlangen?",o:["Eine Hypothek, eingetragen im Grundbuch","Einen Lombard auf das Betriebsgrundstück","Einen Eigentumsvorbehalt an der Werkshalle","Eine stille Zession des Grundstücks"],e:"Ein Pfandrecht an Grundstücken ist eine Hypothek und wird im Grundbuch eingetragen. Der Lombard betrifft nur bewegliche Güter (Gold, Wertpapiere), der Eigentumsvorbehalt sichert Lieferanten, und eine Zession betrifft Forderungen, keine Grundstücke."},en:{q:"Holzmann GmbH, a joinery, needs a long-term loan of €300,000 for a new workshop building. It owns an unencumbered business property. Which collateral is the bank most likely to require?",o:["A mortgage entered in the land register","A lombard pledge on the business property","Retention of title to the workshop building","A silent assignment of the property"],e:"A lien on land is a mortgage and is entered in the land register. A lombard pledge only covers movable goods (gold, securities), retention of title protects suppliers, and an assignment covers receivables, not land."},hu:{q:"A Holzmann GmbH asztalosüzemnek hosszú lejáratú, 300 000 €-s hitelre van szüksége egy új üzemcsarnokhoz. Tulajdonában van egy tehermentes üzemi telek. Milyen biztosítékot fog a bank a legvalószínűbben kérni?",o:["Telekkönyvbe bejegyzett jelzálogot","Lombardzálogot az üzemi telekre","Tulajdonjog-fenntartást az üzemcsarnokon","A telek csendes engedményezését"],e:"Az ingatlanon alapított zálogjog a jelzálog, amelyet az ingatlan-nyilvántartásba (telekkönyvbe) jegyeznek be. A lombard csak ingóságokra vonatkozik (arany, értékpapírok), a tulajdonjog-fenntartás a szállítókat védi, az engedményezés pedig követelésekre, nem ingatlanokra vonatkozik."}},{type:"number",level:1,value:225,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy überzieht ihr Geschäftskonto 45 Tage lang um 20.000 €. Die Bank verrechnet 9 % Sollzinsen p. a. Wie hoch sind die Zinsen? (Zinsformel mit 36 000)",e:"Zinsen = Kapital · Zinssatz · Tage / 36 000 = 20.000 · 9 · 45 / 36 000 = 225 €. Ein Kontokorrentkredit eignet sich deshalb nur für kurzfristige Engpässe."},en:{q:"Loopy overdraws her business account by €20,000 for 45 days. The bank charges 9% debit interest p.a. How much interest is due? (interest formula with 36,000)",e:"Interest = capital · rate · days / 36,000 = 20,000 · 9 · 45 / 36,000 = €225. An overdraft facility is therefore only suitable for short-term shortfalls."},hu:{q:"Loopy 45 napon át 20 000 €-val lépi túl üzleti számláját. A bank évi 9% hitelkamatot számít fel. Mennyi a kamat? (kamatképlet 36 000-rel)",e:"Kamat = tőke · kamatláb · napok / 36 000 = 20 000 · 9 · 45 / 36 000 = 225 €. A folyószámlahitel ezért csak rövid távú pénzhiány áthidalására alkalmas."}}],"finanzplan-analyse":[{type:"tf",level:1,correct:!0,de:{q:"Der Zahlungsmittelendbestand eines Monats ist im Finanzplan der Anfangsbestand des nächsten Monats",e:"Richtig. Der Finanzplan wird fortlaufend geführt: Anfangsbestand + Einzahlungen − Auszahlungen ± Ausgleichsmaßnahmen = Endbestand, der in den Folgemonat übernommen wird."},en:{q:"In the financial plan, a month's closing cash balance is the opening balance of the following month",e:"True. The financial plan is rolled forward: opening balance + receipts − payments ± balancing measures = closing balance, which is carried over to the next month."},hu:{q:"A pénzügyi tervben egy hónap pénzeszköz-záróállománya a következő hónap nyitóállománya",e:"Igaz. A pénzügyi tervet folyamatosan vezetik: nyitóállomány + befizetések − kifizetések ± kiegyenlítő intézkedések = záróállomány, amelyet átvisznek a következő hónapra."}},{type:"tf",level:2,correct:!1,de:{q:"Ein negatives Working Capital ist ein gutes Zeichen, weil dann wenig Kapital im Umlaufvermögen gebunden ist",e:"Falsch. Working Capital = Umlaufvermögen − kurzfristige Verbindlichkeiten und soll positiv sein. Ist es negativ, reicht das kurzfristig verfügbare Vermögen nicht, um die kurzfristigen Schulden zu bezahlen."},en:{q:"A negative working capital is a good sign because little capital is then tied up in current assets",e:"False. Working capital = current assets − short-term liabilities and should be positive. If it is negative, short-term assets are not enough to pay short-term debts."},hu:{q:"A negatív nettó forgótőke jó jel, mert ilyenkor kevés tőke van lekötve a forgóeszközökben",e:"Hamis. Nettó forgótőke = forgóeszközök − rövid lejáratú kötelezettségek, és pozitívnak kell lennie. Ha negatív, a rövid távon mozgósítható vagyon nem elég a rövid lejáratú tartozások kifizetésére."}},{type:"tf",level:3,correct:!0,de:{q:"Bei der Gesamtkapitalrentabilität werden die Fremdkapitalzinsen zum Ergebnis vor Steuern addiert, weil auch das Fremdkapital im Nenner steht",e:"Richtig. Das Gesamtkapital umfasst Eigen- und Fremdkapital. Die FK-Zinsen sind die Verzinsung des Fremdkapitals – deshalb gilt: (EGT + FK-Zinsen) · 100 / Gesamtkapital. Bei der EK-Rentabilität wird nur das EGT verwendet."},en:{q:"For return on total capital, interest on debt is added to the profit before tax because debt is also included in the denominator",e:"True. Total capital includes equity and debt. Interest on debt is the return paid on borrowed capital – hence (profit before tax + interest on debt) · 100 / total capital. Return on equity uses profit before tax only."},hu:{q:"Az összes tőke arányos jövedelmezőségnél az idegen tőke kamatait hozzáadják az adózás előtti eredményhez, mert a nevezőben az idegen tőke is szerepel",e:"Igaz. Az összes tőke saját és idegen tőkéből áll. Az idegen tőke kamata az idegen tőke hozama – ezért: (adózás előtti eredmény + kamatok) · 100 / összes tőke. A saját tőke arányos jövedelmezőségnél csak az adózás előtti eredményt használják."}},{type:"multi",level:1,correct:[0,1,3],de:{q:"Welche Positionen sind im Finanzplan Einzahlungen? Wähle alle zutreffenden.",o:["Bezahlte Rechnungen von Kund:innen","Auszahlung eines neuen Bankkredits an das Unternehmen","Abschreibung der Maschinen","Verkauf einer alten Anlage","Gehaltszahlungen","Rückzahlung eines Kredits"],e:"Einzahlungen erhöhen den Zahlungsmittelbestand: Umsätze, Anlagenverkäufe, Kredite, Eigenkapital. Gehälter und Kreditrückzahlungen sind Auszahlungen; Abschreibungen sind Aufwand, aber gar keine Zahlung."},en:{q:"Which items are cash receipts in the financial plan? Select all that apply.",o:["Invoices paid by customers","A new bank loan paid out to the company","Depreciation of machines","Sale of an old machine","Salary payments","Repayment of a loan"],e:"Receipts increase the cash balance: sales, asset disposals, loans, equity. Salaries and loan repayments are payments; depreciation is an expense but not a payment at all."},hu:{q:"Mely tételek befizetések a pénzügyi tervben? Jelöld meg az összes helyeset.",o:["Vevők által kifizetett számlák","Egy új bankhitel folyósítása a vállalatnak","A gépek értékcsökkenése","Egy régi berendezés eladása","Bérkifizetések","Hitel visszafizetése"],e:"A befizetések növelik a pénzeszközök állományát: árbevétel, eszközeladás, hitelfelvétel, saját tőke. A bérek és a hiteltörlesztés kifizetések; az értékcsökkenés ráfordítás, de egyáltalán nem pénzmozgás."}},{type:"multi",level:2,correct:[1,3,5],de:{q:"Welche Kennzahlen beschreiben die Kapitalstruktur (Passivseite) eines Unternehmens? Wähle alle zutreffenden.",o:["Anlagenintensität","Eigenkapitalquote","Liquidität 1. Grades","Verschuldungskoeffizient","Cashflow-Quote","Fremdkapitalquote"],e:"Die Kapitalstruktur zeigt, wie sich das Kapital zusammensetzt: EK-Quote, FK-Quote und Verschuldungskoeffizient (FK / EK). Anlagenintensität beschreibt die Vermögensstruktur, Liquidität und Cashflow-Quote sind Liquiditäts- bzw. Erfolgskennzahlen."},en:{q:"Which ratios describe a company's capital structure (liabilities side)? Select all that apply.",o:["Fixed asset intensity","Equity ratio","Cash ratio (1st degree liquidity)","Debt-to-equity ratio","Cash flow margin","Debt ratio"],e:"Capital structure shows how capital is made up: equity ratio, debt ratio and debt-to-equity ratio (debt / equity). Fixed asset intensity describes the asset structure; liquidity and cash flow margin are liquidity and earnings ratios."},hu:{q:"Mely mutatók írják le egy vállalat tőkeszerkezetét (forrásoldal)? Jelöld meg az összes helyeset.",o:["A befektetett eszközök aránya","Saját tőke aránya","Elsőfokú likviditás","Eladósodottsági mutató (idegen tőke / saját tőke)","Cash-flow-ráta","Idegen tőke aránya"],e:"A tőkeszerkezet a tőke összetételét mutatja: saját tőke aránya, idegen tőke aránya és eladósodottsági mutató (idegen tőke / saját tőke). A befektetett eszközök aránya a vagyonszerkezetet írja le, a likviditás és a cash-flow-ráta likviditási, illetve jövedelmezőségi mutató."}},{type:"order",level:1,de:{q:"Bringe die Zeilen eines Finanzplans in die richtige Reihenfolge.",o:["Zahlungsmittelanfangsbestand","+ geplante Einzahlungen","− geplante Auszahlungen","= Überschuss bzw. Fehlbetrag","Ausgleichsmaßnahmen","= Zahlungsmittelendbestand"],e:"Man startet mit dem Bestand an Kassa und Bank, addiert die Einzahlungen und zieht die Auszahlungen ab. Auf einen Überschuss oder Fehlbetrag reagiert man mit Ausgleichsmaßnahmen – das Ergebnis ist der Endbestand."},en:{q:"Put the lines of a financial plan in the correct order.",o:["Opening cash balance","+ planned receipts","− planned payments","= surplus or shortfall","Balancing measures","= closing cash balance"],e:"You start with the cash and bank balance, add receipts and subtract payments. A surplus or shortfall is answered with balancing measures – the result is the closing balance."},hu:{q:"Állítsd helyes sorrendbe a pénzügyi terv sorait.",o:["Pénzeszközök nyitóállománya","+ tervezett befizetések","− tervezett kifizetések","= többlet, illetve hiány","Kiegyenlítő intézkedések","= Pénzeszközök záróállománya"],e:"A pénztár- és bankállományból indulunk, hozzáadjuk a befizetéseket, és levonjuk a kifizetéseket. A többletre vagy hiányra kiegyenlítő intézkedésekkel reagálunk – az eredmény a záróállomány."}},{type:"match",level:2,de:{q:"Ordne die Kennzahl ihrer Formel zu.",p:[["Anlagenintensität","Anlagevermögen · 100 / Gesamtvermögen"],["Verschuldungskoeffizient","Fremdkapital / Eigenkapital"],["Working Capital","Umlaufvermögen − kurzfr. Verbindlichkeiten"],["Liquidität 2. Grades","(ZM + kurzfr. Forderungen) · 100 / kurzfr. Verb."],["Eigenkapitalrentabilität","EGT · 100 / Eigenkapital"]],e:"Intensitäten beziehen sich auf das Gesamtvermögen, Liquiditätsgrade auf die kurzfristigen Verbindlichkeiten. Die EK-Rentabilität setzt das Ergebnis vor Steuern (EGT) ins Verhältnis zum Eigenkapital."},en:{q:"Match each ratio with its formula.",p:[["Fixed asset intensity","Fixed assets · 100 / total assets"],["Debt-to-equity ratio","Debt / equity"],["Working capital","Current assets − short-term liabilities"],["Quick ratio (2nd degree)","(Cash + ST receivables) · 100 / ST liabilities"],["Return on equity","Profit before tax · 100 / equity"]],e:"Intensity ratios relate to total assets, liquidity ratios to short-term liabilities. Return on equity relates profit before tax to equity."},hu:{q:"Párosítsd a mutatót a képletével.",p:[["A befektetett eszközök aránya","Befektetett eszközök · 100 / összes eszköz"],["Eladósodottsági mutató","Idegen tőke / saját tőke"],["Nettó forgótőke","Forgóeszközök − rövid lejáratú kötelezettségek"],["Másodfokú likviditás","(Pénzeszközök + rövid lej. követelések) · 100 / rövid lej. köt."],["Saját tőke arányos jövedelmezőség","Adózás előtti eredmény · 100 / saját tőke"]],e:"Az arányszámok az összes eszközre, a likviditási mutatók a rövid lejáratú kötelezettségekre vonatkoznak. A saját tőke arányos jövedelmezőség az adózás előtti eredményt viszonyítja a saját tőkéhez."}},{type:"mc",level:2,correctIndex:2,de:{q:"Die Metallbau Steiner GmbH finanziert eine neue Produktionshalle mit 30 Jahren Nutzungsdauer vollständig über ihren Kontokorrentkredit. Wie ist das zu beurteilen?",o:["Sinnvoll, weil der Kontokorrentkredit der günstigste Kredit ist","Unproblematisch, solange die Eigenkapitalquote über 10 % liegt","Verstoß gegen die Goldene Finanzierungsregel – zu kurzfristig","Richtig, weil die Halle zum Umlaufvermögen gehört"],e:"Langfristiges Vermögen soll mit langfristigem Kapital finanziert werden (Anlagendeckung ≥ 100 %). Der Kontokorrentkredit ist kurzfristig und teuer. Die Halle ist Anlagevermögen, kein Umlaufvermögen."},en:{q:"Steiner GmbH, a metalworking firm, finances a new production hall with a useful life of 30 years entirely through its overdraft facility. How should this be assessed?",o:["Sensible, because the overdraft is the cheapest type of loan","No problem as long as the equity ratio is above 10%","Breach of the golden rule of financing – too short-term","Correct, because the hall is part of current assets"],e:"Long-term assets should be financed with long-term capital (fixed asset coverage ≥ 100%). An overdraft is short-term and expensive. The hall is a fixed asset, not a current asset."},hu:{q:"A Steiner GmbH fémszerkezet-gyártó egy 30 éves hasznos élettartamú új gyártócsarnokot teljes egészében folyószámlahitelből finanszíroz. Hogyan értékelhető ez?",o:["Észszerű, mert a folyószámlahitel a legolcsóbb hitel","Nem gond, amíg a saját tőke aránya 10% felett van","Sérti a finanszírozási aranyszabályt – túl rövid lejáratú","Helyes, mert a csarnok a forgóeszközökhöz tartozik"],e:"A hosszú távú vagyont hosszú távú tőkéből kell finanszírozni (befektetett eszközök fedezettsége ≥ 100%). A folyószámlahitel rövid lejáratú és drága. A csarnok befektetett eszköz, nem forgóeszköz."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopys Bilanz: Zahlungsmittel 20.000 €, kurzfristige Forderungen 48.000 €, Vorräte 60.000 €, kurzfristige Verbindlichkeiten 80.000 €. Wie hoch ist die Liquidität 2. Grades und wie ist sie zu beurteilen?",o:["85 % – unter dem Zielwert von 100–120 %","160 % – im Zielbereich von 150–200 %","25 % – im Zielbereich von 20–50 %","110 % – im Zielbereich von 100–120 %"],e:"Liquidität 2. Grades = (20.000 + 48.000) · 100 / 80.000 = 85 %. Das liegt unter dem Ziel von 100–120 % – die kurzfristigen Schulden sind ohne Vorräte nicht gedeckt. 160 % wäre die Liquidität 3. Grades, 25 % die Liquidität 1. Grades."},en:{q:"Loopy's balance sheet: cash €20,000, short-term receivables €48,000, inventory €60,000, short-term liabilities €80,000. What is the 2nd degree liquidity and how should it be assessed?",o:["85% – below the target of 100–120%","160% – within the target of 150–200%","25% – within the target of 20–50%","110% – within the target of 100–120%"],e:"2nd degree liquidity = (20,000 + 48,000) · 100 / 80,000 = 85%. This is below the target of 100–120% – short-term debts are not covered without inventory. 160% would be 3rd degree liquidity, 25% 1st degree liquidity."},hu:{q:"Loopy mérlege: pénzeszközök 20 000 €, rövid lejáratú követelések 48 000 €, készletek 60 000 €, rövid lejáratú kötelezettségek 80 000 €. Mekkora a másodfokú likviditás, és hogyan értékelhető?",o:["85% – a 100–120%-os célérték alatt","160% – a 150–200%-os célsávon belül","25% – a 20–50%-os célsávon belül","110% – a 100–120%-os célsávon belül"],e:"Másodfokú likviditás = (20 000 + 48 000) · 100 / 80 000 = 85%. Ez a 100–120%-os cél alatt van – a rövid lejáratú tartozások a készletek nélkül nincsenek fedezve. A 160% a harmadfokú, a 25% az elsőfokú likviditás lenne."}},{type:"number",level:2,value:6e4,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopys Jahresabschluss: Jahresüberschuss 40.000 €, Abschreibungen 25.000 €, Auflösung von Rückstellungen 5.000 €. Wie hoch ist der operative Cashflow (indirekte Methode)?",e:"Operativer Cashflow = Jahresüberschuss + nicht auszahlungswirksame Aufwendungen − nicht einzahlungswirksame Erträge = 40.000 + 25.000 − 5.000 = 60.000 €. Abschreibungen mindern den Gewinn, aber nicht das Geld; die Auflösung der Rückstellung erhöht den Gewinn ohne Einzahlung."},en:{q:"Loopy's annual accounts: net profit €40,000, depreciation €25,000, release of provisions €5,000. What is the operating cash flow (indirect method)?",e:"Operating cash flow = net profit + non-cash expenses − non-cash income = 40,000 + 25,000 − 5,000 = €60,000. Depreciation reduces profit but not cash; releasing a provision increases profit without any cash coming in."},hu:{q:"Loopy éves beszámolója: adózott eredmény (nyereség) 40 000 €, értékcsökkenés 25 000 €, céltartalék feloldása 5000 €. Mekkora a működési cash flow (közvetett módszer)?",e:"Működési cash flow = nyereség + nem pénzkiadással járó ráfordítások − nem pénzbevétellel járó bevételek = 40 000 + 25 000 − 5000 = 60 000 €. Az értékcsökkenés csökkenti a nyereséget, de a pénzt nem; a céltartalék feloldása pénzbevétel nélkül növeli a nyereséget."}}],"businessplan-3jg":[{type:"tf",level:1,correct:!0,de:{q:"Steigen die Fixkosten bei gleicher DBU-Quote, steigt auch der Break-even-Umsatz",e:"Richtig. Break-even-Umsatz = Fixkosten / DBU-Quote. Höhere Fixkosten (z. B. höhere Miete) müssen durch mehr Umsatz gedeckt werden, bevor ein Gewinn entsteht."},en:{q:"If fixed costs rise while the contribution margin ratio stays the same, the break-even revenue also rises",e:"True. Break-even revenue = fixed costs / contribution margin ratio. Higher fixed costs (e.g. higher rent) must be covered by more revenue before any profit is made."},hu:{q:"Ha változatlan fedezeti hányad mellett nőnek a fix költségek, a fedezeti ponthoz tartozó árbevétel is nő",e:"Igaz. Fedezeti árbevétel = fix költségek / fedezeti hányad. A magasabb fix költségeket (pl. magasabb bérleti díjat) több árbevétellel kell fedezni, mielőtt nyereség keletkezik."}},{type:"tf",level:2,correct:!1,de:{q:"Eine Privatentnahme der Einzelunternehmerin ist ein Aufwand und verringert daher den buchhalterischen Gewinn",e:"Falsch. Eine Privatentnahme ist eine Auszahlung, aber kein Aufwand – sie senkt das Geld am Konto, nicht den Gewinn. Deshalb gilt: Gewinn ≠ Liquidität."},en:{q:"A private withdrawal by a sole trader is an expense and therefore reduces the accounting profit",e:"False. A private withdrawal is a cash payment but not an expense – it reduces the money in the account, not the profit. That is why profit ≠ liquidity."},hu:{q:"Az egyéni vállalkozó magáncélú kivétele ráfordítás, ezért csökkenti a számviteli nyereséget",e:"Hamis. A magáncélú kivét pénzkiadás, de nem ráfordítás – a számlán lévő pénzt csökkenti, nem a nyereséget. Ezért nyereség ≠ likviditás."}},{type:"tf",level:3,correct:!1,de:{q:"Am Break-even-Point ist der Deckungsbeitrag genau null",e:"Falsch. Am Break-even-Point ist der GEWINN null. Der Deckungsbeitrag (Umsatz − variable Kosten) ist dort genau so hoch wie die Fixkosten – er deckt sie vollständig ab."},en:{q:"At the break-even point, the contribution margin is exactly zero",e:"False. At the break-even point, PROFIT is zero. The contribution margin (revenue − variable costs) there equals the fixed costs exactly – it covers them completely."},hu:{q:"A fedezeti pontban a fedezeti hozzájárulás pontosan nulla",e:"Hamis. A fedezeti pontban a NYERESÉG nulla. A fedezeti hozzájárulás (árbevétel − változó költségek) ott pontosan megegyezik a fix költségekkel – teljesen fedezi azokat."}},{type:"multi",level:1,correct:[0,2,3,5],de:{q:"Ein Café plant seinen Sach- und Personalaufwand. Welche Posten gehören dazu? Wähle alle zutreffenden.",o:["Miete für das Lokal","Kauf der Siebträger-Kaffeemaschine","Werbung","Lohnnebenkosten der Mitarbeiter:innen","Rückzahlung des Bankdarlehens","Energiekosten"],e:"Sach- und Personalaufwand sind laufende Aufwände wie Miete, Werbung, Energie, Löhne und Lohnnebenkosten. Die Kaffeemaschine ist eine Investition (über die Abschreibung erfasst), die Darlehenstilgung ist eine Auszahlung, aber kein Aufwand."},en:{q:"A café is planning its operating and personnel expenses. Which items belong to them? Select all that apply.",o:["Rent for the premises","Purchase of the espresso machine","Advertising","Employer's payroll costs","Repayment of the bank loan","Energy costs"],e:"Operating and personnel expenses are ongoing expenses such as rent, advertising, energy, wages and payroll costs. The coffee machine is an investment (recorded through depreciation); repaying the loan is a payment, but not an expense."},hu:{q:"Egy kávézó megtervezi dologi és személyi jellegű ráfordításait. Mely tételek tartoznak ide? Jelöld meg az összes helyeset.",o:["Az üzlethelyiség bérleti díja","A karos kávégép megvásárlása","Reklám","A munkatársak bérjárulékai","A bankkölcsön visszafizetése","Energiaköltségek"],e:"A dologi és személyi jellegű ráfordítások folyamatos ráfordítások, mint a bérleti díj, a reklám, az energia, a bérek és bérjárulékok. A kávégép beruházás (az értékcsökkenésen keresztül jelenik meg), a hiteltörlesztés pénzkiadás, de nem ráfordítás."}},{type:"multi",level:2,correct:[1,2,4],de:{q:"Welche Aussagen zu Erfolgs- und Liquiditätsplanung treffen zu? Wähle alle zutreffenden.",o:["Ein Gewinn in der Plan-GuV garantiert genug Geld am Konto","Abschreibungen mindern den Gewinn, aber nicht die Liquidität","Eine Darlehensaufnahme erhöht die Liquidität, aber nicht den Gewinn","Kredittilgungen verringern den Gewinn","Die Liquiditätsplanung stellt Ein- und Auszahlungen gegenüber"],e:"Erfolgsplanung = Erträge − Aufwände, Liquiditätsplanung = Einzahlungen − Auszahlungen. Abschreibungen sind Aufwand ohne Auszahlung, Darlehen sind Einzahlungen ohne Ertrag, Tilgungen Auszahlungen ohne Aufwand – deshalb ist Gewinn ≠ Geld am Konto."},en:{q:"Which statements about profit planning and liquidity planning are correct? Select all that apply.",o:["A profit in the planned P&L guarantees enough money in the account","Depreciation reduces profit but not liquidity","Taking out a loan increases liquidity but not profit","Loan repayments reduce profit","Liquidity planning compares cash receipts and payments"],e:"Profit planning = income − expenses, liquidity planning = receipts − payments. Depreciation is an expense without a payment, loans are receipts without income, repayments are payments without an expense – which is why profit ≠ cash in the account."},hu:{q:"Mely állítások igazak az eredménytervezésre és a likviditástervezésre? Jelöld meg az összes helyeset.",o:["A tervezett eredménykimutatásban szereplő nyereség garantálja, hogy elég pénz lesz a számlán","Az értékcsökkenés csökkenti a nyereséget, de a likviditást nem","A hitelfelvétel növeli a likviditást, de a nyereséget nem","A hiteltörlesztés csökkenti a nyereséget","A likviditástervezés a befizetéseket és a kifizetéseket állítja szembe"],e:"Eredménytervezés = bevételek − ráfordítások, likviditástervezés = befizetések − kifizetések. Az értékcsökkenés pénzkiadás nélküli ráfordítás, a hitel bevétel nélküli befizetés, a törlesztés ráfordítás nélküli kifizetés – ezért nyereség ≠ pénz a számlán."}},{type:"order",level:2,de:{q:"Bringe die Zeilen der Liquiditätsplanung (Cashflow-Planung) im Businessplan in die richtige Reihenfolge.",o:["Ergebnis vor Steuern","+ Abschreibungen","− aufgelöste Subventionen","= Cashflow","− Investitionen ± Darlehen + Subventionen − Steuern − Privatentnahmen","= Veränderung der Liquidität"],e:"Vom Ergebnis ausgehend werden nicht zahlungswirksame Posten korrigiert (Abschreibungen addieren, aufgelöste Subventionen abziehen) – das ergibt den Cashflow. Danach folgen Investitionen, Darlehen, Subventionen, Einkommensteuer und Privatentnahmen."},en:{q:"Put the lines of liquidity planning (cash flow planning) in the business plan in the correct order.",o:["Profit before tax","+ depreciation","− released subsidies","= cash flow","− investments ± loans + subsidies − tax − private withdrawals","= change in liquidity"],e:"Starting from profit, non-cash items are adjusted (add depreciation, subtract released subsidies) – giving the cash flow. Then come investments, loans, subsidies, income tax and private withdrawals."},hu:{q:"Állítsd helyes sorrendbe az üzleti terv likviditástervének (cash-flow-tervének) sorait.",o:["Adózás előtti eredmény","+ értékcsökkenés","− feloldott támogatások","= cash flow","− beruházások ± hitelek + támogatások − adó − magáncélú kivétek","= a likviditás változása"],e:"Az eredményből kiindulva korrigálják a pénzmozgással nem járó tételeket (értékcsökkenés hozzáadása, feloldott támogatások levonása) – ez adja a cash flow-t. Ezután következnek a beruházások, hitelek, támogatások, a jövedelemadó és a magáncélú kivétek."}},{type:"match",level:1,de:{q:"Ordne die Größe aus der Finanzplanung ihrer Berechnung zu.",p:[["Planumsatz","Nettoverkaufspreis · geplante Absatzmenge"],["Rohertrag","Umsatz − Wareneinsatz"],["DBU-Quote","Deckungsbeitrag · 100 / Umsatz"],["Break-even-Umsatz","Fixkosten / DBU-Quote"],["Jährliche Abschreibung","Anschaffungswert / Nutzungsdauer"]],e:"Diese fünf Formeln bilden das Rechengerüst der Finanzplanung im Businessplan – vom geplanten Umsatz über die Abschreibung bis zur Gewinnschwelle."},en:{q:"Match each figure from financial planning with its calculation.",p:[["Planned revenue","Net selling price · planned sales volume"],["Gross profit","Revenue − cost of goods sold"],["Contribution margin ratio","Contribution margin · 100 / revenue"],["Break-even revenue","Fixed costs / contribution margin ratio"],["Annual depreciation","Acquisition cost / useful life"]],e:"These five formulas form the calculation framework of financial planning in the business plan – from planned revenue and depreciation to the break-even point."},hu:{q:"Párosítsd a pénzügyi terv mutatóját a kiszámítási módjával.",p:[["Tervezett árbevétel","Nettó eladási ár · tervezett értékesítési mennyiség"],["Bruttó haszon (árrés)","Árbevétel − eladott áruk beszerzési értéke"],["Fedezeti hányad","Fedezeti hozzájárulás · 100 / árbevétel"],["Fedezeti árbevétel","Fix költségek / fedezeti hányad"],["Éves értékcsökkenés","Bekerülési érték / hasznos élettartam"]],e:"Ez az öt képlet adja az üzleti terv pénzügyi tervezésének számítási vázát – a tervezett árbevételtől az értékcsökkenésen át a fedezeti pontig."}},{type:"mc",level:2,correctIndex:1,de:{q:"Lena gründet einen Fahrradladen mit einem Kapitalbedarf von 120.000 €. Ihre Bank verlangt eine Eigenkapitalquote von mindestens 20 %. Wie viel Eigenkapital muss sie mindestens aufbringen?",o:["20.000 €","24.000 €","30.000 €","12.000 €"],e:"20 % von 120.000 € = 0,20 · 120.000 = 24.000 €. Den Rest von 96.000 € kann sie z. B. über Förderungen (aws), ein Darlehen und einen Kontokorrentkredit finanzieren."},en:{q:"Lena is founding a bicycle shop with a capital requirement of €120,000. Her bank requires an equity ratio of at least 20%. What is the minimum amount of equity she must contribute?",o:["€20,000","€24,000","€30,000","€12,000"],e:"20% of €120,000 = 0.20 · 120,000 = €24,000. She can finance the remaining €96,000 e.g. through subsidies (aws), a loan and an overdraft facility."},hu:{q:"Lena kerékpárboltot alapít 120 000 € tőkeigénnyel. A bankja legalább 20%-os saját tőke arányt követel. Legalább mennyi saját tőkét kell előteremtenie?",o:["20 000 €","24 000 €","30 000 €","12 000 €"],e:"120 000 € 20%-a = 0,20 · 120 000 = 24 000 €. A fennmaradó 96 000 €-t pl. támogatásokból (aws), kölcsönből és folyószámlahitelből finanszírozhatja."}},{type:"mc",level:3,correctIndex:2,de:{q:"Die Plan-GuV eines neuen Cafés zeigt im ersten Jahr 15.000 € Gewinn, die Abschreibungen betragen 8.000 €. Trotzdem sinkt laut Liquiditätsplan das Geld am Konto. Was ist die wahrscheinlichste Ursache?",o:["Die Abschreibungen sind höher als im Vorjahr geplant","Ein Teil der Subventionen wurde als Einzahlung erfasst","Tilgung und Privatentnahmen übersteigen den Cashflow","Der Wareneinsatz wurde als Ertrag verbucht"],e:"Cashflow = 15.000 + 8.000 = 23.000 €. Sinkt die Liquidität trotzdem, müssen Auszahlungen ohne Aufwand (Kredittilgung, Privatentnahmen, Investitionen, Einkommensteuer) größer sein. Abschreibungen erhöhen den Cashflow sogar, und eine Subventions-Einzahlung würde die Liquidität erhöhen."},en:{q:"The planned P&L of a new café shows a first-year profit of €15,000, with depreciation of €8,000. Yet according to the liquidity plan, the money in the account falls. What is the most likely cause?",o:["Depreciation is higher than planned for the previous year","Part of the subsidies was recorded as a cash receipt","Loan repayments and private withdrawals exceed the cash flow","Cost of goods sold was booked as income"],e:"Cash flow = 15,000 + 8,000 = €23,000. If liquidity still falls, payments that are not expenses (loan repayment, private withdrawals, investments, income tax) must be larger. Depreciation actually increases cash flow, and a subsidy received would increase liquidity."},hu:{q:"Egy új kávézó tervezett eredménykimutatása az első évben 15 000 € nyereséget mutat, az értékcsökkenés 8000 €. A likviditási terv szerint mégis csökken a pénz a számlán. Mi a legvalószínűbb ok?",o:["Az értékcsökkenés magasabb, mint az előző évre tervezett","A támogatások egy részét befizetésként rögzítették","A törlesztés és a magáncélú kivétek meghaladják a cash flow-t","Az eladott áruk beszerzési értékét bevételként könyvelték"],e:"Cash flow = 15 000 + 8000 = 23 000 €. Ha a likviditás mégis csökken, akkor a ráfordításnak nem minősülő kifizetések (hiteltörlesztés, magáncélú kivét, beruházás, jövedelemadó) nagyobbak. Az értékcsökkenés még növeli is a cash flow-t, egy támogatás befizetése pedig növelné a likviditást."}},{type:"number",level:3,value:14e4,tol:1,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy plant als Einzelunternehmerin einen zweiten Laden: Umsatz 180.000 €, variable Kosten 72.000 €, Fixkosten 54.000 €. Als fiktiven Unternehmerlohn rechnet sie mit Privatentnahmen von 24.000 € und Einkommensteuer von 6.000 €. Wie hoch ist der Break-even-Umsatz?",e:"DB = 180.000 − 72.000 = 108.000 €; DBU-Quote = 108.000 / 180.000 = 60 %. Fixkosten inkl. Unternehmerlohn = 54.000 + 24.000 + 6.000 = 84.000 €. Break-even-Umsatz = 84.000 / 0,60 = 140.000 €. Ohne Unternehmerlohn käme man fälschlich auf 90.000 €."},en:{q:"Loopy, as a sole trader, is planning a second shop: revenue €180,000, variable costs €72,000, fixed costs €54,000. As a notional entrepreneur's salary she allows for private withdrawals of €24,000 and income tax of €6,000. What is the break-even revenue?",e:"CM = 180,000 − 72,000 = €108,000; CM ratio = 108,000 / 180,000 = 60%. Fixed costs incl. entrepreneur's salary = 54,000 + 24,000 + 6,000 = €84,000. Break-even revenue = 84,000 / 0.60 = €140,000. Without the entrepreneur's salary you would wrongly get €90,000."},hu:{q:"Loopy egyéni vállalkozóként második üzletet tervez: árbevétel 180 000 €, változó költségek 72 000 €, fix költségek 54 000 €. Kalkulatív vállalkozói bérként 24 000 € magáncélú kivéttel és 6000 € jövedelemadóval számol. Mekkora a fedezeti ponthoz tartozó árbevétel?",e:"Fedezeti hozzájárulás = 180 000 − 72 000 = 108 000 €; fedezeti hányad = 108 000 / 180 000 = 60%. Fix költségek a vállalkozói bérrel = 54 000 + 24 000 + 6000 = 84 000 €. Fedezeti árbevétel = 84 000 / 0,60 = 140 000 €. A vállalkozói bér nélkül tévesen 90 000 € jönne ki."}}]},o=e(t,n,a,i,s,r);export{o as default};
